{"command": "cd /workspace && python3 -c "
import json
c=json.load(open('contracts/openapi.contract.json'))
for n,s in c['components']['schemas'].items():
    print('=== SCHEMA', n); print(json.dumps(s, indent=1))
" > /tmp/schemas.txt; wc -l /tmp/schemas.txt; head -400 /tmp/schemas.txt", "security_risk": "LOW", "summary": "Dump contract schemas"}

