action.command:
cd /workspace && cat > /tmp/summ.py <<'EOF'
import json
c=json.load(open('contracts/openapi.contract.json'))
def fmt(s, ind=0):
    pad='  '*ind
    if '$ref' in s: return pad+'-> '+s['$ref'].split('/')[-1]
    if 'allOf' in s: return pad+'allOf['+', '.join(x.get('$ref','?').split('/')[-1] for x in s['allOf'])+']'
    if 'oneOf' in s: return pad+'oneOf['+', '.join(x.get('$ref','?').split('/')[-1] for x in s['oneOf'])+']'
    t=s.get('type')
    if t=='object':
        req=set(s.get('required',[]))
        out=[pad+'{ addl='+str(s.get('additionalProperties','?'))]
        for k,v in s.get('properties',{}).items():
            star='*' if k in req else ''
            out.append(pad+'  '+k+star+': '+fmt(v,ind+2).strip())
        out.append(pad+'}')
        return '\n'.join(out)
    if t=='array':
        return pad+'[ '+fmt(s.get('items',{}),ind+1).strip()+' ]'
    extra=''
    for k in ('enum','format','minimum','maximum','minLength','maxLength','default','minItems'):
        if k in s: extra+=' '+k+'='+json.dumps(s[k])
    return pad+str(t)+extra
for p,ops in c['paths'].items():
    for m,o in ops.items():
        if m not in ('get','post','put','patch','delete'): continue
        print('########', m.upper(), p, o.get('operationId'), 'sec=',o.get('security'))
        if o.get('description') or o.get('summary'): print('  DESC:', o.get('summary'), o.get('description'))
        for prm in o.get('parameters',[]):
            print('  PARAM', prm['in'], prm['name'], 'req=',prm.get('required'), fmt(prm.get('schema',{})))
        rb=o.get('requestBody')
        if rb:
            print('  BODY required=',rb.get('required'))
            print(fmt(rb['content']['application/json']['schema'],2))
        for code,r in o['responses'].items():
            cont=r.get('content',{})
            sch=cont.get('application/json',{}).get('schema') if cont else None
            if sch is None:
                print('  RESP',code, list(cont.keys()), r.get('description'))
                continue
            if code.startswith('2'):
                print('  RESP',code)
                print(fmt(sch,2))
            else:
                codes=sch.get('properties',{}).get('code',{}).get('enum')
                print('  ERR',code,codes)
EOF
python3 /tmp/summ.py > /tmp/ops_summary.txt; wc -l /tmp/ops_summary.txt; sed -n 1,300p /tmp/ops_summary.txt

