)

type State struct {
	Users       map[string]*User
	Sessions    map[string]*Session
	Locations   map[string]*Location
	Connections map[string]*Connection
	SampleTypes map[string]*SampleType
	Requests    map[string]*Request
	Samples     map[string]*Sample
	Journeys    map[string]*Journey
	Assignments map[string]*Assignment
	Handoffs    map[string]*Handoff
	Reservations map[string]*Reservation
	Checkpoints map[string]*Checkpoint
	Disruptions map[string]*Disruption
	Idempotency map[string]*IdempotencyRecord
	Meta        *Meta
}

func newState() *State {
	return &State{
		Users: map[string]*User{}, Sessions: map[string]*Session{}, Locations: map[string]*Location{},
		Connections: map[string]*Connection{}, SampleTypes: map[string]*SampleType{}, Requests: map[string]*Request{},
		Samples: map[string]*Sample{}, Journeys: map[string]*Journey{}, Assignments: map[string]*Assignment{},
		Handoffs: map[string]*Handoff{}, Reservations: map[string]*Reservation{}, Checkpoints: map[string]*Checkpoint{},
		Disruptions: map[string]*Disruption{}, Idempotency: map[string]*IdempotencyRecord{},
		Meta: &Meta{ID: "meta"},
	}
}

func loadTable[T any](ctx context.Context, st *store.Store, table string, key func(*T) string, into map[string]*T) error {
	docs, err := st.LoadAll(ctx, table)
	if err != nil {
		return err
	}
	for _, d := range docs {
		var v T
		if err := json.Unmarshal(d, &v); err != nil {
			return fmt.Errorf("decode %s: %w", table, err)
		}
		into[key(&v)] = &v
	}
	return nil
}

func loadState(ctx context.Context, st *store.Store) (*State, error) {
	s := newState()
	if err := loadTable(ctx, st, "users", func(u *User) string { return u.ID }, s.Users); err != nil {
		return nil, err
	}
	if err := loadTable(ctx, st, "sessions", func(u *Session) string { return u.Token }, s.Sessions); err != nil {
		return nil, err
	}
	if err := loadTable(ctx, st, "locations", func(u *Location) string { return u.ID }, s.Locations); err != nil {
		return nil, err
	}
	if err := loadTable(ctx, st, "connections", func(u *Connection) string { return u.ID }, s.Connections); err != nil {
		return nil, err
	}
	if err := loadTable(ctx, st, "sample_types", func(u *SampleType) string { return u.ID }, s.SampleTypes); err != nil {
		return nil, err
	}
	if err := loadTable(ctx, st, "requests", func(u *Request) string { return u.ID }, s.Requests); err != nil {
		return nil, err
	}
	if err := loadTable(ctx, st, "samples", func(u *Sample) string { return u.ID }, s.Samples); err != nil {
		return nil, err
	}
	if err := loadTable(ctx, st, "journeys", func(u *Journey) string { return u.ID }, s.Journeys); err != nil {
		return nil, err
	}
	if err := loadTable(ctx, st, "assignments", func(u *Assignment) string { return u.ID }, s.Assignments); err != nil {
		return nil, err
	}
	if err := loadTable(ctx, st, "handoffs", func(u *Handoff) string { return u.ID }, s.Handoffs); err != nil {
		return nil, err
	}
