		return nil, err
	}
	if err := loadTable(ctx, st, "checkpoints", func(u *Checkpoint) string { return u.ID }, s.Checkpoints); err != nil {
		return nil, err
	}
	if err := loadTable(ctx, st, "disruptions", func(u *Disruption) string { return u.ID }, s.Disruptions); err != nil {
		return nil, err
	}
	if err := loadTable(ctx, st, "idempotency", func(u *IdempotencyRecord) string { return u.Key }, s.Idempotency); err != nil {
		return nil, err
	}
