func (tx *Tx) MarkMeta()                      { tx.mark("app_meta", "meta", tx.st.Meta) }

func (tx *Tx) hasChanges() bool {
	return len(tx.marks) > 0 || len(tx.audits) > 0 || len(tx.events) > 0
}

func (tx *Tx) actorID() string {
	if tx.actor == nil {
		return "system"
	}
	return tx.actor.ID
}

// Audit records an audit entry; sampleID may be empty.
func (tx *Tx) Audit(action, entityType, entityID, sampleID string, success bool, details map[string]any) {
