// Event records a timeline entry on the sample and an audit entry.
func (tx *Tx) SampleEvent(s *Sample, action, entityType, entityID string, details map[string]any) {
	if details == nil {
		details = map[string]any{}
	}
	role := tx.role
	if role == "" {
		role = "system"
	}
