func (tx *Tx) Emit(typ, entityType, entityID string, payload map[string]any) {
	if payload == nil {
		payload = map[string]any{}
	}
	tx.events = append(tx.events, &store.EventRow{Type: typ, EntityType: entityType, EntityID: entityID, Payload: payload, CreatedAt: tx.now})
}

func (tx *Tx) commit(ctx context.Context) error {
	for table, m := range tx.marks {
		tx.dirty[table] = map[string][]byte{}
		for id, doc := range m {
			b, err := json.Marshal(doc)
			if err != nil {
				return err
			}
			tx.dirty[table][id] = b
		}
	}
	if err := tx.app.store.Commit(ctx, tx.dirty, tx.audits, tx.events); err != nil {
		return err
	}
