type State struct {
	Users       map[string]*User
	Sessions    map[string]*Session
	Locations   map[string]*Location
	Connections map[string]*Connection
	SampleTypes map[string]*SampleType
	Requests    map[string]*Request
	Samples     map[string]*Sample
	Journeys    map[string]*Journey
	Assignments map[string]*Assignment
	Handoffs    map[string]*Handoff
	Reservations map[string]*Reservation
	Checkpoints map[string]*Checkpoint
	Disruptions map[string]*Disruption
	Idempotency map[string]*IdempotencyRecord
	Meta        *Meta
}

func newState() *State {
	return &State{
		Users: map[string]*User{}, Sessions: map[string]*Session{}, Locations: map[string]*Location{},
		Connections: map[string]*Connection{}, SampleTypes: map[string]*SampleType{}, Requests: map[string]*Request{},
		Samples: map[string]*Sample{}, Journeys: map[string]*Journey{}, Assignments: map[string]*Assignment{},
		Handoffs: map[string]*Handoff{}, Reservations: map[string]*Reservation{}, Checkpoints: map[string]*Checkpoint{},
		Disruptions: map[string]*Disruption{}, Idempotency: map[string]*IdempotencyRecord{},
		Meta: &Meta{ID: "meta"},
	}
}

func loadTable[T any](ctx context.Context, st *store.Store, table string, key func(*T) string, into map[string]*T) error {
	docs, err := st.LoadAll(ctx, table)
	if err != nil {
		return err
	}
	for _, d := range docs {
		var v T
		if err := json.Unmarshal(d, &v); err != nil {
			return fmt.Errorf("decode %s: %w", table, err)
		}
		into[key(&v)] = &v
	}
	return nil
}

func loadState(ctx context.Context, st *store.Store) (*State, error) {
	s := newState()
	if err := loadTable(ctx, st, "users", func(u *User) string { return u.ID }, s.Users); err != nil {
		return nil, err
	}
	if err := loadTable(ctx, st, "sessions", func(u *Session) string { return u.Token }, s.Sessions); err != nil {
		return nil, err
	}
	if err := loadTable(ctx, st, "locations", func(u *Location) string { return u.ID }, s.Locations); err != nil {
		return nil, err
	}
	if err := loadTable(ctx, st, "connections", func(u *Connection) string { return u.ID }, s.Connections); err != nil {
		return nil, err
	}
	if err := loadTable(ctx, st, "sample_types", func(u *SampleType) string { return u.ID }, s.SampleTypes); err != nil {
		return nil, err
	}
	if err := loadTable(ctx, st, "requests", func(u *Request) string { return u.ID }, s.Requests); err != nil {
		return nil, err
	}
	if err := loadTable(ctx, st, "samples", func(u *Sample) string { return u.ID }, s.Samples); err != nil {
		return nil, err
	}
	if err := loadTable(ctx, st, "journeys", func(u *Journey) string { return u.ID }, s.Journeys); err != nil {
		return nil, err
	}
	if err := loadTable(ctx, st, "assignments", func(u *Assignment) string { return u.ID }, s.Assignments); err != nil {
		return nil, err
	}
	if err := loadTable(ctx, st, "handoffs", func(u *Handoff) string { return u.ID }, s.Handoffs); err != nil {
		return nil, err
	}
	if err := loadTable(ctx, st, "reservations", func(u *Reservation) string { return u.ID }, s.Reservations); err != nil {
		return nil, err
	}
	if err := loadTable(ctx, st, "checkpoints", func(u *Checkpoint) string { return u.ID }, s.Checkpoints); err != nil {
		return nil, err
	}
	if err := loadTable(ctx, st, "disruptions", func(u *Disruption) string { return u.ID }, s.Disruptions); err != nil {
		return nil, err
	}
	if err := loadTable(ctx, st, "idempotency", func(u *IdempotencyRecord) string { return u.Key }, s.Idempotency); err != nil {
		return nil, err
	}
	metas := map[string]*Meta{}
	if err := loadTable(ctx, st, "app_meta", func(u *Meta) string { return u.ID }, metas); err != nil {
		return nil, err
	}
	if m, ok := metas["meta"]; ok {
		s.Meta = m
	}
	return s, nil
}

// Tx is a unit of work: it records which in-memory documents were mutated so
// they can be written through to PostgreSQL atomically together with audit
// entries and realtime events.
type Tx struct {
	app    *App
	st     *State
	now    time.Time
	actor  *User
	role   string
	dirty  map[string]map[string][]byte
	marks  map[string]map[string]any
	audits []*store.AuditRow
	events []*store.EventRow
}

func (a *App) newTx(actor *User, role string) *Tx {
	return &Tx{app: a, st: a.state, now: time.Now().UTC(), actor: actor, role: role,
		dirty: map[string]map[string][]byte{}, marks: map[string]map[string]any{}}
}

func (tx *Tx) mark(table, id string, doc any) {
	if tx.marks[table] == nil {
		tx.marks[table] = map[string]any{}
	}
	tx.marks[table][id] = doc
}

func (tx *Tx) MarkUser(u *User)               { tx.mark("users", u.ID, u) }
func (tx *Tx) MarkSession(s *Session)         { tx.mark("sessions", s.Token, s) }
func (tx *Tx) MarkLocation(l *Location)       { tx.mark("locations", l.ID, l) }
func (tx *Tx) MarkConnection(c *Connection)   { tx.mark("connections", c.ID, c) }
func (tx *Tx) MarkSampleType(t *SampleType)   { tx.mark("sample_types", t.ID, t) }
func (tx *Tx) MarkRequest(r *Request)         { tx.mark("requests", r.ID, r) }
func (tx *Tx) MarkSample(s *Sample)           { s.UpdatedAt = tx.now; tx.mark("samples", s.ID, s) }
func (tx *Tx) MarkJourney(j *Journey)         { j.UpdatedAt = tx.now; tx.mark("journeys", j.ID, j) }
func (tx *Tx) MarkAssignment(a *Assignment)   { a.UpdatedAt = tx.now; tx.mark("assignments", a.ID, a) }
func (tx *Tx) MarkHandoff(h *Handoff)         { tx.mark("handoffs", h.ID, h) }
func (tx *Tx) MarkReservation(r *Reservation) { tx.mark("reservations", r.ID, r) }
func (tx *Tx) MarkCheckpoint(c *Checkpoint)   { tx.mark("checkpoints", c.ID, c) }
func (tx *Tx) MarkDisruption(d *Disruption)   { tx.mark("disruptions", d.ID, d) }
func (tx *Tx) MarkIdempotency(r *IdempotencyRecord) { tx.mark("idempotency", r.Key, r) }
func (tx *Tx) MarkMeta()                      { tx.mark("app_meta", "meta", tx.st.Meta) }

func (tx *Tx) hasChanges() bool {
	return len(tx.marks) > 0 || len(tx.audits) > 0 || len(tx.events) > 0
}

func (tx *Tx) actorID() string {
	if tx.actor == nil {
		return "system"
	}
	return tx.actor.ID
}

// Audit records an audit entry; sampleID may be empty.
func (tx *Tx) Audit(action, entityType, entityID, sampleID string, success bool, details map[string]any) {
	if details == nil {
		details = map[string]any{}
	}
	role := tx.role
	if role == "" {
		if tx.actor == nil {
			role = "system"
		} else {
			role = "none"
		}
	}
	tx.audits = append(tx.audits, &store.AuditRow{
		ActorID: tx.actorID(), Role: role, Action: action, EntityType: entityType, EntityID: entityID,
		SampleID: sampleID, Success: success, OccurredAt: tx.now, Details: details,
	})
}

// Event records a timeline entry on the sample and an audit entry.
func (tx *Tx) SampleEvent(s *Sample, action, entityType, entityID string, details map[string]any) {
	if details == nil {
		details = map[string]any{}
	}
	role := tx.role
	if role == "" {
		role = "system"
	}
	entry := TimelineEntry{EventID: len(s.Timeline) + 1, Action: action, ActorID: tx.actorID(), Role: role,
		EntityType: entityType, EntityID: entityID, Success: true, OccurredAt: tx.now, Details: details}
	s.Timeline = append(s.Timeline, entry)
	t := tx.now
	s.LastEventAt = &t
	tx.MarkSample(s)
	tx.Audit(action, entityType, entityID, s.ID, true, details)
}

func (tx *Tx) Emit(typ, entityType, entityID string, payload map[string]any) {
	if payload == nil {
		payload = map[string]any{}
	}
	tx.events = append(tx.events, &store.EventRow{Type: typ, EntityType: entityType, EntityID: entityID, Payload: payload, CreatedAt: tx.now})
}

func (tx *Tx) commit(ctx context.Context) error {
	for table, m := range tx.marks {
		tx.dirty[table] = map[string][]byte{}
		for id, doc := range m {
			b, err := json.Marshal(doc)
			if err != nil {
				return err
			}
			tx.dirty[table][id] = b
		}
	}
	if err := tx.app.store.Commit(ctx, tx.dirty, tx.audits, tx.events); err != nil {
		return err
	}
	for _, e := range tx.events {
		tx.app.broadcaster.publish(e)
	}
	return nil
}

