func errf(status int, code, msg string, args ...any) *apiError {
	if len(args) > 0 {
		msg = fmt.Sprintf(msg, args...)
	}
	return &apiError{Status: status, Code: code, Message: msg}
}

func badJSON(msg string, args ...any) *apiError { return errf(400, "invalid_json", msg, args...) }
func notFound(what string) *apiError           { return errf(404, "not_found", what+" not found") }
func forbidden(msg string) *apiError            { return errf(403, "forbidden", msg) }
func conflict(code, msg string, args ...any) *apiError {
	return errf(409, code, msg, args...)
}

type reqCtx struct {
	app     *App
	r       *http.Request
	user    *User
	session *Session
	role    string
	tx      *Tx
	opID    string
}

func (c *reqCtx) st() *State  { return c.app.state }
func (c *reqCtx) now() time.Time { return c.tx.now }

type handlerFn func(c *reqCtx, body []byte) (int, any, *apiError)

type opSpec struct {
	id          string
	method      string
	path        string
	public      bool
	roles       []string // nil = any authenticated user
	requireRole bool     // 409 role_not_selected when no active role
	idem        string   // "", "optional", "required"
	handler     handlerFn
}

func New(ctx context.Context, cfg Config) (*App, error) {
	st, err := store.Open(ctx, cfg.DatabaseURL)
	if err != nil {
		return nil, err
	}
	if err := st.Migrate(ctx); err != nil {
		return nil, err
	}
	a := &App{cfg: cfg, store: st, broadcaster: newBroadcaster(), stopCh: make(chan struct{})}
	if err := a.reload(ctx); err != nil {
		return nil, err
	}
	if err := a.seed(ctx); err != nil {
		return nil, err
	}
	return a, nil
}

func Reset(ctx context.Context, databaseURL string) error {
	st, err := store.Open(ctx, databaseURL)
	if err != nil {
		return err
	}
	defer st.Close()
	return st.Reset(ctx)
}

func (a *App) reload(ctx context.Context) error {
	st, err := loadState(ctx, a.store)
	if err != nil {
		return err
	}
	a.state = st
	return nil
}

func (a *App) Close() {
	close(a.stopCh)
	a.store.Close()
}

// runSystemTx executes fn under the global lock with a system actor and commits.
func (a *App) runSystemTx(ctx context.Context, fn func(tx *Tx) error) error {
	a.mu.Lock()
	defer a.mu.Unlock()
	tx := a.newTx(nil, "")
	if err := fn(tx); err != nil {
		if len(tx.marks) > 0 {
			_ = a.reload(ctx)
		}
		return err
	}
	if !tx.hasChanges() {
		return nil
	}
	if err := tx.commit(ctx); err != nil {
		_ = a.reload(ctx)
		return err
	}
	return nil
}

func (a *App) Handler() http.Handler {
	mux := http.NewServeMux()
	byPath := map[string][]*opSpec{}
	for _, op := range a.ops() {
		byPath[op.path] = append(byPath[op.path], op)
	}
	for path, specs := range byPath {
		specs := specs
		mux.HandleFunc(path, func(w http.ResponseWriter, r *http.Request) {
			for _, s := range specs {
				if s.method == r.Method {
					a.serve(s, w, r)
					return
				}
			}
			writeError(w, errf(405, "method_not_allowed", "method not allowed"))
		})
	}
	mux.HandleFunc("/api/", func(w http.ResponseWriter, r *http.Request) {
		writeError(w, errf(404, "not_found", "unknown operation"))
	})
	mux.HandleFunc("/ready", a.handleReady)
	mux.Handle("/map-assets/", http.StripPrefix("/map-assets/", http.FileServer(http.Dir(a.cfg.MapAssetsDir))))
	mux.HandleFunc("/", a.serveStatic)
	return mux
}

func (a *App) handleReady(w http.ResponseWriter, r *http.Request) {
	ctx, cancel := context.WithTimeout(r.Context(), 3*time.Second)
	defer cancel()
	if err := a.store.Ping(ctx); err != nil {
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(503)
		_ = json.NewEncoder(w).Encode(map[string]any{"status": "unavailable", "error": err.Error()})
		return
	}
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(200)
	_, _ = w.Write([]byte(`{"status":"ready"}`))
}

func (a *App) serveStatic(w http.ResponseWriter, r *http.Request) {
	if a.cfg.StaticDir == "" {
		http.NotFound(w, r)
		return
	}
	p := filepath.Clean(r.URL.Path)
	full := filepath.Join(a.cfg.StaticDir, p)
	if st, err := os.Stat(full); err == nil && !st.IsDir() {
		http.ServeFile(w, r, full)
		return
	}
	http.ServeFile(w, r, filepath.Join(a.cfg.StaticDir, "index.html"))
}

func writeJSON(w http.ResponseWriter, status int, v any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(v)
}

func writeError(w http.ResponseWriter, e *apiError) {
	writeJSON(w, e.Status, map[string]any{"error": e.Message, "code": e.Code})
}

func bearerToken(r *http.Request) string {
	h := r.Header.Get("Authorization")
	if strings.HasPrefix(strings.ToLower(h), "bearer ") {
		return strings.TrimSpace(h[7:])
	}
	if t := r.URL.Query().Get("token"); t != "" {
		return t
	}
	if p := r.Header.Get("Sec-WebSocket-Protocol"); p != "" {
		for _, part := range strings.Split(p, ",") {
			part = strings.TrimSpace(part)
			if strings.HasPrefix(part, "bearer.") {
				return strings.TrimPrefix(part, "bearer.")
			}
			if len(part) == 64 {
				return part
			}
		}
	}
	return ""
}

// authenticate resolves the session for the request. Must be called under lock.
func (a *App) authenticate(r *http.Request, now time.Time) (*User, *Session) {
	tok := bearerToken(r)
	if tok == "" {
		return nil, nil
	}
	s := a.state.Sessions[tok]
	if s == nil || s.ExpiresAt.Before(now) {
		return nil, nil
	}
	u := a.state.Users[s.UserID]
	if u == nil || !u.Active {
		return nil, nil
	}
	return u, s
}

func (a *App) serve(spec *opSpec, w http.ResponseWriter, r *http.Request) {
	body, err := io.ReadAll(io.LimitReader(r.Body, 4<<20))
	if err != nil {
		writeError(w, badJSON("unable to read body"))
		return
	}
	if spec.id == "stream_realtime_events" && isWebSocketRequest(r) {
		a.serveEventsWS(w, r)
		return
	}
	a.mu.Lock()
	defer a.mu.Unlock()
	ctx := r.Context()
	c := &reqCtx{app: a, r: r, opID: spec.id}
	tx := a.newTx(nil, "")
	c.tx = tx
	if !spec.public {
		u, s := a.authenticate(r, tx.now)
		if u == nil {
			writeError(w, errf(401, "unauthorized", "authentication required"))
			return
		}
		c.user, c.session, c.role = u, s, s.ActiveRole
		tx.actor, tx.role = u, s.ActiveRole
		if e := a.authorize(spec, c); e != nil {
			tx.Audit("permission_check", "operation", spec.id, "", false, map[string]any{"code": e.Code, "activeRole": c.role})
			_ = tx.commit(ctx)
			writeError(w, e)
			return
		}
	}
	if r.Method == http.MethodPost {
		trimmed := bytes.TrimSpace(body)
		if len(trimmed) == 0 {
			trimmed = []byte("{}")
			body = trimmed
		}
		if trimmed[0] != '{' {
			a.failOp(ctx, tx, spec, badJSON("request body must be a JSON object"), w)
			return
		}
	}
	var idemKey string
	if spec.idem != "" {
		var probe struct {
			Key *string `json:"idempotencyKey"`
		}
		if err := json.Unmarshal(body, &probe); err != nil {
			a.failOp(ctx, tx, spec, badJSON("malformed JSON: %v", err), w)
			return
		}
		if probe.Key == nil || strings.TrimSpace(*probe.Key) == "" {
			if spec.idem == "required" {
				a.failOp(ctx, tx, spec, errf(400, "idempotency_required", "idempotencyKey is required"), w)
				return
			}
		} else {
			idemKey = c.user.ID + ":" + spec.id + ":" + *probe.Key
			if rec, ok := a.state.Idempotency[idemKey]; ok {
				if rec.RequestHash != hashBody(body) {
					a.failOp(ctx, tx, spec, conflict("idempotency_conflict", "idempotencyKey was already used with a different request"), w)
					return
				}
				w.Header().Set("Content-Type", "application/json")
				w.Header().Set("Idempotent-Replay", "true")
				w.WriteHeader(rec.StatusCode)
				_, _ = w.Write([]byte(rec.Body))
				return
			}
		}
	}
	status, data, apiErr := spec.handler(c, body)
	if apiErr != nil {
		a.failOp(ctx, tx, spec, apiErr, w)
		return
	}
	var out []byte
	if spec.id == "system_readiness" {
		out, _ = json.Marshal(data)
	} else {
		out, _ = json.Marshal(map[string]any{"data": data})
	}
	if idemKey != "" {
		rec := &IdempotencyRecord{Key: idemKey, UserID: c.user.ID, Operation: spec.id, RequestHash: hashBody(body), StatusCode: status, Body: string(out), CreatedAt: tx.now}
		a.state.Idempotency[idemKey] = rec
		tx.MarkIdempotency(rec)
	}
	if spec.id != "authenticate_user" && spec.id != "stream_realtime_events" {
		tx.Audit(spec.id, "operation", spec.id, "", true, map[string]any{"status": status})
	}
	if err := tx.commit(ctx); err != nil {
		log.Printf("commit failed for %s: %v", spec.id, err)
		_ = a.reload(ctx)
		writeError(w, errf(500, "internal_error", "failed to persist changes"))
		return
	}
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_, _ = w.Write(out)
}

func (a *App) failOp(ctx context.Context, tx *Tx, spec *opSpec, e *apiError, w http.ResponseWriter) {
	if len(tx.marks) > 0 {
		if err := a.reload(ctx); err != nil {
			log.Printf("reload after failed op: %v", err)
		}
	}
	audit := a.newTx(tx.actor, tx.role)
	audit.now = tx.now
	audit.audits = tx.audits
	if spec.id != "stream_realtime_events" {
		audit.Audit(spec.id, "operation", spec.id, "", false, map[string]any{"code": e.Code, "error": e.Message, "status": e.Status})
	}
	if err := audit.commit(ctx); err != nil {
		log.Printf("audit commit failed: %v", err)
	}
	writeError(w, e)
}

func (a *App) authorize(spec *opSpec, c *reqCtx) *apiError {
	if spec.roles == nil {
		return nil
	}
	if c.role == "" {
		if spec.requireRole {
			return conflict("role_not_selected", "select an active role first")
		}
		for _, r := range c.user.Roles {
			if containsStr(spec.roles, r) {
				return nil
			}
		}
		return forbidden("none of your roles may perform this operation")
	}
	if !c.user.HasRole(c.role) {
		return forbidden("active role is no longer held")
	}
	if containsStr(spec.roles, c.role) {
		return nil
	}
	return forbidden("role " + c.role + " may not perform this operation")
}

func hashBody(b []byte) string {
	h := sha256.Sum256(b)
	return hex.EncodeToString(h[:])
}

// decodeBody strictly decodes a JSON object body into T, verifying that the
// listed required fields are present and non-null.
func decodeBody[T any](body []byte, required ...string) (*T, *apiError) {
	raw := map[string]json.RawMessage{}
	if err := json.Unmarshal(body, &raw); err != nil {
		return nil, badJSON("malformed JSON: %v", err)
	}
	for _, f := range required {
		v, ok := raw[f]
		if !ok || bytes.Equal(bytes.TrimSpace(v), []byte("null")) {
			return nil, badJSON("missing required field %q", f)
		}
	}
	dec := json.NewDecoder(bytes.NewReader(body))
	dec.DisallowUnknownFields()
	var v T
	if err := dec.Decode(&v); err != nil {
		return nil, badJSON("invalid request body: %v", err)
	}
	return &v, nil
}

func parseTime(s string) (time.Time, bool) {
	if s == "" {
		return time.Time{}, false
	}
	for _, layout := range []string{time.RFC3339Nano, time.RFC3339, "2006-01-02T15:04:05Z07:00", "2006-01-02T15:04:05"} {
		if t, err := time.Parse(layout, s); err == nil {
			return t.UTC(), true
		}
	}
	return time.Time{}, false
}

func reqTime(s string) (time.Time, *apiError) {
	t, ok := parseTime(s)
	if !ok {
		return time.Time{}, errf(400, "invalid_time", "invalid timestamp %q", s)
	}
	return t, nil
}

func optTime(s *string) (*time.Time, *apiError) {
	if s == nil || *s == "" {
		return nil, nil
	}
	t, ok := parseTime(*s)
	if !ok {
		return nil, errf(400, "invalid_time", "invalid timestamp %q", *s)
	}
	return &t, nil
}

func fmtTime(t time.Time) string { return t.UTC().Format(time.RFC3339) }

func fmtTimePtr(t *time.Time) any {
	if t == nil {
		return nil
	}
	return fmtTime(*t)
}

var errNotFound = errors.New("not found")

