package app

import (
	"context"
	"encoding/json"
	"net/http"
	"strconv"
	"strings"
	"sync"
	"time"

	"github.com/gorilla/websocket"

	"labsample/internal/store"
)

type broadcaster struct {
	mu   sync.Mutex
	subs map[chan *store.EventRow]struct{}
}

func newBroadcaster() *broadcaster {
	return &broadcaster{subs: map[chan *store.EventRow]struct{}{}}
}

func (b *broadcaster) subscribe() chan *store.EventRow {
	ch := make(chan *store.EventRow, 256)
	b.mu.Lock()
	b.subs[ch] = struct{}{}
	b.mu.Unlock()
	return ch
}

func (b *broadcaster) unsubscribe(ch chan *store.EventRow) {
	b.mu.Lock()
	delete(b.subs, ch)
	b.mu.Unlock()
}

func (b *broadcaster) publish(e *store.EventRow) {
	b.mu.Lock()
	defer b.mu.Unlock()
	for ch := range b.subs {
		select {
		case ch <- e:
		default:
		}
	}
}

func isWebSocketRequest(r *http.Request) bool {
	return strings.EqualFold(r.Header.Get("Upgrade"), "websocket")
}

func eventJSON(e *store.EventRow) map[string]any {
	return map[string]any{
		"id": e.ID, "type": e.Type, "entityType": e.EntityType, "entityId": e.EntityID,
		"payload": e.Payload, "createdAt": fmtTime(e.CreatedAt),
	}
}

// eventVisible applies data-level access control to the realtime stream.
func eventVisible(u *User, e *store.EventRow) bool {
	if u.HasRole(RoleAdmin) || u.HasRole(RoleDispatcher) {
		return true
	}
	switch {
	case strings.HasPrefix(e.Type, "sample_type."), strings.HasPrefix(e.Type, "location."), strings.HasPrefix(e.Type, "connection."), strings.HasPrefix(e.Type, "serviceability."):
		return true
	case strings.HasPrefix(e.Type, "user."):
		return e.EntityID == u.ID
	}
	if v, ok := e.Payload["requesterId"].(string); ok && v == u.ID {
		return true
	}
	if parts, ok := e.Payload["participantIds"].([]any); ok {
		for _, p := range parts {
			if s, ok := p.(string); ok && s == u.ID {
				return true
			}
		}
	}
	if parts, ok := e.Payload["participantIds"].([]string); ok {
		return containsStr(parts, u.ID)
	}
	return false
}

func (a *App) handleEventsPoll(c *reqCtx, body []byte) (int, any, *apiError) {
	since := int64(0)
	if s := c.r.URL.Query().Get("since"); s != "" {
		v, err := strconv.ParseInt(s, 10, 64)
		if err != nil || v < 0 {
			return 0, nil, badJSON("since must be a non-negative integer")
		}
		since = v
	}
	rows, err := a.store.EventsSince(c.r.Context(), since, 1000)
	if err != nil {
		return 0, nil, errf(500, "internal_error", "failed to load events")
	}
	events := []map[string]any{}
	cursor := since
	for i := range rows {
		cursor = rows[i].ID
		if eventVisible(c.user, &rows[i]) {
			events = append(events, eventJSON(&rows[i]))
		}
	}
	return 200, map[string]any{"events": events, "cursor": cursor}, nil
}

var upgrader = websocket.Upgrader{CheckOrigin: func(r *http.Request) bool { return true }}

func (a *App) serveEventsWS(w http.ResponseWriter, r *http.Request) {
	a.mu.Lock()
	u, _ := a.authenticate(r, time.Now())
	a.mu.Unlock()
	if u == nil {
		writeError(w, errf(401, "unauthorized", "authentication required"))
		return
	}
	since := int64(0)
	if s := r.URL.Query().Get("since"); s != "" {
		if v, err := strconv.ParseInt(s, 10, 64); err == nil && v >= 0 {
			since = v
		}
	}
	hdr := http.Header{}
	if p := r.Header.Get("Sec-WebSocket-Protocol"); p != "" {
		first := strings.TrimSpace(strings.Split(p, ",")[0])
		hdr.Set("Sec-WebSocket-Protocol", first)
	}
	conn, err := upgrader.Upgrade(w, r, hdr)
	if err != nil {
		return
	}
	defer conn.Close()
	ch := a.broadcaster.subscribe()
	defer a.broadcaster.unsubscribe(ch)
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()
	go func() {
		for {
			if _, _, err := conn.ReadMessage(); err != nil {
				cancel()
				return
			}
		}
	}()
	send := func(e *store.EventRow) error {
		if !eventVisible(u, e) {
			return nil
		}
		b, _ := json.Marshal(eventJSON(e))
		_ = conn.SetWriteDeadline(time.Now().Add(10 * time.Second))
		return conn.WriteMessage(websocket.TextMessage, b)
	}
	rows, err := a.store.EventsSince(ctx, since, 1000)
	if err == nil {
		for i := range rows {
			if err := send(&rows[i]); err != nil {
				return
			}
		}
	}
	ping := time.NewTicker(25 * time.Second)
	defer ping.Stop()
	for {
		select {
		case <-ctx.Done():
			return
		case <-a.stopCh:
			return
		case e := <-ch:
			if err := send(e); err != nil {
				return
			}
		case <-ping.C:
			_ = conn.SetWriteDeadline(time.Now().Add(10 * time.Second))
			if err := conn.WriteMessage(websocket.PingMessage, nil); err != nil {
				return
			}
		}
	}
}

