package app

import (
	"context"
	"log"
	"strings"
	"time"
)

const defaultWorkerCapacity = 5

func (a *App) seed(ctx context.Context) error {
	return a.runSystemTx(ctx, func(tx *Tx) error {
		st := tx.st
		if len(st.Users) == 0 && a.cfg.AdminUsername != "" {
			u := &User{ID: newID(), Username: a.cfg.AdminUsername, PasswordHash: hashPassword(a.cfg.AdminPassword),
				FullName: "Initial Administrator", Roles: []string{RoleAdmin}, Qualifications: []string{}, Certifications: []Certification{},
				Active: true, Available: true, CapacityUnits: defaultWorkerCapacity, DeclineTimes: []time.Time{}, CreatedAt: tx.now}
			st.Users[u.ID] = u
			tx.MarkUser(u)
			tx.Audit("user_created", "user", u.ID, "", true, map[string]any{"username": u.Username, "roles": u.Roles, "seed": true})
			tx.Emit("user.created", "user", u.ID, userEventPayload(u))
			log.Printf("created initial administrator %q", u.Username)
		}
		if len(st.SampleTypes) == 0 {
			amber := &SampleType{ID: "11111111-1111-4111-8111-111111111111", Name: "Amber", QualifiedCollectorRequired: true, RequiredQualification: "amber",
				ContainerType: "standard_vial", TemperatureMinC: 2, TemperatureMaxC: 25, BatchingAllowed: true, CreatedAt: tx.now}
			indigo := &SampleType{ID: "22222222-2222-4222-8222-222222222222", Name: "Indigo", QualifiedCollectorRequired: true, RequiredQualification: "indigo",
				ContainerType: "standard_vial", TemperatureMinC: 2, TemperatureMaxC: 25, IncompatibleSampleTypes: []string{amber.ID}, BatchingAllowed: true, CreatedAt: tx.now}
			amber.IncompatibleSampleTypes = []string{indigo.ID}
			frost := &SampleType{ID: "33333333-3333-4333-8333-333333333333", Name: "Frost", QualifiedCollectorRequired: true, RequiredQualification: "frost",
				ContainerType: "cooled_vial", TemperatureMinC: 2, TemperatureMaxC: 8, RequiresCooledRoute: true, BatchingAllowed: true, CreatedAt: tx.now}
			pulse := &SampleType{ID: "44444444-4444-4444-8444-444444444444", Name: "Pulse", QualifiedCollectorRequired: true, RequiredQualification: "pulse",
				ContainerType: "standard_vial", TemperatureMinC: 15, TemperatureMaxC: 25, BatchingAllowed: false, CreatedAt: tx.now}
			for _, t := range []*SampleType{amber, indigo, frost, pulse} {
				if t.IncompatibleSampleTypes == nil {
					t.IncompatibleSampleTypes = []string{}
				}
				st.SampleTypes[t.ID] = t
				tx.MarkSampleType(t)
				tx.Audit("sample_type_created", "sample_type", t.ID, "", true, map[string]any{"name": t.Name, "seed": true})
				tx.Emit("sample_type.created", "sample_type", t.ID, sampleTypeJSON(t))
			}
		}
		if st.Meta.Snapshot == nil {
			a.recomputeSnapshot(tx)
		}
		return nil
	})
}

func userEventPayload(u *User) map[string]any {
	return map[string]any{
		"userId": u.ID, "username": u.Username, "fullName": u.FullName, "roles": nonNil(u.Roles),
		"assignedLocationId": u.AssignedLocationID, "active": u.Active, "available": u.Available,
		"capacityUnits": u.CapacityUnits, "qualifications": nonNil(u.Qualifications),
	}
}

func userJSON(u *User) map[string]any {
	certs := u.Certifications
	if certs == nil {
		certs = []Certification{}
	}
	return map[string]any{
		"userId": u.ID, "username": u.Username, "email": u.Email, "fullName": u.FullName, "phone": u.Phone,
		"roles": nonNil(u.Roles), "qualifications": nonNil(u.Qualifications), "certifications": certs, "active": u.Active,
	}
}

func (a *App) handleAuthenticate(c *reqCtx, body []byte) (int, any, *apiError) {
	type in struct {
		Username string `json:"username"`
		Password string `json:"password"`
	}
	req, e := decodeBody[in](body, "username", "password")
	if e != nil {
		return 0, nil, e
	}
	tx := c.tx
	var user *User
	for _, u := range c.st().Users {
		if strings.EqualFold(u.Username, req.Username) {
			user = u
			break
		}
	}
	if user == nil || !user.Active || !checkPassword(user.PasswordHash, req.Password) {
		id := ""
		if user != nil {
			id = user.ID
		}
		tx.Audit("sign_in", "user", id, "", false, map[string]any{"username": req.Username, "reason": "invalid_credentials"})
		return 0, nil, errf(401, "invalid_credentials", "invalid username or password")
	}
	active := ""
	if len(user.Roles) == 1 {
		active = user.Roles[0]
	}
	s := &Session{Token: newToken(), UserID: user.ID, ActiveRole: active, CreatedAt: tx.now, ExpiresAt: tx.now.Add(a.cfg.SessionTTL)}
	c.st().Sessions[s.Token] = s
	tx.MarkSession(s)
	tx.actor, tx.role = user, active
	tx.Audit("sign_in", "user", user.ID, "", true, map[string]any{"username": user.Username, "activeRole": active})
	return 200, map[string]any{"sessionToken": s.Token, "userId": user.ID, "roles": nonNil(user.Roles), "activeRole": active}, nil
}

func (a *App) handleSelectRole(c *reqCtx, body []byte) (int, any, *apiError) {
	type in struct {
		Role string `json:"role"`
	}
	req, e := decodeBody[in](body, "role")
	if e != nil {
		return 0, nil, e
	}
	if !containsStr(AllRoles, req.Role) {
		return 0, nil, errf(400, "invalid_role", "unknown role %q", req.Role)
	}
	if !c.user.HasRole(req.Role) {
		c.tx.Audit("role_selected", "user", c.user.ID, "", false, map[string]any{"role": req.Role, "reason": "role_not_held"})
		return 0, nil, errf(403, "role_not_held", "you do not hold the role %q", req.Role)
	}
	c.session.ActiveRole = req.Role
	c.tx.MarkSession(c.session)
	c.tx.role = req.Role
	c.tx.Audit("role_selected", "user", c.user.ID, "", true, map[string]any{"role": req.Role})
	return 200, map[string]any{"activeRole": req.Role, "roles": nonNil(c.user.Roles)}, nil
}

func (a *App) handleReadUser(c *reqCtx, body []byte) (int, any, *apiError) {
	id := c.r.PathValue("userId")
	if c.user.ID != id && !c.user.HasRole(RoleAdmin) && !c.user.HasRole(RoleDispatcher) {
		return 0, nil, forbidden("you may only view your own user record")
	}
	u := c.st().Users[id]
	if u == nil {
		return 0, nil, notFound("user")
	}
	return 200, userJSON(u), nil
}

func validateCertifications(certs []Certification) *apiError {
	for _, ct := range certs {
		if strings.TrimSpace(ct.Code) == "" {
			return errf(400, "invalid_certification", "certification code is required")
		}
	}
	return nil
}

func (a *App) handleCreateUser(c *reqCtx, body []byte) (int, any, *apiError) {
	type in struct {
		Username           string          `json:"username"`
		InitialPassword    string          `json:"initialPassword"`
		Email              string          `json:"email"`
		FullName           string          `json:"fullName"`
		Phone              string          `json:"phone"`
		Roles              []string        `json:"roles"`
		Qualifications     []string        `json:"qualifications"`
		Certifications     []Certification `json:"certifications"`
		Active             *bool           `json:"active"`
		AssignedLocationID string          `json:"assignedLocationId"`
	}
	req, e := decodeBody[in](body, "username", "initialPassword", "roles", "active")
	if e != nil {
		return 0, nil, e
	}
	req.Username = strings.TrimSpace(req.Username)
	if req.Username == "" || req.InitialPassword == "" {
		return 0, nil, errf(400, "invalid_user", "username and initialPassword are required")
	}
	if len(req.Roles) == 0 {
		return 0, nil, errf(400, "invalid_user", "at least one role is required")
	}
	for _, r := range req.Roles {
		if !containsStr(AllRoles, r) {
			return 0, nil, errf(400, "invalid_user", "unknown role %q", r)
		}
	}
	if e := validateCertifications(req.Certifications); e != nil {
		return 0, nil, e
	}
	if req.AssignedLocationID != "" && c.st().Locations[req.AssignedLocationID] == nil {
		return 0, nil, errf(400, "invalid_user", "assignedLocationId does not exist")
	}
	for _, u := range c.st().Users {
		if strings.EqualFold(u.Username, req.Username) {
			return 0, nil, conflict("username_exists", "username already exists")
		}
	}
	u := &User{ID: newID(), Username: req.Username, PasswordHash: hashPassword(req.InitialPassword), Email: req.Email, FullName: req.FullName,
		Phone: req.Phone, Roles: uniqueStrs(req.Roles), Qualifications: uniqueStrs(req.Qualifications), Certifications: req.Certifications,
		Active: *req.Active, AssignedLocationID: req.AssignedLocationID, Available: true, CapacityUnits: defaultWorkerCapacity,
		DeclineTimes: []time.Time{}, CreatedAt: c.now()}
	if u.Certifications == nil {
		u.Certifications = []Certification{}
	}
	c.st().Users[u.ID] = u
	c.tx.MarkUser(u)
	c.tx.Audit("user_created", "user", u.ID, "", true, map[string]any{"username": u.Username, "roles": u.Roles, "assignedLocationId": u.AssignedLocationID})
	c.tx.Emit("user.created", "user", u.ID, userEventPayload(u))
	a.retryPendingOffers(c.tx)
	return 201, userJSON(u), nil
}

func (a *App) handleUpdateUserAccess(c *reqCtx, body []byte) (int, any, *apiError) {
	type in struct {
		UserID             string          `json:"userId"`
		Roles              []string        `json:"roles"`
		Qualifications     []string        `json:"qualifications"`
		Certifications     []Certification `json:"certifications"`
		Active             *bool           `json:"active"`
		AssignedLocationID *string         `json:"assignedLocationId"`
	}
	req, e := decodeBody[in](body, "userId", "roles", "active")
	if e != nil {
		return 0, nil, e
	}
	for _, r := range req.Roles {
		if !containsStr(AllRoles, r) {
			return 0, nil, badJSON("unknown role %q", r)
		}
	}
	if e := validateCertifications(req.Certifications); e != nil {
		return 0, nil, e
	}
	u := c.st().Users[req.UserID]
	if u == nil {
		return 0, nil, notFound("user")
	}
	if req.AssignedLocationID != nil && *req.AssignedLocationID != "" && c.st().Locations[*req.AssignedLocationID] == nil {
		return 0, nil, notFound("assigned location")
	}
	before := userEventPayload(u)
	u.Roles = uniqueStrs(req.Roles)
	if req.Qualifications != nil {
		u.Qualifications = uniqueStrs(req.Qualifications)
	}
	if req.Certifications != nil {
		u.Certifications = req.Certifications
	}
	u.Active = *req.Active
	if req.AssignedLocationID != nil {
		u.AssignedLocationID = *req.AssignedLocationID
	}
	c.tx.MarkUser(u)
	// Sessions whose active role is no longer held fall back to no selection.
	for _, s := range c.st().Sessions {
		if s.UserID == u.ID && s.ActiveRole != "" && !u.HasRole(s.ActiveRole) {
			s.ActiveRole = ""
			c.tx.MarkSession(s)
		}
	}
	c.tx.Audit("user_access_updated", "user", u.ID, "", true, map[string]any{"before": before, "after": userEventPayload(u)})
	c.tx.Emit("user.updated", "user", u.ID, userEventPayload(u))
	a.reofferIneligible(c.tx)
	a.retryPendingOffers(c.tx)
	return 201, map[string]any{"userId": u.ID, "roles": nonNil(u.Roles), "qualifications": nonNil(u.Qualifications), "certifications": u.Certifications, "active": u.Active}, nil
}

func (a *App) handleUIBootstrap(c *reqCtx, body []byte) (int, any, *apiError) {
	u := c.user
	out := map[string]any{
		"user": map[string]any{
			"userId": u.ID, "username": u.Username, "fullName": u.FullName, "roles": nonNil(u.Roles),
			"activeRole": c.role, "roleSelectionRequired": c.role == "",
		},
		"serverTime": fmtTime(c.now()),
	}
	if c.role == RoleRequester {
		items := []any{}
		for _, s := range a.samplesSorted() {
			if s.RequesterID == u.ID {
				items = append(items, a.sampleWorkItem(s))
			}
		}
		out["requesterSamples"] = items
	}
	if c.role == RoleDispatcher || c.role == RoleAdmin {
		out["operations"] = a.operationsState("")
	}
	return 200, out, nil
}

