// ---- capacity ----

func (a *App) handleConfigureCapacity(c *reqCtx, body []byte) (int, any, *apiError) {
	type in struct {
		ResourceID          string `json:"resourceId"`
		CapacityUnits       *int   `json:"capacityUnits"`
		CooledCapacityUnits *int   `json:"cooledCapacityUnits"`
	}
	req, e := decodeBody[in](body, "resourceId", "capacityUnits")
	if e != nil {
		return 0, nil, e
	}
	cooled := 0
	if req.CooledCapacityUnits != nil {
		cooled = *req.CooledCapacityUnits
	}
	if *req.CapacityUnits < 0 || cooled < 0 {
		return 0, nil, errf(400, "invalid_capacity", "capacity units must not be negative")
	}
	l := c.st().Locations[req.ResourceID]
	cn := c.st().Connections[req.ResourceID]
	if l == nil && cn == nil {
		return 0, nil, errf(400, "invalid_capacity", "unknown capacity resource")
	}
	if c.role == RoleNode || c.role == RoleLab {
		if l == nil || c.user.AssignedLocationID != l.ID {
			return 0, nil, forbidden("you may only configure capacity at your assigned location")
		}
	}
	if a.reservedUnits(req.ResourceID, false, "") > *req.CapacityUnits || a.reservedUnits(req.ResourceID, true, "") > cooled {
		return 0, nil, conflict("capacity_reserved", "capacity cannot be reduced below the currently reserved units")
	}
	var before, after capacityView
	before = a.capacityOf(req.ResourceID)
	if l != nil {
		l.CapacityUnits, l.CooledCapacityUnits = *req.CapacityUnits, cooled
		c.tx.MarkLocation(l)
		after = a.capacityOf(l.ID)
		c.tx.Emit("location.updated", "location", l.ID, a.locationEventPayload(l))
	} else {
		cn.CapacityUnits, cn.CooledCapacityUnits = *req.CapacityUnits, cooled
		c.tx.MarkConnection(cn)
		after = a.capacityOf(cn.ID)
		c.tx.Emit("connection.updated", "connection", cn.ID, a.connectionEventPayload(cn))
	}
	c.tx.Audit("capacity_configured", "capacity", req.ResourceID, "", true, map[string]any{"before": before, "after": after})
	a.networkChanged(c.tx)
	return 200, map[string]any{"resourceId": req.ResourceID, "capacityUnits": *req.CapacityUnits, "cooledCapacityUnits": cooled}, nil
}

func (a *App) handleConfigureAcceptance(c *reqCtx, body []byte) (int, any, *apiError) {
	type in struct {
		LaboratoryID string `json:"laboratoryId"`
		SampleTypeID string `json:"sampleTypeId"`
		Accepts      *bool  `json:"accepts"`
	}
	req, e := decodeBody[in](body, "laboratoryId", "sampleTypeId", "accepts")
	if e != nil {
		return 0, nil, e
	}
	l := c.st().Locations[req.LaboratoryID]
	if l == nil || !l.Functions[FnLab] {
		return 0, nil, errf(400, "invalid_acceptance", "laboratoryId must reference a location with the laboratory function")
	}
	if c.st().SampleTypes[req.SampleTypeID] == nil {
		return 0, nil, errf(400, "invalid_acceptance", "unknown sample type")
	}
	if l.Acceptances == nil {
		l.Acceptances = map[string]Acceptance{}
	}
	acc, ok := l.Acceptances[req.SampleTypeID]
	if !ok {
		acc = Acceptance{ID: newID()}
	}
	acc.Accepts = *req.Accepts
	l.Acceptances[req.SampleTypeID] = acc
	c.tx.MarkLocation(l)
	c.tx.Audit("laboratory_acceptance_configured", "location", l.ID, "", true, map[string]any{"sampleTypeId": req.SampleTypeID, "accepts": acc.Accepts, "acceptanceId": acc.ID})
	c.tx.Emit("location.updated", "location", l.ID, a.locationEventPayload(l))
	a.networkChanged(c.tx)
	return 200, map[string]any{"acceptanceId": acc.ID, "accepts": acc.Accepts}, nil
}

// ---- sample types ----

func validateHandling(min, max float64, incompatible []string, st *State) *apiError {
	if min > max {
		return errf(400, "invalid_handling_rule", "temperatureMinC must not exceed temperatureMaxC")
	}
	for _, id := range incompatible {
		if st.SampleTypes[id] == nil {
			return errf(400, "invalid_handling_rule", "incompatible sample type %q does not exist", id)
		}
	}
	return nil
}

func (a *App) handleCreateSampleType(c *reqCtx, body []byte) (int, any, *apiError) {
	type in struct {
		Name                       string   `json:"name"`
		QualifiedCollectorRequired *bool    `json:"qualifiedCollectorRequired"`
		RequiredQualification      string   `json:"requiredQualification"`
		ContainerType              string   `json:"containerType"`
		TemperatureMinC            *float64 `json:"temperatureMinC"`
		TemperatureMaxC            *float64 `json:"temperatureMaxC"`
		IncompatibleSampleTypes    []string `json:"incompatibleSampleTypes"`
		RequiresCooledRoute        *bool    `json:"requiresCooledRoute"`
		BatchingAllowed            *bool    `json:"batchingAllowed"`
	}
	req, e := decodeBody[in](body, "name", "containerType", "temperatureMinC", "temperatureMaxC")
	if e != nil {
		return 0, nil, e
	}
	if strings.TrimSpace(req.Name) == "" || strings.TrimSpace(req.ContainerType) == "" {
		return 0, nil, errf(400, "invalid_handling_rule", "name and containerType are required")
	}
	if e := validateHandling(*req.TemperatureMinC, *req.TemperatureMaxC, req.IncompatibleSampleTypes, c.st()); e != nil {
		return 0, nil, e
	}
	t := &SampleType{ID: newID(), Name: strings.TrimSpace(req.Name), ContainerType: req.ContainerType, TemperatureMinC: *req.TemperatureMinC,
		TemperatureMaxC: *req.TemperatureMaxC, IncompatibleSampleTypes: uniqueStrs(req.IncompatibleSampleTypes), BatchingAllowed: true, CreatedAt: c.now()}
	if req.QualifiedCollectorRequired != nil {
		t.QualifiedCollectorRequired = *req.QualifiedCollectorRequired
	}
	t.RequiredQualification = strings.TrimSpace(req.RequiredQualification)
	if t.RequiredQualification != "" && req.QualifiedCollectorRequired == nil {
		t.QualifiedCollectorRequired = true
	}
	if req.RequiresCooledRoute != nil {
		t.RequiresCooledRoute = *req.RequiresCooledRoute
	}
	if req.BatchingAllowed != nil {
		t.BatchingAllowed = *req.BatchingAllowed
	}
	c.st().SampleTypes[t.ID] = t
	c.tx.MarkSampleType(t)
	// Incompatibility is symmetric.
	for _, other := range t.IncompatibleSampleTypes {
		o := c.st().SampleTypes[other]
		if !containsStr(o.IncompatibleSampleTypes, t.ID) {
			o.IncompatibleSampleTypes = append(o.IncompatibleSampleTypes, t.ID)
			c.tx.MarkSampleType(o)
			c.tx.Emit("sample_type.updated", "sample_type", o.ID, sampleTypeJSON(o))
		}
	}
	c.tx.Audit("sample_type_created", "sample_type", t.ID, "", true, map[string]any{"sampleType": sampleTypeJSON(t)})
	c.tx.Emit("sample_type.created", "sample_type", t.ID, sampleTypeJSON(t))
	return 201, sampleTypeJSON(t), nil
}

func (a *App) handleUpdateSampleType(c *reqCtx, body []byte) (int, any, *apiError) {
	type in struct {
		SampleTypeID               string   `json:"sampleTypeId"`
		QualifiedCollectorRequired *bool    `json:"qualifiedCollectorRequired"`
		RequiredQualification      *string  `json:"requiredQualification"`
		ContainerType              string   `json:"containerType"`
		TemperatureMinC            *float64 `json:"temperatureMinC"`
		TemperatureMaxC            *float64 `json:"temperatureMaxC"`
		IncompatibleSampleTypes    []string `json:"incompatibleSampleTypes"`
		RequiresCooledRoute        *bool    `json:"requiresCooledRoute"`
		BatchingAllowed            *bool    `json:"batchingAllowed"`
	}
	req, e := decodeBody[in](body, "sampleTypeId", "containerType", "temperatureMinC", "temperatureMaxC")
	if e != nil {
		return 0, nil, e
	}
	t := c.st().SampleTypes[req.SampleTypeID]
	if t == nil {
		return 0, nil, notFound("sample type")
	}
	if strings.TrimSpace(req.ContainerType) == "" {
		return 0, nil, errf(400, "invalid_handling_rule", "containerType is required")
	}
	if e := validateHandling(*req.TemperatureMinC, *req.TemperatureMaxC, req.IncompatibleSampleTypes, c.st()); e != nil {
		return 0, nil, e
	}
	before := sampleTypeJSON(t)
	t.ContainerType = req.ContainerType
	t.TemperatureMinC, t.TemperatureMaxC = *req.TemperatureMinC, *req.TemperatureMaxC
	if req.QualifiedCollectorRequired != nil {
		t.QualifiedCollectorRequired = *req.QualifiedCollectorRequired
	}
	if req.RequiredQualification != nil {
		t.RequiredQualification = strings.TrimSpace(*req.RequiredQualification)
	}
	if req.IncompatibleSampleTypes != nil {
		t.IncompatibleSampleTypes = uniqueStrs(req.IncompatibleSampleTypes)
		for _, other := range t.IncompatibleSampleTypes {
			o := c.st().SampleTypes[other]
			if o != nil && o.ID != t.ID && !containsStr(o.IncompatibleSampleTypes, t.ID) {
				o.IncompatibleSampleTypes = append(o.IncompatibleSampleTypes, t.ID)
				c.tx.MarkSampleType(o)
				c.tx.Emit("sample_type.updated", "sample_type", o.ID, sampleTypeJSON(o))
			}
		}
	}
	if req.RequiresCooledRoute != nil {
		t.RequiresCooledRoute = *req.RequiresCooledRoute
	}
	if req.BatchingAllowed != nil {
		t.BatchingAllowed = *req.BatchingAllowed
	}
	c.tx.MarkSampleType(t)
	c.tx.Audit("sample_type_updated", "sample_type", t.ID, "", true, map[string]any{"before": before, "after": sampleTypeJSON(t)})
	c.tx.Emit("sample_type.updated", "sample_type", t.ID, sampleTypeJSON(t))
	return 201, sampleTypeJSON(t), nil
}

