// ---- connections ----

func (a *App) handleCreateConnection(c *reqCtx, body []byte) (int, any, *apiError) {
	type in struct {
		FromLocationID string   `json:"fromLocationId"`
		ToLocationID   string   `json:"toLocationId"`
		TravelMinutes  *int     `json:"travelMinutes"`
		CostUnits      *float64 `json:"costUnits"`
		Cooled         *bool    `json:"cooled"`
		Active         *bool    `json:"active"`
	}
	req, e := decodeBody[in](body, "fromLocationId", "toLocationId", "travelMinutes", "costUnits", "active")
	if e != nil {
		return 0, nil, e
	}
	if c.st().Locations[req.FromLocationID] == nil || c.st().Locations[req.ToLocationID] == nil {
		return 0, nil, errf(400, "invalid_connection", "both locations must exist")
	}
	if req.FromLocationID == req.ToLocationID {
		return 0, nil, errf(400, "invalid_connection", "a connection must join two different locations")
	}
	if *req.TravelMinutes < 1 {
		return 0, nil, errf(400, "invalid_connection", "travelMinutes must be at least 1")
	}
	if *req.CostUnits < 0 {
		return 0, nil, errf(400, "invalid_connection", "costUnits must not be negative")
	}
	cn := &Connection{ID: newID(), FromLocationID: req.FromLocationID, ToLocationID: req.ToLocationID, TravelMinutes: *req.TravelMinutes,
		CostUnits: *req.CostUnits, Cooled: req.Cooled != nil && *req.Cooled, Active: *req.Active, CapacityUnits: 0, CooledCapacityUnits: 0, CreatedAt: c.now()}
	c.st().Connections[cn.ID] = cn
	c.tx.MarkConnection(cn)
	c.tx.Audit("connection_created", "connection", cn.ID, "", true, map[string]any{"connection": connectionJSON(cn)})
	c.tx.Emit("connection.created", "connection", cn.ID, a.connectionEventPayload(cn))
	a.networkChanged(c.tx)
	return 201, connectionJSON(cn), nil
}

func (a *App) handleSetConnectionStatus(c *reqCtx, body []byte) (int, any, *apiError) {
	type in struct {
