package app

import (
	"sort"
	"strings"
)

func functionStates(l *Location) map[string]bool {
	out := map[string]bool{}
	for _, f := range AllFunctions {
		out[f] = l.Functions[f]
	}
	return out
}

func locationJSON(l *Location) map[string]any {
	return map[string]any{
		"locationId": l.ID, "name": l.Name, "coordinate": l.Coordinate, "coverageKm": l.CoverageKm,
		"handlingMinutes": l.HandlingMinutes, "active": l.Active, "functions": functionStates(l),
	}
}

func sampleTypeJSON(t *SampleType) map[string]any {
	return map[string]any{
		"sampleTypeId": t.ID, "name": t.Name, "qualifiedCollectorRequired": t.QualifiedCollectorRequired,
		"requiredQualification": t.RequiredQualification, "containerType": t.ContainerType,
		"temperatureMinC": t.TemperatureMinC, "temperatureMaxC": t.TemperatureMaxC,
		"incompatibleSampleTypes": nonNil(t.IncompatibleSampleTypes), "requiresCooledRoute": t.RequiresCooledRoute,
		"batchingAllowed": t.BatchingAllowed,
	}
}

func connectionJSON(cn *Connection) map[string]any {
	return map[string]any{
		"connectionId": cn.ID, "fromLocationId": cn.FromLocationID, "toLocationId": cn.ToLocationID,
		"travelMinutes": cn.TravelMinutes, "costUnits": cn.CostUnits, "cooled": cn.Cooled, "active": cn.Active,
	}
}

// ---- capacity pools ----

type capacityView struct {
	CapacityUnits        int `json:"capacityUnits"`
	ReservedUnits        int `json:"reservedUnits"`
	AvailableUnits       int `json:"availableUnits"`
	CooledCapacityUnits  int `json:"cooledCapacityUnits"`
	CooledReservedUnits  int `json:"cooledReservedUnits"`
	CooledAvailableUnits int `json:"cooledAvailableUnits"`
}

func (a *App) reservedUnits(poolID string, cooled bool, ignoreJourney string) int {
	n := 0
	for _, r := range a.state.Reservations {
		if r.PoolID == poolID && r.Cooled == cooled && r.Status == "active" && r.JourneyID != ignoreJourney {
			n += r.Units
		}
	}
	return n
}

func (a *App) poolCapacity(poolID string) (regular, cooled int, ok bool) {
	if l := a.state.Locations[poolID]; l != nil {
		return l.CapacityUnits, l.CooledCapacityUnits, true
	}
	if cn := a.state.Connections[poolID]; cn != nil {
		return cn.CapacityUnits, cn.CooledCapacityUnits, true
	}
	return 0, 0, false
}

func (a *App) capacityOf(poolID string) capacityView {
	reg, cool, _ := a.poolCapacity(poolID)
	rr := a.reservedUnits(poolID, false, "")
	cr := a.reservedUnits(poolID, true, "")
	return capacityView{CapacityUnits: reg, ReservedUnits: rr, AvailableUnits: reg - rr,
		CooledCapacityUnits: cool, CooledReservedUnits: cr, CooledAvailableUnits: cool - cr}
}

func (a *App) available(poolID string, cooled bool, ignoreJourney string) int {
	reg, cool, ok := a.poolCapacity(poolID)
	if !ok {
		return 0
	}
	if cooled {
		return cool - a.reservedUnits(poolID, true, ignoreJourney)
	}
	return reg - a.reservedUnits(poolID, false, ignoreJourney)
}

func (a *App) locationEventPayload(l *Location) map[string]any {
	p := locationJSON(l)
	p["capacity"] = a.capacityOf(l.ID)
	accepted := []string{}
	for id, acc := range l.Acceptances {
		if acc.Accepts {
			accepted = append(accepted, id)
		}
	}
	sort.Strings(accepted)
	p["acceptedSampleTypeIds"] = accepted
	return p
}

func (a *App) connectionEventPayload(cn *Connection) map[string]any {
	p := connectionJSON(cn)
	p["capacity"] = a.capacityOf(cn.ID)
	return p
}

// ---- serviceability snapshot ----

// recomputeSnapshot builds a complete new serviceability snapshot and publishes
// it atomically; readers keep seeing the previous version until it is swapped.
func (a *App) recomputeSnapshot(tx *Tx) {
	m := tx.st.Meta
	version := 1
	if m.Snapshot != nil {
		version = m.Snapshot.Version + 1
	}
	snap := &ServiceabilitySnapshot{Version: version, Status: "complete", ComputedAt: tx.now, NetworkRevision: m.NetworkRevision, Regions: []ServiceabilityRegion{}}
	for _, id := range sortedKeys(tx.st.Locations) {
		l := tx.st.Locations[id]
		if l.Fn(FnCollection) {
			snap.Regions = append(snap.Regions, ServiceabilityRegion{LocationID: l.ID, Name: l.Name, Latitude: l.Coordinate.Latitude, Longitude: l.Coordinate.Longitude, CoverageKm: l.CoverageKm})
		}
	}
	snap.ActiveCollectionPointCount = len(snap.Regions)
	m.Snapshot = snap
	tx.MarkMeta()
	tx.Emit("serviceability.recomputed", "serviceability", "snapshot", map[string]any{"version": snap.Version, "networkRevision": snap.NetworkRevision, "activeCollectionPointCount": snap.ActiveCollectionPointCount})
}

func (a *App) networkChanged(tx *Tx) {
	tx.st.Meta.NetworkRevision++
	tx.MarkMeta()
	a.recomputeSnapshot(tx)
}

func (a *App) handleReadSnapshot(c *reqCtx, body []byte) (int, any, *apiError) {
	if _, e := decodeBody[struct{}](body); e != nil {
		return 0, nil, e
	}
	s := c.st().Meta.Snapshot
	return 200, map[string]any{
		"version": s.Version, "status": "complete", "computedAt": fmtTime(s.ComputedAt), "networkRevision": s.NetworkRevision,
		"regions": s.Regions, "activeCollectionPointCount": s.ActiveCollectionPointCount,
	}, nil
}

// ---- locations ----

func (a *App) handleCreateLocation(c *reqCtx, body []byte) (int, any, *apiError) {
	type in struct {
		Name            string     `json:"name"`
		Coordinate      Coordinate `json:"coordinate"`
		CoverageKm      *float64   `json:"coverageKm"`
		HandlingMinutes *int       `json:"handlingMinutes"`
		Active          *bool      `json:"active"`
		Functions       []string   `json:"functions"`
	}
	req, e := decodeBody[in](body, "name", "coordinate", "active", "functions")
	if e != nil {
		return 0, nil, e
	}
	if !validCoordinate(req.Coordinate) {
		return 0, nil, errf(400, "invalid_coordinate", "coordinate out of range")
	}
	coverage := 5.0
	if req.CoverageKm != nil {
		coverage = *req.CoverageKm
	}
	if coverage <= 0 || coverage > 5 {
		return 0, nil, errf(400, "invalid_node_coverage", "coverageKm must be greater than 0 and at most 5")
	}
	handling := 0
	if req.HandlingMinutes != nil {
		handling = *req.HandlingMinutes
	}
	if handling < 0 || handling > 1440 {
		return 0, nil, errf(400, "invalid_handling_time", "handlingMinutes must be between 0 and 1440")
	}
	if len(req.Functions) == 0 {
		return 0, nil, errf(400, "invalid_location_function", "at least one function is required")
	}
	fns := map[string]bool{}
	for _, f := range req.Functions {
		if !containsStr(AllFunctions, f) {
			return 0, nil, errf(400, "invalid_location_function", "unknown function %q", f)
		}
		fns[f] = true
	}
	l := &Location{ID: newID(), Name: strings.TrimSpace(req.Name), Coordinate: req.Coordinate, CoverageKm: coverage, HandlingMinutes: handling,
		Active: *req.Active, Functions: fns, CapacityUnits: 0, CooledCapacityUnits: 0, Acceptances: map[string]Acceptance{}, CreatedAt: c.now()}
	c.st().Locations[l.ID] = l
	c.tx.MarkLocation(l)
	c.tx.Audit("location_created", "location", l.ID, "", true, map[string]any{"location": locationJSON(l)})
	c.tx.Emit("location.created", "location", l.ID, a.locationEventPayload(l))
	a.networkChanged(c.tx)
	return 201, locationJSON(l), nil
}

func (a *App) handleUpdateLocation(c *reqCtx, body []byte) (int, any, *apiError) {
	type in struct {
		LocationID      string     `json:"locationId"`
		Name            string     `json:"name"`
		Coordinate      Coordinate `json:"coordinate"`
		CoverageKm      *float64   `json:"coverageKm"`
		HandlingMinutes *int       `json:"handlingMinutes"`
		Functions       []string   `json:"functions"`
	}
	req, e := decodeBody[in](body, "locationId", "name", "coordinate")
	if e != nil {
		return 0, nil, e
	}
	l := c.st().Locations[req.LocationID]
	if l == nil {
		return 0, nil, notFound("location")
	}
	if !validCoordinate(req.Coordinate) {
		return 0, nil, errf(400, "invalid_coordinate", "coordinate out of range")
	}
	if req.CoverageKm != nil && (*req.CoverageKm <= 0 || *req.CoverageKm > 5) {
		return 0, nil, errf(400, "invalid_node_coverage", "coverageKm must be greater than 0 and at most 5")
	}
	if req.HandlingMinutes != nil && (*req.HandlingMinutes < 0 || *req.HandlingMinutes > 1440) {
		return 0, nil, errf(400, "invalid_handling_time", "handlingMinutes must be between 0 and 1440")
	}
	var fns map[string]bool
	if req.Functions != nil {
		if len(req.Functions) == 0 {
			return 0, nil, errf(400, "invalid_location_function", "at least one function is required")
		}
		fns = map[string]bool{}
		for _, f := range req.Functions {
			if !containsStr(AllFunctions, f) {
				return 0, nil, errf(400, "invalid_location_function", "unknown function %q", f)
			}
			fns[f] = true
		}
	}
	before := locationJSON(l)
	l.Name = strings.TrimSpace(req.Name)
	l.Coordinate = req.Coordinate
	if req.CoverageKm != nil {
		l.CoverageKm = *req.CoverageKm
	}
	if req.HandlingMinutes != nil {
		l.HandlingMinutes = *req.HandlingMinutes
	}
	if fns != nil {
		l.Functions = fns
	}
	c.tx.MarkLocation(l)
	c.tx.Audit("location_updated", "location", l.ID, "", true, map[string]any{"before": before, "after": locationJSON(l)})
	c.tx.Emit("location.updated", "location", l.ID, a.locationEventPayload(l))
	a.networkChanged(c.tx)
	return 201, locationJSON(l), nil
}

