package app

import (
	"math"
	"time"
)

type planInput struct {
	StartNode     string      // non-empty when the sample starts at a network node
	StartCoord    *Coordinate // used when StartNode is empty (home / clinic)
	StartAt       time.Time
	Types         []*SampleType
	Deadline      time.Time
	Units         int
	IgnoreJourney string // reservations of this journey are not counted
}

type planResult struct {
	Reason   string // "serviceable" or a serviceability reason code
	Path     []string
	Conns    []string
	Lab      string
	ETA      time.Time
	Cost     float64
	Arrivals []time.Time // arrival at each path node, after handling
	FirstMileMinutes int
	Cooled   bool
}

func (in planInput) cooled() bool {
	for _, t := range in.Types {
		if t.RequiresCooledRoute {
			return true
		}
	}
	return false
}

func (a *App) acceptingLabs(types []*SampleType) map[string]bool {
	labs := map[string]bool{}
	for id, l := range a.state.Locations {
		if !l.Fn(FnLab) {
			continue
		}
		ok := true
		for _, t := range types {
			if !l.Accepts(t.ID) {
				ok = false
				break
			}
		}
		if ok {
			labs[id] = true
		}
	}
	return labs
}

func (a *App) entryNodes(in planInput) map[string]time.Time {
	entries := map[string]time.Time{}
	if in.StartNode != "" {
		entries[in.StartNode] = in.StartAt
		return entries
	}
	for id, l := range a.state.Locations {
		if !l.Fn(FnCollection) {
			continue
		}
		d := haversineKm(*in.StartCoord, l.Coordinate)
		if d <= math.Min(l.CoverageKm, 5) {
			entries[id] = in.StartAt.Add(time.Duration(firstMileMinutes(*in.StartCoord, l.Coordinate)+l.HandlingMinutes) * time.Minute)
		}
	}
	return entries
}

func (a *App) nodeAdmitted(id string, in planInput, cooled, checkCap bool) bool {
	l := a.state.Locations[id]
	if l == nil {
		return false
	}
	if id != in.StartNode && !l.Active {
		return false
	}
	if checkCap {
		if a.available(id, cooled, in.IgnoreJourney) < in.Units {
			return false
		}
	}
	return true
}

func (a *App) connAdmitted(cn *Connection, in planInput, cooled, checkCap bool) bool {
	if !cn.Active {
		return false
	}
	if cooled && !cn.Cooled {
		return false
	}
	if checkCap && a.available(cn.ID, cooled, in.IgnoreJourney) < in.Units {
		return false
	}
	return true
}

type dnode struct {
	at       time.Time
	cost     float64
	prev     string
	prevConn string
	visited  bool
}

func (a *App) dijkstra(in planInput, entries map[string]time.Time, labs map[string]bool, cooled, checkCap bool) *planResult {
	nodes := map[string]*dnode{}
	for id, at := range entries {
		if !a.nodeAdmitted(id, in, cooled, checkCap) {
			continue
		}
		nodes[id] = &dnode{at: at}
	}
	better := func(at time.Time, cost float64, cur *dnode) bool {
		if at.Before(cur.at) {
			return true
		}
		return at.Equal(cur.at) && cost < cur.cost
	}
	for {
		var curID string
		var cur *dnode
		for id, n := range nodes {
			if n.visited {
				continue
			}
			if cur == nil || better(n.at, n.cost, cur) || (n.at.Equal(cur.at) && n.cost == cur.cost && id < curID) {
				curID, cur = id, n
			}
		}
		if cur == nil {
			break
		}
		cur.visited = true
		for _, cn := range a.state.Connections {
			if cn.FromLocationID != curID || !a.connAdmitted(cn, in, cooled, checkCap) {
				continue
			}
			to := cn.ToLocationID
			if !a.nodeAdmitted(to, in, cooled, checkCap) || to == in.StartNode {
				continue
			}
			l := a.state.Locations[to]
			at := cur.at.Add(time.Duration(cn.TravelMinutes+l.HandlingMinutes) * time.Minute)
			cost := cur.cost + cn.CostUnits
			if ex, ok := nodes[to]; ok {
				if ex.visited || !better(at, cost, ex) {
					continue
				}
				ex.at, ex.cost, ex.prev, ex.prevConn = at, cost, curID, cn.ID
			} else {
				nodes[to] = &dnode{at: at, cost: cost, prev: curID, prevConn: cn.ID}
			}
		}
	}
	var bestID string
	var best *dnode
	for id, n := range nodes {
		if !labs[id] {
			continue
		}
		if best == nil || better(n.at, n.cost, best) || (n.at.Equal(best.at) && n.cost == best.cost && id < bestID) {
			bestID, best = id, n
		}
	}
	if best == nil {
		return nil
	}
	res := &planResult{Reason: "serviceable", Lab: bestID, ETA: best.at, Cost: best.cost, Cooled: cooled}
	for id := bestID; id != ""; {
		n := nodes[id]
		res.Path = append([]string{id}, res.Path...)
		res.Arrivals = append([]time.Time{n.at}, res.Arrivals...)
		if n.prevConn != "" {
			res.Conns = append([]string{n.prevConn}, res.Conns...)
		}
		id = n.prev
	}
	if in.StartNode == "" {
		res.FirstMileMinutes = firstMileMinutes(*in.StartCoord, a.state.Locations[res.Path[0]].Coordinate)
	}
	return res
}

// plan finds the fastest valid route to an accepting laboratory. The returned
// Reason explains why no route exists.
func (a *App) plan(in planInput) *planResult {
	if in.Units <= 0 {
		in.Units = 1
	}
	labs := a.acceptingLabs(in.Types)
	if len(labs) == 0 {
		return &planResult{Reason: "no_accepting_laboratory"}
	}
	entries := a.entryNodes(in)
	if len(entries) == 0 {
		return &planResult{Reason: "outside_service_coverage"}
	}
	cooled := in.cooled()
	structural := a.dijkstra(in, entries, labs, cooled, false)
	if structural == nil {
		if cooled && a.dijkstra(in, entries, labs, false, false) != nil {
			return &planResult{Reason: "handling_rules_unsatisfiable"}
		}
		return &planResult{Reason: "no_route"}
	}
	withCap := a.dijkstra(in, entries, labs, cooled, true)
	if withCap == nil {
		return &planResult{Reason: "insufficient_capacity", ETA: structural.ETA, Lab: structural.Lab}
	}
	if withCap.ETA.After(in.Deadline) {
		return &planResult{Reason: "deadline_unreachable", ETA: withCap.ETA, Lab: withCap.Lab}
	}
	return withCap
}

// findConnection returns the best active connection between two nodes.
func (a *App) findConnection(from, to string, cooled bool) *Connection {
	var best *Connection
	for _, cn := range a.state.Connections {
		if cn.FromLocationID != from || cn.ToLocationID != to || !cn.Active {
			continue
		}
		if cooled && !cn.Cooled {
			continue
		}
		if best == nil || cn.TravelMinutes < best.TravelMinutes || (cn.TravelMinutes == best.TravelMinutes && cn.ID < best.ID) {
			best = cn
		}
	}
	return best
}

// validatePath checks an explicit path (entry node .. laboratory) against the
// same criteria as the planner and returns the timing if valid.
func (a *App) validatePath(in planInput, path []string) (*planResult, *apiError) {
	if len(path) == 0 {
		return nil, conflict("invalid_route", "route has no stops")
	}
	cooled := in.cooled()
	units := in.Units
	if units <= 0 {
		units = 1
	}
	seen := map[string]bool{}
	for _, id := range path {
		if seen[id] {
			return nil, conflict("ambiguous_stop", "location %s appears more than once in the route", id)
		}
		seen[id] = true
		if a.state.Locations[id] == nil {
			return nil, conflict("invalid_stop", "unknown location %s", id)
		}
	}
	res := &planResult{Reason: "serviceable", Cooled: cooled}
	var at time.Time
	if in.StartNode != "" {
		if path[0] != in.StartNode {
			return nil, conflict("invalid_stop_order", "route must start at the current position")
		}
		at = in.StartAt
	} else {
		entry := a.state.Locations[path[0]]
		if !entry.Fn(FnCollection) || haversineKm(*in.StartCoord, entry.Coordinate) > math.Min(entry.CoverageKm, 5) {
			return nil, conflict("invalid_stop", "first stop must be an active collection point covering the origin")
		}
		res.FirstMileMinutes = firstMileMinutes(*in.StartCoord, entry.Coordinate)
		at = in.StartAt.Add(time.Duration(res.FirstMileMinutes+entry.HandlingMinutes) * time.Minute)
	}
	res.Arrivals = append(res.Arrivals, at)
	for i, id := range path {
		l := a.state.Locations[id]
		if id != in.StartNode && !l.Active {
			return nil, conflict("invalid_stop", "location %s is inactive", l.Name)
		}
		if a.available(id, cooled, in.IgnoreJourney) < units {
			if cooled {
				return nil, conflict("cooled_capacity_exhausted", "no cooled capacity at %s", l.Name)
			}
			return nil, conflict("capacity_exhausted", "no capacity at %s", l.Name)
		}
		if i == len(path)-1 {
			break
		}
		next := path[i+1]
		cn := a.findConnection(id, next, cooled)
		if cn == nil {
			return nil, conflict("invalid_route", "no active connection from %s to %s", l.Name, a.state.Locations[next].Name)
		}
		if a.available(cn.ID, cooled, in.IgnoreJourney) < units {
			if cooled {
				return nil, conflict("cooled_capacity_exhausted", "no cooled capacity on connection %s", cn.ID)
			}
			return nil, conflict("capacity_exhausted", "no capacity on connection %s", cn.ID)
		}
		res.Conns = append(res.Conns, cn.ID)
		res.Cost += cn.CostUnits
		at = at.Add(time.Duration(cn.TravelMinutes+a.state.Locations[next].HandlingMinutes) * time.Minute)
		res.Arrivals = append(res.Arrivals, at)
	}
	lab := a.state.Locations[path[len(path)-1]]
	if !lab.Fn(FnLab) {
		return nil, conflict("invalid_destination", "final stop must be an active laboratory")
	}
	for _, t := range in.Types {
		if !lab.Accepts(t.ID) {
			return nil, conflict("invalid_destination", "laboratory %s does not accept sample type %s", lab.Name, t.Name)
		}
	}
	res.Path = append([]string{}, path...)
	res.Lab = lab.ID
	res.ETA = at
	if at.After(in.Deadline) {
		return nil, conflict("deadline_exceeded", "route would arrive at %s, after the delivery deadline", fmtTime(at))
	}
	return res, nil
}

