package app

import (
	"context"
	"log"
	"sort"
	"time"
)

func roleForKind(kind string) string {
	switch kind {
	case KindCollection:
		return RoleCollector
	case KindTransport:
		return RoleCourier
	case KindNode:
		return RoleNode
	case KindLab:
		return RoleLab
	}
	return ""
}

func (a *App) hasQualification(u *User, code string, now time.Time) bool {
	if containsStr(u.Qualifications, code) {
		return true
	}
	for _, ct := range u.Certifications {
		if ct.Code == code && ct.Active && (ct.ExpiresAt == nil || ct.ExpiresAt.After(now)) {
			return true
		}
	}
	return false
}

// qualified reports whether the user may perform the assignment regardless of
// current workload.
func (a *App) qualified(u *User, asg *Assignment, now time.Time) bool {
	if !u.Active || !u.HasRole(roleForKind(asg.Kind)) {
		return false
	}
	switch asg.Kind {
	case KindCollection:
		s := a.state.Samples[asg.SampleID]
		if s == nil {
			return false
		}
		t := a.state.SampleTypes[s.SampleTypeID]
		if t != nil && t.QualifiedCollectorRequired && !a.hasQualification(u, t.QualificationCode(), now) {
			return false
		}
	case KindNode:
		if u.AssignedLocationID == "" || u.AssignedLocationID != asg.NodeID {
			return false
		}
	case KindLab:
		if u.AssignedLocationID == "" || u.AssignedLocationID != asg.LaboratoryID {
			return false
		}
	}
	return true
}

func (a *App) activeAssignmentCount(userID string) int {
	n := 0
	for _, asg := range a.state.Assignments {
		if asg.WorkerID == userID && !asg.Finished() && asg.Status != AsgPending {
			n++
		}
	}
	return n
}

func (a *App) recentAssignmentCount(userID string, since time.Time) int {
	n := 0
	for _, asg := range a.state.Assignments {
		if asg.WorkerID == userID && asg.OfferedAt != nil && asg.OfferedAt.After(since) {
			n++
		}
	}
	return n
}

func (a *App) eligibleForOffer(u *User, asg *Assignment, now time.Time) bool {
	if !u.Available || containsStr(asg.DeclinedBy, u.ID) || !a.qualified(u, asg, now) {
		return false
	}
	return a.activeAssignmentCount(u.ID) < u.CapacityUnits
}

// offer picks the fairest eligible worker and offers the assignment to them.
func (a *App) offer(tx *Tx, asg *Assignment) bool {
	type cand struct {
		u        *User
		penalty  bool
		active   int
		recent   int
		lastTime time.Time
	}
	var cands []cand
	for _, u := range tx.st.Users {
		if !a.eligibleForOffer(u, asg, tx.now) {
			continue
		}
		c := cand{u: u, active: a.activeAssignmentCount(u.ID), recent: a.recentAssignmentCount(u.ID, tx.now.Add(-24*time.Hour))}
		if u.PenaltyUntil != nil && u.PenaltyUntil.After(tx.now) {
			c.penalty = true
		}
		if u.LastOfferedAt != nil {
			c.lastTime = *u.LastOfferedAt
		}
		cands = append(cands, c)
	}
	s := tx.st.Samples[asg.SampleID]
	if len(cands) == 0 {
		if asg.Status != AsgPending || asg.WorkerID != "" {
			asg.Status = AsgPending
			asg.WorkerID = ""
			asg.OfferExpiresAt = nil
			tx.MarkAssignment(asg)
		}
		if s != nil {
			tx.Audit("assignment_unassigned", "assignment", asg.ID, s.ID, false, map[string]any{"reason": "no_eligible_worker", "kind": asg.Kind})
		}
		a.emitAssignment(tx, asg)
		return false
	}
	sort.Slice(cands, func(i, k int) bool {
		x, y := cands[i], cands[k]
		if x.penalty != y.penalty {
			return !x.penalty
		}
		if x.active != y.active {
			return x.active < y.active
		}
		if x.recent != y.recent {
			return x.recent < y.recent
		}
		if !x.lastTime.Equal(y.lastTime) {
			return x.lastTime.Before(y.lastTime)
		}
		return x.u.ID < y.u.ID
	})
	w := cands[0].u
	asg.Status = AsgOffered
	asg.WorkerID = w.ID
	asg.OfferedAt = timePtr(tx.now)
	asg.OfferExpiresAt = timePtr(tx.now.Add(a.cfg.OfferTimeout))
	asg.OfferCount++
	tx.MarkAssignment(asg)
	w.LastOfferedAt = timePtr(tx.now)
	tx.MarkUser(w)
	if s != nil {
		tx.SampleEvent(s, "assignment_offered", "assignment", asg.ID, map[string]any{"assignmentId": asg.ID, "kind": asg.Kind, "workerId": w.ID, "offerExpiresAt": fmtTime(*asg.OfferExpiresAt), "offerCount": asg.OfferCount})
		if s.Exception != nil && s.Exception["reason"] == "no_qualified_worker" && s.Exception["assignmentId"] == asg.ID {
			a.clearException(tx, s)
		}
	}
	a.emitAssignment(tx, asg)
	return true
}

func (a *App) clearException(tx *Tx, s *Sample) {
	prev, _ := s.Exception["previousStatus"].(string)
	if prev == "" {
		prev = SampleRequested
	}
	if s.Status == SampleException {
		s.Status = prev
	}
	s.Exception = nil
	tx.SampleEvent(s, "exception_cleared", "sample", s.ID, map[string]any{"status": s.Status})
	a.emitSample(tx, s)
}

func (a *App) flagException(tx *Tx, s *Sample, reason string, details map[string]any) {
	if details == nil {
		details = map[string]any{}
	}
	ex := map[string]any{"exceptionId": newID(), "reason": reason, "occurredAt": fmtTime(tx.now), "previousStatus": s.Status, "recordedBy": tx.actorID()}
	for k, v := range details {
		ex[k] = v
	}
	if s.Exception != nil {
		if prev, ok := s.Exception["previousStatus"]; ok {
			ex["previousStatus"] = prev
		}
	}
	s.Exception = ex
	if !s.Terminal() {
		s.Status = SampleException
	}
	tx.SampleEvent(s, "exception_recorded", "sample", s.ID, map[string]any{"reason": reason, "exception": ex})
	a.emitSample(tx, s)
}

// retryPendingOffers offers every unassigned assignment of active journeys.
func (a *App) retryPendingOffers(tx *Tx) {
	for _, id := range sortedKeys(tx.st.Assignments) {
		asg := tx.st.Assignments[id]
		if asg.Status != AsgPending || asg.WorkerID != "" {
			continue
		}
		j := tx.st.Journeys[asg.JourneyID]
		if j == nil || !j.IsActive() {
			continue
		}
		if len(a.eligibleCandidates(asg, tx.now)) == 0 {
			continue
		}
		a.offer(tx, asg)
	}
}

func (a *App) eligibleCandidates(asg *Assignment, now time.Time) []*User {
	var out []*User
	for _, u := range a.state.Users {
		if a.eligibleForOffer(u, asg, now) {
			out = append(out, u)
		}
	}
	return out
}

// reofferIneligible re-offers open offers whose worker is no longer qualified.
func (a *App) reofferIneligible(tx *Tx) {
	for _, id := range sortedKeys(tx.st.Assignments) {
		asg := tx.st.Assignments[id]
		if asg.Status != AsgOffered {
			continue
		}
		w := tx.st.Users[asg.WorkerID]
		if w != nil && w.Available && a.qualified(w, asg, tx.now) {
			continue
		}
		s := tx.st.Samples[asg.SampleID]
		if s != nil {
			tx.SampleEvent(s, "offer_withdrawn", "assignment", asg.ID, map[string]any{"assignmentId": asg.ID, "workerId": asg.WorkerID, "reason": "worker_ineligible"})
		}
		asg.Status = AsgPending
		asg.WorkerID = ""
		asg.OfferExpiresAt = nil
		tx.MarkAssignment(asg)
		a.offer(tx, asg)
	}
}

func (a *App) expireOffers(tx *Tx) {
	for _, id := range sortedKeys(tx.st.Assignments) {
		asg := tx.st.Assignments[id]
		if asg.Status != AsgOffered || asg.OfferExpiresAt == nil || asg.OfferExpiresAt.After(tx.now) {
			continue
		}
		s := tx.st.Samples[asg.SampleID]
		w := tx.st.Users[asg.WorkerID]
		if s != nil {
			tx.SampleEvent(s, "offer_expired", "assignment", asg.ID, map[string]any{"assignmentId": asg.ID, "workerId": asg.WorkerID, "treatedAs": "declined"})
		}
		asg.DeclinedBy = append(asg.DeclinedBy, asg.WorkerID)
		asg.Status = AsgPending
		asg.WorkerID = ""
		asg.OfferExpiresAt = nil
		tx.MarkAssignment(asg)
		if w != nil {
			a.recordDecline(tx, w)
		}
		a.offer(tx, asg)
	}
}

func (a *App) flagStalledAssignments(tx *Tx) {
	for _, id := range sortedKeys(tx.st.Assignments) {
		asg := tx.st.Assignments[id]
		if asg.Status != AsgPending || asg.WorkerID != "" {
			continue
		}
		j := tx.st.Journeys[asg.JourneyID]
		s := tx.st.Samples[asg.SampleID]
		if j == nil || !j.IsActive() || s == nil || s.Terminal() || s.Exception != nil {
			continue
		}
		if tx.now.Sub(asg.CreatedAt) < a.cfg.NoWorkerGrace {
			continue
		}
		qualifiedExists := false
		for _, u := range tx.st.Users {
			if a.qualified(u, asg, tx.now) {
				qualifiedExists = true
				break
			}
		}
		a.flagException(tx, s, "no_qualified_worker", map[string]any{"assignmentId": asg.ID, "kind": asg.Kind, "qualifiedWorkerExists": qualifiedExists,
			"message": "no qualified worker became available within the allowed time"})
	}
}

func (a *App) recordDecline(tx *Tx, w *User) {
	cutoff := tx.now.Add(-24 * time.Hour)
	var kept []time.Time
	for _, t := range w.DeclineTimes {
		if t.After(cutoff) {
			kept = append(kept, t)
		}
	}
	kept = append(kept, tx.now)
	w.DeclineTimes = kept
	recent := 0
	for _, t := range kept {
		if t.After(tx.now.Add(-time.Hour)) {
			recent++
		}
	}
	if recent >= 3 {
		w.PenaltyUntil = timePtr(tx.now.Add(30 * time.Minute))
	}
	tx.MarkUser(w)
}

// Scheduler runs periodic housekeeping: offer expiry, retries and stall detection.
func (a *App) RunScheduler(ctx context.Context) {
	t := time.NewTicker(2 * time.Second)
	defer t.Stop()
	for {
		select {
		case <-ctx.Done():
			return
		case <-a.stopCh:
			return
		case <-t.C:
			err := a.runSystemTx(ctx, func(tx *Tx) error {
				a.expireOffers(tx)
				a.retryPendingOffers(tx)
				a.flagStalledAssignments(tx)
				return nil
			})
			if err != nil {
				log.Printf("scheduler: %v", err)
			}
		}
	}
}

// ---- handlers ----

func (a *App) loadAssignment(c *reqCtx, id string) (*Assignment, *Sample, *apiError) {
	asg := c.st().Assignments[id]
	if asg == nil {
		return nil, nil, notFound("assignment")
	}
	s := c.st().Samples[asg.SampleID]
	if s == nil {
		return nil, nil, notFound("sample")
	}
	return asg, s, nil
}

func (a *App) handleAcceptAssignment(c *reqCtx, body []byte) (int, any, *apiError) {
	type in struct {
		AssignmentID   string `json:"assignmentId"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	req, e := decodeBody[in](body, "assignmentId", "idempotencyKey")
	if e != nil {
		return 0, nil, e
	}
	asg, s, e := a.loadAssignment(c, req.AssignmentID)
	if e != nil {
		return 0, nil, e
	}
	me := c.user
	if c.role != roleForKind(asg.Kind) {
		return 0, nil, errf(403, "ineligible_worker", "your active role cannot perform %s assignments", asg.Kind)
	}
	if asg.Finished() {
		return 0, nil, conflict("assignment_inactive", "assignment is %s", asg.Status)
	}
	if asg.Status != AsgOffered {
		if asg.WorkerID == me.ID {
			return 201, map[string]any{"assignmentId": asg.ID, "workerId": me.ID, "status": "accepted"}, nil
		}
		if asg.WorkerID != "" {
			return 0, nil, conflict("assignment_taken", "assignment was already accepted by another worker")
		}
		return 0, nil, conflict("offer_not_available", "assignment is not currently offered")
	}
	if asg.WorkerID != me.ID {
		c.tx.Audit("assignment_accept_rejected", "assignment", asg.ID, s.ID, false, map[string]any{"reason": "offer_not_offered", "offeredTo": asg.WorkerID})
		return 0, nil, conflict("offer_not_offered", "this assignment was offered to a different worker")
	}
	if !a.qualified(me, asg, c.now()) {
		return 0, nil, errf(403, "ineligible_worker", "you are not eligible for this assignment")
	}
	if !me.Available {
		return 0, nil, conflict("worker_unavailable", "you are marked unavailable")
	}
	asg.Status = AsgAccepted
	asg.AcceptedAt = timePtr(c.now())
	asg.OfferExpiresAt = nil
	c.tx.MarkAssignment(asg)
	c.tx.SampleEvent(s, "assignment_accepted", "assignment", asg.ID, map[string]any{"assignmentId": asg.ID, "kind": asg.Kind, "workerId": me.ID})
	a.emitAssignment(c.tx, asg)
	return 201, map[string]any{"assignmentId": asg.ID, "workerId": me.ID, "status": "accepted"}, nil
}

func (a *App) handleDeclineAssignment(c *reqCtx, body []byte) (int, any, *apiError) {
	type in struct {
		AssignmentID   string  `json:"assignmentId"`
		Reason         string  `json:"reason"`
		DeclinedAt     *string `json:"declinedAt"`
		IdempotencyKey string  `json:"idempotencyKey"`
	}
	req, e := decodeBody[in](body, "assignmentId", "idempotencyKey")
	if e != nil {
		return 0, nil, e
	}
	declinedAt, e := optTime(req.DeclinedAt)
	if e != nil {
		return 0, nil, e
	}
	asg, s, e := a.loadAssignment(c, req.AssignmentID)
	if e != nil {
		return 0, nil, e
	}
	me := c.user
	if asg.Finished() || asg.Status != AsgOffered || asg.WorkerID != me.ID {
		return 0, nil, conflict("offer_not_available", "this assignment is not currently offered to you")
	}
	at := c.now()
	if declinedAt != nil {
		at = *declinedAt
	}
	asg.DeclinedBy = append(asg.DeclinedBy, me.ID)
	asg.Status = AsgPending
	asg.WorkerID = ""
	asg.OfferExpiresAt = nil
	c.tx.MarkAssignment(asg)
	a.recordDecline(c.tx, me)
	c.tx.SampleEvent(s, "assignment_declined", "assignment", asg.ID, map[string]any{"assignmentId": asg.ID, "kind": asg.Kind, "workerId": me.ID, "reason": req.Reason, "declinedAt": fmtTime(at)})
	a.offer(c.tx, asg)
	out := map[string]any{"assignmentId": asg.ID, "status": "pending", "declinedBy": me.ID, "declinedAt": fmtTime(at)}
	if asg.WorkerID != "" {
		out["reofferedTo"] = asg.WorkerID
	}
	return 201, out, nil
}

var transportOrder = map[string]int{AsgAccepted: 0, AsgAtPickup: 1, AsgPickedUp: 2, AsgInTransit: 3, AsgArrived: 4, AsgDelivered: 5, AsgCompleted: 5}
var stationaryOrder = map[string]int{AsgAccepted: 0, AsgInProgress: 1, AsgCompleted: 2}

func (a *App) priorAssignment(asg *Assignment) *Assignment {
	var prior *Assignment
	for _, x := range a.journeyAssignments(asg.JourneyID) {
		if x.SampleID != asg.SampleID || x.Status == AsgCancelled || x.ID == asg.ID {
			continue
		}
		if x.Sequence < asg.Sequence {
			prior = x
		}
	}
	return prior
}

func (a *App) nextAssignment(asg *Assignment) *Assignment {
	for _, x := range a.journeyAssignments(asg.JourneyID) {
		if x.SampleID == asg.SampleID && x.Status != AsgCancelled && x.Sequence > asg.Sequence {
			return x
		}
	}
	return nil
}

func (a *App) handleUpdateProgress(c *reqCtx, body []byte) (int, any, *apiError) {
	type in struct {
		AssignmentID   string `json:"assignmentId"`
		Status         string `json:"status"`
		OccurredAt     string `json:"occurredAt"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	req, e := decodeBody[in](body, "assignmentId", "status", "occurredAt", "idempotencyKey")
	if e != nil {
		return 0, nil, e
	}
	at, e := reqTime(req.OccurredAt)
	if e != nil {
		return 0, nil, e
	}
	valid := map[string]bool{AsgAtPickup: true, AsgPickedUp: true, AsgInTransit: true, AsgArrived: true, AsgDelivered: true, AsgInProgress: true, AsgCompleted: true}
	if !valid[req.Status] {
		return 0, nil, badJSON("invalid status %q", req.Status)
	}
	asg, s, e := a.loadAssignment(c, req.AssignmentID)
	if e != nil {
		return 0, nil, e
	}
	me := c.user
	if asg.WorkerID != me.ID {
		return 0, nil, forbidden("this assignment is not assigned to you")
	}
	if c.role != roleForKind(asg.Kind) {
		return 0, nil, errf(403, "ineligible_worker", "your active role cannot work on %s assignments", asg.Kind)
	}
	if asg.Status == AsgCancelled {
		return 0, nil, conflict("assignment_inactive", "assignment is cancelled")
	}
	if asg.Status == AsgPending || asg.Status == AsgOffered {
		return 0, nil, conflict("assignment_not_ready", "accept the assignment before reporting progress")
	}
	if s.Status == SampleCancelled || s.Status == SampleExpired || s.Status == SampleUnserviceable {
		return 0, nil, conflict("invalid_sample_state", "sample is %s", s.Status)
	}
	j := c.st().Journeys[asg.JourneyID]
	if j == nil || !j.IsActive() {
		return 0, nil, conflict("assignment_inactive", "journey is no longer active")
	}
	if asg.LastProgressAt != nil && at.Before(*asg.LastProgressAt) {
		return 0, nil, conflict("invalid_progress_time", "occurredAt is earlier than the previous progress update")
	}
	order := stationaryOrder
	if asg.Kind == KindTransport {
		order = transportOrder
	}
	target, ok := order[req.Status]
	if !ok {
		return 0, nil, conflict("invalid_transition", "status %q is not valid for %s assignments", req.Status, asg.Kind)
	}
	current := order[asg.Status]
	if req.Status == asg.Status || (asg.Status == AsgCompleted && target == order[AsgCompleted]) {
		return 201, map[string]any{"assignmentId": asg.ID, "sampleId": s.ID, "status": asg.Status}, nil
	}
	if asg.Status == AsgCompleted {
		return 0, nil, conflict("assignment_inactive", "assignment is already completed")
	}
	if target <= current {
		return 0, nil, conflict("invalid_transition", "cannot move from %s to %s", asg.Status, req.Status)
	}
	holder := s.CurrentHolderID == me.ID
	switch asg.Kind {
	case KindTransport:
		switch req.Status {
		case AsgPickedUp, AsgInTransit, AsgArrived:
			if !s.Sealed {
				return 0, nil, conflict("collection_required", "the sample has not been collected and sealed yet")
			}
			if prior := a.priorAssignment(asg); prior != nil && prior.Status != AsgCompleted && !holder {
				return 0, nil, conflict("prior_leg_incomplete", "the previous leg has not been completed")
			}
			if !holder {
				return 0, nil, conflict("custody_required", "confirm the handoff into your custody first")
			}
		case AsgDelivered, AsgCompleted:
			if holder {
				return 0, nil, conflict("invalid_transition", "hand the sample off before marking the leg delivered")
			}
			if !s.Sealed {
				return 0, nil, conflict("collection_required", "the sample has not been collected yet")
			}
		}
	case KindCollection:
		if req.Status == AsgCompleted {
			if !s.Sealed {
				return 0, nil, conflict("collection_required", "collect and seal the sample first")
			}
			if holder {
				return 0, nil, conflict("invalid_transition", "hand the sealed sample off before completing the collection")
			}
		}
	case KindNode:
		if req.Status == AsgCompleted && holder {
			return 0, nil, conflict("invalid_transition", "hand the sample off before completing the node assignment")
		}
	case KindLab:
		if req.Status == AsgCompleted && s.Status != SampleReceived {
			return 0, nil, conflict("invalid_transition", "confirm laboratory receipt before completing the assignment")
		}
	}
	from := asg.Status
	asg.Status = req.Status
	asg.LastProgressAt = &at
	if req.Status == AsgCompleted || req.Status == AsgDelivered {
		asg.CompletedAt = &at
		if req.Status == AsgDelivered {
			asg.Status = AsgCompleted
		}
	}
	c.tx.MarkAssignment(asg)
	if asg.Kind == KindTransport && holder {
		switch req.Status {
		case AsgAtPickup:
			if asg.FromCoordinate != nil {
				a.setSampleLocation(c.tx, s, *asg.FromCoordinate, at)
			}
		case AsgInTransit:
			if s.Status != SampleException {
				s.Status = SampleInTransit
			}
		case AsgArrived:
			if asg.ToCoordinate != nil {
				a.setSampleLocation(c.tx, s, *asg.ToCoordinate, at)
			}
		}
	}
	c.tx.SampleEvent(s, "assignment_progress", "assignment", asg.ID, map[string]any{"assignmentId": asg.ID, "kind": asg.Kind, "from": from, "to": asg.Status, "occurredAt": fmtTime(at), "workerId": me.ID})
	a.emitAssignment(c.tx, asg)
	a.emitSample(c.tx, s)
	return 201, map[string]any{"assignmentId": asg.ID, "sampleId": s.ID, "status": asg.Status}, nil
}

func (a *App) setSampleLocation(tx *Tx, s *Sample, coord Coordinate, at time.Time) {
	if s.LocationRecordedAt != nil && at.Before(*s.LocationRecordedAt) {
		return
	}
	c := coord
	s.LatestLocation = &c
	s.LocationRecordedAt = &at
	tx.MarkSample(s)
}

func (a *App) handleRecordWorkerLocation(c *reqCtx, body []byte) (int, any, *apiError) {
	type in struct {
		AssignmentID string     `json:"assignmentId"`
		Coordinate   Coordinate `json:"coordinate"`
		Sequence     *int       `json:"sequence"`
		RecordedAt   string     `json:"recordedAt"`
	}
	req, e := decodeBody[in](body, "assignmentId", "coordinate", "sequence", "recordedAt")
	if e != nil {
		return 0, nil, e
	}
	if !validCoordinate(req.Coordinate) {
		return 0, nil, errf(400, "invalid_coordinate", "coordinate out of range")
	}
	if *req.Sequence < 1 {
		return 0, nil, errf(400, "invalid_sequence", "sequence must be at least 1")
	}
	at, e := reqTime(req.RecordedAt)
	if e != nil {
		return 0, nil, e
	}
	asg, s, e := a.loadAssignment(c, req.AssignmentID)
	if e != nil {
		return 0, nil, e
	}
	if asg.WorkerID != c.user.ID {
		return 0, nil, forbidden("this assignment is not assigned to you")
	}
	if *req.Sequence <= asg.LastLocationSeq {
		return 0, nil, errf(400, "invalid_sequence", "sequence must be greater than %d", asg.LastLocationSeq)
	}
	if asg.LastLocationAt != nil && at.Before(*asg.LastLocationAt) {
		return 0, nil, conflict("stale_location", "recordedAt is older than the latest recorded location")
	}
	asg.LastLocationSeq = *req.Sequence
	asg.LastLocationAt = &at
	c.tx.MarkAssignment(asg)
	u := c.user
	coord := req.Coordinate
	u.LatestLocation = &coord
	u.LocationRecordedAt = &at
	c.tx.MarkUser(u)
	if s.CurrentHolderID == u.ID {
		a.setSampleLocation(c.tx, s, coord, at)
	}
	c.tx.SampleEvent(s, "worker_location_recorded", "assignment", asg.ID, map[string]any{"assignmentId": asg.ID, "workerId": u.ID, "coordinate": coord, "sequence": *req.Sequence, "recordedAt": fmtTime(at), "holder": s.CurrentHolderID == u.ID})
	c.tx.Emit("worker.location", "user", u.ID, map[string]any{"workerId": u.ID, "coordinate": coord, "recordedAt": fmtTime(at), "assignmentId": asg.ID, "participantIds": []string{u.ID}})
	a.emitSample(c.tx, s)
	return 201, map[string]any{"assignmentId": asg.ID, "coordinate": coord, "sequence": *req.Sequence, "recordedAt": fmtTime(at)}, nil
}

func (a *App) handleSetWorkerAvailability(c *reqCtx, body []byte) (int, any, *apiError) {
	type in struct {
		WorkerID      string `json:"workerId"`
		Available     *bool  `json:"available"`
		CapacityUnits *int   `json:"capacityUnits"`
	}
	req, e := decodeBody[in](body, "workerId", "available", "capacityUnits")
	if e != nil {
		return 0, nil, e
	}
	if *req.CapacityUnits < 0 {
		return 0, nil, errf(400, "invalid_capacity", "capacityUnits must not be negative")
	}
	w := c.st().Users[req.WorkerID]
	if w == nil {
		return 0, nil, notFound("worker")
	}
	if w.ID != c.user.ID && c.role != RoleAdmin && c.role != RoleDispatcher {
		return 0, nil, forbidden("you may only change your own availability")
	}
	active := a.activeAssignmentCount(w.ID)
	if *req.CapacityUnits < active {
		return 0, nil, conflict("capacity_reserved", "worker currently holds %d active assignments", active)
	}
	before := map[string]any{"available": w.Available, "capacityUnits": w.CapacityUnits}
	w.Available = *req.Available
	w.CapacityUnits = *req.CapacityUnits
	c.tx.MarkUser(w)
	c.tx.Audit("worker_availability_changed", "user", w.ID, "", true, map[string]any{"before": before, "after": map[string]any{"available": w.Available, "capacityUnits": w.CapacityUnits}})
	c.tx.Emit("user.updated", "user", w.ID, userEventPayload(w))
	if !w.Available {
		a.reofferIneligible(c.tx)
	} else {
		a.retryPendingOffers(c.tx)
	}
	return 200, map[string]any{"workerId": w.ID, "available": w.Available, "capacityUnits": w.CapacityUnits}, nil
}

