package app

import (
	"strings"
	"time"
)

type requestInput struct {
	RequesterID             string     `json:"requesterId"`
	Origin                  Coordinate `json:"origin"`
	OriginType              string     `json:"originType"`
	OriginNodeID            string     `json:"originNodeId"`
	RequestedAt             string     `json:"requestedAt"`
	DeliveryDeadline        string     `json:"deliveryDeadline"`
	EarliestCollectionAt    *string    `json:"earliestCollectionAt"`
	LatestCollectionAt      *string    `json:"latestCollectionAt"`
	SampleTypeID            string     `json:"sampleTypeId"`
	ContainerType           string     `json:"containerType"`
	TemperatureMinC         *float64   `json:"temperatureMinC"`
	TemperatureMaxC         *float64   `json:"temperatureMaxC"`
	IncompatibleSampleTypes []string   `json:"incompatibleSampleTypes"`
	IdempotencyKey          string     `json:"idempotencyKey"`
}

type parsedRequest struct {
	Origin       Coordinate
	OriginType   string
	OriginNode   *Location
	RequestedAt  time.Time
	Deadline     time.Time
	Earliest     time.Time
	Latest       time.Time
	SampleType   *SampleType
}

// parseRequestCommon validates the fields shared by serviceability checks and
// request creation. allowedTypes restricts originType.
func (a *App) parseRequestCommon(c *reqCtx, in *requestInput, allowedTypes []string, defaultType string) (*parsedRequest, *apiError) {
	p := &parsedRequest{Origin: in.Origin, OriginType: in.OriginType}
	if p.OriginType == "" {
		p.OriginType = defaultType
	}
	if !containsStr(allowedTypes, p.OriginType) {
		return nil, errf(400, "invalid_origin_type", "originType must be one of %s", strings.Join(allowedTypes, ", "))
	}
	if !validCoordinate(p.Origin) {
		return nil, errf(400, "invalid_origin", "origin coordinate out of range")
	}
	if p.OriginType == "node" {
		if in.OriginNodeID == "" {
			return nil, errf(400, "invalid_origin", "originNodeId is required for node origins")
		}
		node := c.st().Locations[in.OriginNodeID]
		if node == nil {
			return nil, notFound("origin node")
		}
		if !node.Active {
			return nil, errf(400, "invalid_origin_state", "origin node is inactive")
		}
		p.OriginNode = node
		p.Origin = node.Coordinate
	}
	var e *apiError
	if p.RequestedAt, e = reqTime(in.RequestedAt); e != nil {
		return nil, e
	}
	if p.Deadline, e = reqTime(in.DeliveryDeadline); e != nil {
		return nil, e
	}
	if !p.Deadline.After(p.RequestedAt) {
		return nil, errf(400, "invalid_deadline", "deliveryDeadline must be after requestedAt")
	}
	earliest, e := optTime(in.EarliestCollectionAt)
	if e != nil {
		return nil, e
	}
	latest, e := optTime(in.LatestCollectionAt)
	if e != nil {
		return nil, e
	}
	p.Earliest = p.RequestedAt
	if earliest != nil {
		p.Earliest = *earliest
	}
	p.Latest = p.Deadline
	if latest != nil {
		p.Latest = *latest
	}
	if p.Latest.Before(p.Earliest) || p.Earliest.Before(p.RequestedAt) || p.Latest.After(p.Deadline) {
		return nil, errf(400, "invalid_collection_window", "collection window must lie between requestedAt and deliveryDeadline, with earliest before latest")
	}
	if in.SampleTypeID == "" {
		return nil, badJSON("sampleTypeId is required")
	}
	p.SampleType = c.st().SampleTypes[in.SampleTypeID]
	if p.SampleType == nil {
		return nil, notFound("sample type")
	}
	return p, nil
}

func (a *App) planFor(p *parsedRequest, startAt time.Time) *planResult {
	in := planInput{StartAt: startAt, Types: []*SampleType{p.SampleType}, Deadline: p.Deadline, Units: 1}
	if p.OriginNode != nil {
		in.StartNode = p.OriginNode.ID
	} else {
		o := p.Origin
		in.StartCoord = &o
	}
	return a.plan(in)
}

func (a *App) handleCheckServiceability(c *reqCtx, body []byte) (int, any, *apiError) {
	type in struct {
		Origin               Coordinate `json:"origin"`
		OriginType           string     `json:"originType"`
		OriginNodeID         string     `json:"originNodeId"`
		SampleTypeID         string     `json:"sampleTypeId"`
		RequestedAt          string     `json:"requestedAt"`
		DeliveryDeadline     string     `json:"deliveryDeadline"`
		EarliestCollectionAt *string    `json:"earliestCollectionAt"`
		LatestCollectionAt   *string    `json:"latestCollectionAt"`
	}
	req, e := decodeBody[in](body, "origin", "sampleTypeId", "requestedAt", "deliveryDeadline")
	if e != nil {
		return 0, nil, e
	}
	ri := &requestInput{Origin: req.Origin, OriginType: req.OriginType, OriginNodeID: req.OriginNodeID, SampleTypeID: req.SampleTypeID,
		RequestedAt: req.RequestedAt, DeliveryDeadline: req.DeliveryDeadline, EarliestCollectionAt: req.EarliestCollectionAt, LatestCollectionAt: req.LatestCollectionAt}
	p, e := a.parseRequestCommon(c, ri, []string{"home", "clinic", "node"}, "home")
	if e != nil {
		return 0, nil, e
	}
	plan := a.planFor(p, p.Earliest)
	snap := c.st().Meta.Snapshot
	out := map[string]any{"serviceable": plan.Reason == "serviceable", "reason": plan.Reason, "serviceabilityVersion": snap.Version}
	if plan.Lab != "" {
		out["targetLaboratoryId"] = plan.Lab
	}
	if !plan.ETA.IsZero() {
		out["estimatedArrivalAt"] = fmtTime(plan.ETA)
	}
	c.tx.Audit("serviceability_checked", "serviceability", req.SampleTypeID, "", true, map[string]any{"dryRun": true, "result": out, "origin": p.Origin, "originType": p.OriginType})
	return 200, out, nil
}

func (a *App) validateHandlingMatch(p *parsedRequest, container string, min, max *float64) *apiError {
	t := p.SampleType
	if container == "" || min == nil || max == nil {
		return badJSON("containerType, temperatureMinC and temperatureMaxC are required")
	}
	if *min > *max {
		return errf(400, "handling_mismatch", "temperatureMinC must not exceed temperatureMaxC")
	}
	if !strings.EqualFold(container, t.ContainerType) {
		return errf(400, "handling_mismatch", "sample type %s requires container %q", t.Name, t.ContainerType)
	}
	if *min < t.TemperatureMinC || *max > t.TemperatureMaxC {
		return errf(400, "handling_mismatch", "temperature range must lie within %.1f to %.1f C for %s", t.TemperatureMinC, t.TemperatureMaxC, t.Name)
	}
	return nil
}

func (a *App) createRequestRecord(c *reqCtx, in *requestInput, p *parsedRequest, requesterID string, presealed bool) (*Request, *Sample) {
	tx := c.tx
	r := &Request{ID: newID(), RequesterID: requesterID, CreatedByID: c.user.ID, Origin: p.Origin, OriginType: p.OriginType,
		RequestedAt: p.RequestedAt, DeliveryDeadline: p.Deadline, EarliestCollectionAt: p.Earliest, LatestCollectionAt: p.Latest,
		SampleTypeID: p.SampleType.ID, ContainerType: in.ContainerType, TemperatureMinC: *in.TemperatureMinC, TemperatureMaxC: *in.TemperatureMaxC,
		IncompatibleSampleTypes: uniqueStrs(append(append([]string{}, in.IncompatibleSampleTypes...), p.SampleType.IncompatibleSampleTypes...)),
		Presealed: presealed, CreatedAt: tx.now}
	if p.OriginNode != nil {
		r.OriginNodeID = p.OriginNode.ID
	}
	tx.st.Requests[r.ID] = r
	tx.MarkRequest(r)
	origin := p.Origin
	s := &Sample{ID: newID(), RequestID: r.ID, RequesterID: requesterID, SampleTypeID: p.SampleType.ID, Status: SampleRequested,
		Serviceability: "serviceable", LatestLocation: &origin, LocationRecordedAt: timePtr(tx.now), Timeline: []TimelineEntry{}, JourneyIDs: []string{}, CreatedAt: tx.now}
	tx.st.Samples[s.ID] = s
	tx.MarkSample(s)
	tx.SampleEvent(s, "request_created", "request", r.ID, map[string]any{"requestId": r.ID, "originType": r.OriginType, "sampleTypeId": r.SampleTypeID, "deliveryDeadline": fmtTime(r.DeliveryDeadline), "presealed": presealed})
	return r, s
}

func requestResponse(r *Request, s *Sample, j *Journey, assignments []*Assignment, presealed bool) map[string]any {
	ids := []string{}
	for _, asg := range assignments {
		if !asg.Finished() {
			ids = append(ids, asg.ID)
		}
	}
	out := map[string]any{
		"requestId": r.ID, "sampleId": s.ID, "serviceability": s.Serviceability, "activeAssignmentIds": ids,
		"earliestCollectionAt": fmtTime(r.EarliestCollectionAt), "latestCollectionAt": fmtTime(r.LatestCollectionAt),
		"alreadySealed": presealed, "originType": r.OriginType,
	}
	if s.ServiceabilityReason != "" {
		out["serviceabilityReason"] = s.ServiceabilityReason
	}
	if j != nil {
		out["journeyId"] = j.ID
		out["targetLaboratoryId"] = j.TargetLaboratoryID
	}
	return out
}

func (a *App) handleCreateCollectionRequest(c *reqCtx, body []byte) (int, any, *apiError) {
	req, e := decodeBody[requestInput](body, "origin", "requestedAt", "deliveryDeadline", "sampleTypeId", "containerType", "temperatureMinC", "temperatureMaxC")
	if e != nil {
		return 0, nil, e
	}
	p, e := a.parseRequestCommon(c, req, []string{"home", "clinic", "node"}, "home")
	if e != nil {
		return 0, nil, e
	}
	if e := a.validateHandlingMatch(p, req.ContainerType, req.TemperatureMinC, req.TemperatureMaxC); e != nil {
		return 0, nil, e
	}
	for _, id := range req.IncompatibleSampleTypes {
		if c.st().SampleTypes[id] == nil {
			return 0, nil, errf(400, "handling_mismatch", "incompatible sample type %q does not exist", id)
		}
	}
	requesterID := c.user.ID
	if req.RequesterID != "" && req.RequesterID != c.user.ID {
		if c.role == RoleRequester {
			return 0, nil, forbidden("requesters may only create requests for themselves")
		}
		if c.st().Users[req.RequesterID] == nil {
			return 0, nil, notFound("requester")
		}
		requesterID = req.RequesterID
	}
	tx := c.tx
	r, s := a.createRequestRecord(c, req, p, requesterID, false)
	plan := a.planFor(p, p.Earliest)
	if plan.Reason != "serviceable" {
		s.Serviceability = "unserviceable"
		s.ServiceabilityReason = plan.Reason
		s.Status = SampleUnserviceable
		tx.SampleEvent(s, "request_unserviceable", "sample", s.ID, map[string]any{"reason": plan.Reason})
		a.emitSample(tx, s)
		return 201, requestResponse(r, s, nil, nil, false), nil
	}
	var startCoord *Coordinate
	startNode := ""
	var origin *visit
	if p.OriginNode != nil {
		startNode = p.OriginNode.ID
	} else {
		o := p.Origin
		startCoord = &o
		origin = &visit{LocationID: r.ID, Coordinate: o}
	}
	j := a.newJourney(tx, plan, []string{s.ID}, startNode, startCoord)
	s.ActiveJourneyID = j.ID
	s.JourneyIDs = append(s.JourneyIDs, j.ID)
	s.TargetLaboratoryID = plan.Lab
	tx.MarkSample(s)
	asgs := a.materialize(tx, chainSpec{Journey: j, Sample: s, Request: r, Plan: plan, Origin: origin, HeadKind: KindCollection, StartAt: p.Earliest})
	tx.SampleEvent(s, "journey_planned", "journey", j.ID, map[string]any{"journeyId": j.ID, "routeMode": j.RouteMode, "path": j.Path, "targetLaboratoryId": j.TargetLaboratoryID, "estimatedDeliveryAt": fmtTime(j.EstimatedDeliveryAt), "planVersion": j.PlanVersion})
	a.emitSample(tx, s)
	a.emitJourney(tx, j)
	return 201, requestResponse(r, s, j, asgs, false), nil
}

func (a *App) handleIngestPresealed(c *reqCtx, body []byte) (int, any, *apiError) {
	req, e := decodeBody[requestInput](body, "origin", "requestedAt", "deliveryDeadline", "sampleTypeId", "containerType", "temperatureMinC", "temperatureMaxC")
	if e != nil {
		return 0, nil, e
	}
	p, e := a.parseRequestCommon(c, req, []string{"clinic", "node"}, "node")
	if e != nil {
		return 0, nil, e
	}
	if e := a.validateHandlingMatch(p, req.ContainerType, req.TemperatureMinC, req.TemperatureMaxC); e != nil {
		return 0, nil, e
	}
	me := c.user
	// The registrant must be able to hold the sample at the origin.
	headKind := ""
	switch c.role {
	case RoleCollector:
		headKind = KindCollection
	case RoleCourier:
		headKind = KindTransport
	case RoleNode:
		if p.OriginNode == nil || me.AssignedLocationID != p.OriginNode.ID {
			return 0, nil, errf(400, "invalid_holder", "node handlers may only register samples at their assigned node")
		}
		headKind = KindNode
	case RoleLab:
		if p.OriginNode == nil || me.AssignedLocationID != p.OriginNode.ID {
			return 0, nil, errf(400, "invalid_holder", "laboratory operators may only register samples at their assigned laboratory")
		}
		headKind = KindLab
	default:
		return 0, nil, forbidden("only workers holding the sample may register it")
	}
	requesterID := me.ID
	if req.RequesterID != "" {
		if c.st().Users[req.RequesterID] == nil {
			return 0, nil, notFound("requester")
		}
		requesterID = req.RequesterID
	}
	tx := c.tx
	r, s := a.createRequestRecord(c, req, p, requesterID, true)
	s.Sealed = true
	s.SealedAt = timePtr(p.RequestedAt)
	s.Status = SampleSealed
	s.CurrentHolderID = me.ID
	tx.MarkSample(s)
	plan := a.planFor(p, p.RequestedAt)
	if plan.Reason != "serviceable" {
		s.Serviceability = "unserviceable"
		s.ServiceabilityReason = plan.Reason
		s.Status = SampleUnserviceable
		tx.SampleEvent(s, "request_unserviceable", "sample", s.ID, map[string]any{"reason": plan.Reason})
		a.emitSample(tx, s)
		return 201, requestResponse(r, s, nil, nil, true), nil
	}
	if headKind == KindTransport && len(plan.Path) == 1 && p.OriginNode != nil {
		return 0, nil, errf(400, "invalid_holder", "the origin is already the destination laboratory; a courier cannot hold this sample")
	}
	if headKind == KindLab && (len(plan.Path) != 1 || plan.Lab != p.OriginNode.ID) {
		headKind = KindNode
	}
	var startCoord *Coordinate
	startNode := ""
	var origin *visit
	if p.OriginNode != nil {
		startNode = p.OriginNode.ID
	} else {
		o := p.Origin
		startCoord = &o
		origin = &visit{LocationID: r.ID, Coordinate: o}
	}
	j := a.newJourney(tx, plan, []string{s.ID}, startNode, startCoord)
	s.ActiveJourneyID = j.ID
	s.JourneyIDs = append(s.JourneyIDs, j.ID)
	s.TargetLaboratoryID = plan.Lab
	tx.MarkSample(s)
	asgs := a.materialize(tx, chainSpec{Journey: j, Sample: s, Request: r, Plan: plan, Origin: origin, HeadKind: headKind, HeadWorker: me, StartAt: p.RequestedAt})
	tx.SampleEvent(s, "sample_registered_presealed", "sample", s.ID, map[string]any{"holderId": me.ID, "originType": r.OriginType, "originNodeId": r.OriginNodeID})
	tx.SampleEvent(s, "journey_planned", "journey", j.ID, map[string]any{"journeyId": j.ID, "routeMode": j.RouteMode, "path": j.Path, "targetLaboratoryId": j.TargetLaboratoryID, "estimatedDeliveryAt": fmtTime(j.EstimatedDeliveryAt), "planVersion": j.PlanVersion})
	if len(j.Stops) > 0 {
		j.Stops[0].CompletedAt = timePtr(tx.now)
		tx.MarkJourney(j)
	}
	a.emitSample(tx, s)
	a.emitJourney(tx, j)
	return 201, requestResponse(r, s, j, asgs, true), nil
}

