	s.Sealed = true
	s.SealedAt = timePtr(p.RequestedAt)
	s.Status = SampleSealed
	s.CurrentHolderID = me.ID
	tx.MarkSample(s)
	plan := a.planFor(p, p.RequestedAt)
	if plan.Reason != "serviceable" {
		s.Serviceability = "unserviceable"
		s.ServiceabilityReason = plan.Reason
		s.Status = SampleUnserviceable
		tx.SampleEvent(s, "request_unserviceable", "sample", s.ID, map[string]any{"reason": plan.Reason})
