		return 0, nil, errf(400, "invalid_holder", "the origin is already the destination laboratory; a courier cannot hold this sample")
	}
	if headKind == KindLab && (len(plan.Path) != 1 || plan.Lab != p.OriginNode.ID) {
		headKind = KindNode
	}
	var startCoord *Coordinate
	startNode := ""
	var origin *visit
	if p.OriginNode != nil {
		startNode = p.OriginNode.ID
	} else {
		o := p.Origin
		startCoord = &o
		origin = &visit{LocationID: r.ID, Coordinate: o}
	}
	j := a.newJourney(tx, plan, []string{s.ID}, startNode, startCoord)
	s.ActiveJourneyID = j.ID
	s.JourneyIDs = append(s.JourneyIDs, j.ID)
	s.TargetLaboratoryID = plan.Lab
	tx.MarkSample(s)
	asgs := a.materialize(tx, chainSpec{Journey: j, Sample: s, Request: r, Plan: plan, Origin: origin, HeadKind: headKind, HeadWorker: me, StartAt: p.RequestedAt})
	tx.SampleEvent(s, "sample_registered_presealed", "sample", s.ID, map[string]any{"holderId": me.ID, "originType": r.OriginType, "originNodeId": r.OriginNodeID})
	tx.SampleEvent(s, "journey_planned", "journey", j.ID, map[string]any{"journeyId": j.ID, "routeMode": j.RouteMode, "path": j.Path, "targetLaboratoryId": j.TargetLaboratoryID, "estimatedDeliveryAt": fmtTime(j.EstimatedDeliveryAt), "planVersion": j.PlanVersion})
	if len(j.Stops) > 0 {
		j.Stops[0].CompletedAt = timePtr(tx.now)
		tx.MarkJourney(j)
	}
	a.emitSample(tx, s)
	a.emitJourney(tx, j)
	return 201, requestResponse(r, s, j, asgs, true), nil
}
