package app

import (
	"strings"
)

func (a *App) pendingHandoff(sampleID string) *Handoff {
	for _, h := range a.state.Handoffs {
		if h.SampleID == sampleID && h.Status == "pending" {
			return h
		}
	}
	return nil
}

func handoffJSON(h *Handoff) map[string]any {
	return map[string]any{
		"handoffId": h.ID, "sampleId": h.SampleID, "journeyId": h.JourneyID, "fromAssignmentId": h.FromAssignmentID,
		"toAssignmentId": h.ToAssignmentID, "senderId": h.SenderID, "receiverId": h.ReceiverID, "status": h.Status,
		"initiatedAt": fmtTime(h.InitiatedAt), "senderConfirmed": h.SenderConfirmedAt != nil, "receiverConfirmed": h.ReceiverConfirmedAt != nil,
		"senderConfirmedAt": fmtTimePtr(h.SenderConfirmedAt), "receiverConfirmedAt": fmtTimePtr(h.ReceiverConfirmedAt), "completedAt": fmtTimePtr(h.CompletedAt),
	}
}

func (a *App) handleCollectAndSeal(c *reqCtx, body []byte) (int, any, *apiError) {
	type in struct {
		SampleID             string   `json:"sampleId"`
		AssignmentID         string   `json:"assignmentId"`
		CollectedAt          string   `json:"collectedAt"`
		ContainerType        string   `json:"containerType"`
		ObservedTemperatureC *float64 `json:"observedTemperatureC"`
		IdempotencyKey       string   `json:"idempotencyKey"`
	}
	req, e := decodeBody[in](body, "sampleId", "assignmentId", "collectedAt", "containerType", "observedTemperatureC", "idempotencyKey")
	if e != nil {
		return 0, nil, e
	}
	at, e := reqTime(req.CollectedAt)
	if e != nil {
		return 0, nil, e
	}
	s := c.st().Samples[req.SampleID]
	if s == nil {
		return 0, nil, notFound("sample")
	}
	asg := c.st().Assignments[req.AssignmentID]
	if asg == nil || asg.SampleID != s.ID {
		return 0, nil, notFound("assignment")
	}
	r := c.st().Requests[s.RequestID]
	me := c.user
	if asg.WorkerID != me.ID || asg.Kind != KindCollection {
		return 0, nil, forbidden("this collection assignment is not assigned to you")
	}
	if asg.Finished() {
		return 0, nil, conflict("assignment_inactive", "assignment is %s", asg.Status)
	}
	if s.Sealed || s.Terminal() {
		return 0, nil, conflict("invalid_sample_state", "sample is already %s", s.Status)
	}
	if asg.Status == AsgPending || asg.Status == AsgOffered {
		return 0, nil, conflict("collection_not_ready", "accept the collection assignment first")
	}
	t := c.st().SampleTypes[s.SampleTypeID]
	if t != nil && t.QualifiedCollectorRequired {
		code := t.QualificationCode()
		if !a.hasQualification(me, code, c.now()) {
			for _, ct := range me.Certifications {
				if ct.Code == code {
					return 0, nil, conflict("certification_inactive", "your %s certification is inactive or expired", code)
				}
			}
			return 0, nil, conflict("certification_inactive", "you do not hold the %s qualification", code)
		}
	}
	if at.Before(r.RequestedAt) {
		return 0, nil, conflict("invalid_collection_time", "collectedAt is before the request was made")
	}
	if at.Before(r.EarliestCollectionAt) || at.After(r.LatestCollectionAt) {
		return 0, nil, conflict("outside_collection_window", "collectedAt must be within %s and %s", fmtTime(r.EarliestCollectionAt), fmtTime(r.LatestCollectionAt))
	}
	if !strings.EqualFold(req.ContainerType, r.ContainerType) {
		return 0, nil, errf(400, "handling_noncompliant", "sample must be sealed in container %q", r.ContainerType)
	}
	compliant := *req.ObservedTemperatureC >= r.TemperatureMinC && *req.ObservedTemperatureC <= r.TemperatureMaxC
	s.Sealed = true
	s.SealedAt = &at
	s.Status = SampleSealed
	s.CurrentHolderID = me.ID
	if asg.FromCoordinate != nil {
		a.setSampleLocation(c.tx, s, *asg.FromCoordinate, at)
	}
	c.tx.MarkSample(s)
	asg.Status = AsgInProgress
	asg.LastProgressAt = &at
	c.tx.MarkAssignment(asg)
	j := c.st().Journeys[asg.JourneyID]
	if j != nil && len(j.Stops) > 0 && j.Stops[0].CompletedAt == nil {
		j.Stops[0].CompletedAt = &at
		c.tx.MarkJourney(j)
	}
	c.tx.SampleEvent(s, "sample_collected_sealed", "sample", s.ID, map[string]any{"assignmentId": asg.ID, "collectorId": me.ID, "collectedAt": fmtTime(at), "containerType": req.ContainerType, "observedTemperatureC": *req.ObservedTemperatureC, "handlingCompliant": compliant})
	c.tx.SampleEvent(s, "custody_established", "sample", s.ID, map[string]any{"holderId": me.ID, "assignmentId": asg.ID})
	if !compliant {
		a.flagException(c.tx, s, "handling_noncompliant", map[string]any{"assignmentId": asg.ID, "containerType": req.ContainerType, "observedTemperatureC": *req.ObservedTemperatureC, "stage": "collection"})
	}
	a.emitAssignment(c.tx, asg)
	a.emitSample(c.tx, s)
	return 201, map[string]any{"sampleId": s.ID, "status": "sealed", "currentHolderId": me.ID, "sealedAt": fmtTime(at), "handlingCompliant": compliant}, nil
}

func (a *App) handleInitiateHandoff(c *reqCtx, body []byte) (int, any, *apiError) {
	type in struct {
		SampleID         string `json:"sampleId"`
		FromAssignmentID string `json:"fromAssignmentId"`
		ToAssignmentID   string `json:"toAssignmentId"`
		ReceiverID       string `json:"receiverId"`
		InitiatedAt      string `json:"initiatedAt"`
		IdempotencyKey   string `json:"idempotencyKey"`
	}
	req, e := decodeBody[in](body, "sampleId", "fromAssignmentId", "toAssignmentId", "receiverId", "initiatedAt", "idempotencyKey")
	if e != nil {
		return 0, nil, e
	}
	at, e := reqTime(req.InitiatedAt)
	if e != nil {
		return 0, nil, e
	}
	st := c.st()
	s := st.Samples[req.SampleID]
	if s == nil {
		return 0, nil, notFound("sample")
	}
	from := st.Assignments[req.FromAssignmentID]
	to := st.Assignments[req.ToAssignmentID]
	if from == nil || to == nil {
		return 0, nil, notFound("assignment")
	}
	receiver := st.Users[req.ReceiverID]
	if receiver == nil {
		return 0, nil, errf(400, "invalid_receiver", "receiver does not exist")
	}
	if from.SampleID != s.ID || to.SampleID != s.ID {
		return 0, nil, errf(400, "invalid_handoff_route", "assignments do not belong to this sample")
	}
	me := c.user
	if from.WorkerID != me.ID {
		return 0, nil, errf(403, "sender_assignment_mismatch", "the sending assignment is not yours")
	}
	if s.CurrentHolderID != me.ID {
		return 0, nil, conflict("not_current_holder", "you do not currently hold this sample")
	}
	if !s.Sealed {
		return 0, nil, conflict("prior_leg_incomplete", "sample must be collected and sealed before handoff")
	}
	if from.Finished() {
		return 0, nil, conflict("invalid_assignment_state", "sending assignment is %s", from.Status)
	}
	if to.Finished() {
		return 0, nil, conflict("invalid_assignment_state", "receiving assignment is %s", to.Status)
	}
	j := st.Journeys[s.ActiveJourneyID]
	if j == nil || from.JourneyID != j.ID || to.JourneyID != j.ID {
		return 0, nil, conflict("invalid_handoff_route", "assignments are not part of the active journey")
	}
	if next := a.nextAssignment(from); next == nil || next.ID != to.ID {
		return 0, nil, conflict("nonadjacent_handoff", "the receiving assignment is not the next leg of the journey")
	}
	if to.Status == AsgPending || to.Status == AsgOffered {
		return 0, nil, conflict("receiver_unavailable", "the receiving assignment has not been accepted yet")
	}
	if to.WorkerID != receiver.ID {
		if to.Kind == KindNode && receiver.HasRole(RoleNode) {
			return 0, nil, conflict("node_assignment_mismatch", "receiver is not the handler assigned to this node leg")
		}
		return 0, nil, conflict("receiver_assignment_mismatch", "receiver is not the worker on the receiving assignment")
	}
	if !receiver.Active || !receiver.Available {
		return 0, nil, conflict("receiver_unavailable", "receiver is not available")
	}
	if from.Kind == KindTransport && transportOrder[from.Status] < transportOrder[AsgArrived] {
		return 0, nil, conflict("transport_leg_incomplete", "report arrival before handing the sample off")
	}
	if h := a.pendingHandoff(s.ID); h != nil {
		return 0, nil, conflict("pending_handoff_exists", "a handoff for this sample is already pending")
	}
	if s.SealedAt != nil && at.Before(*s.SealedAt) {
		return 0, nil, conflict("invalid_handoff_time", "initiatedAt is before the sample was sealed")
	}
	h := &Handoff{ID: newID(), SampleID: s.ID, JourneyID: j.ID, FromAssignmentID: from.ID, ToAssignmentID: to.ID, SenderID: me.ID, ReceiverID: receiver.ID, Status: "pending", InitiatedAt: at, CreatedAt: c.now()}
	st.Handoffs[h.ID] = h
	c.tx.MarkHandoff(h)
	c.tx.SampleEvent(s, "handoff_initiated", "handoff", h.ID, map[string]any{"handoffId": h.ID, "senderId": me.ID, "receiverId": receiver.ID, "fromAssignmentId": from.ID, "toAssignmentId": to.ID, "initiatedAt": fmtTime(at)})
	c.tx.Emit("handoff.updated", "handoff", h.ID, map[string]any{"handoff": handoffJSON(h), "participantIds": []string{me.ID, receiver.ID}, "requesterId": s.RequesterID})
	return 201, map[string]any{"handoffId": h.ID, "senderId": me.ID, "receiverId": receiver.ID, "currentHolderId": s.CurrentHolderID, "status": "pending"}, nil
}

func (a *App) handleConfirmHandoff(c *reqCtx, body []byte) (int, any, *apiError) {
	type in struct {
		HandoffID        string `json:"handoffId"`
		ConfirmationSide string `json:"confirmationSide"`
		ConfirmedAt      string `json:"confirmedAt"`
		IdempotencyKey   string `json:"idempotencyKey"`
	}
	req, e := decodeBody[in](body, "handoffId", "confirmationSide", "confirmedAt", "idempotencyKey")
	if e != nil {
		return 0, nil, e
	}
	if req.ConfirmationSide != "sender" && req.ConfirmationSide != "receiver" {
		return 0, nil, errf(400, "invalid_confirmation_side", "confirmationSide must be sender or receiver")
	}
	at, e := reqTime(req.ConfirmedAt)
	if e != nil {
		return 0, nil, e
	}
	st := c.st()
	h := st.Handoffs[req.HandoffID]
	if h == nil {
		return 0, nil, notFound("handoff")
	}
	s := st.Samples[h.SampleID]
	if s == nil {
		return 0, nil, notFound("sample")
	}
	me := c.user
	if req.ConfirmationSide == "sender" && h.SenderID != me.ID {
		return 0, nil, forbidden("only the sender may confirm the sender side")
	}
	if req.ConfirmationSide == "receiver" && h.ReceiverID != me.ID {
		return 0, nil, forbidden("only the receiver may confirm the receiver side")
	}
	respond := func() (int, any, *apiError) {
		return 201, map[string]any{"handoffId": h.ID, "status": h.Status, "senderConfirmed": h.SenderConfirmedAt != nil, "receiverConfirmed": h.ReceiverConfirmedAt != nil, "currentHolderId": s.CurrentHolderID}, nil
	}
	if h.Status == "confirmed" {
		// Repeated confirmations never transfer custody twice.
		return respond()
	}
	if h.Status != "pending" {
		return 0, nil, conflict("handoff_inactive", "handoff is %s", h.Status)
	}
	if s.CurrentHolderID != h.SenderID {
		return 0, nil, conflict("custody_conflict", "the sender no longer holds the sample")
	}
	if at.Before(h.InitiatedAt) {
		return 0, nil, conflict("invalid_confirmation_time", "confirmedAt is before the handoff was initiated")
	}
	if req.ConfirmationSide == "sender" {
		if h.SenderConfirmedAt != nil {
			return respond()
		}
		h.SenderConfirmedAt = &at
	} else {
		if h.ReceiverConfirmedAt != nil {
			return respond()
		}
		h.ReceiverConfirmedAt = &at
	}
	c.tx.MarkHandoff(h)
	c.tx.SampleEvent(s, "handoff_confirmed_"+req.ConfirmationSide, "handoff", h.ID, map[string]any{"handoffId": h.ID, "side": req.ConfirmationSide, "confirmedAt": fmtTime(at), "userId": me.ID})
	if h.SenderConfirmedAt != nil && h.ReceiverConfirmedAt != nil {
		a.completeHandoff(c, h, s)
	}
	c.tx.Emit("handoff.updated", "handoff", h.ID, map[string]any{"handoff": handoffJSON(h), "participantIds": []string{h.SenderID, h.ReceiverID}, "requesterId": s.RequesterID})
	return respond()
}

func (a *App) completeHandoff(c *reqCtx, h *Handoff, s *Sample) {
	tx := c.tx
	st := c.st()
	at := *h.SenderConfirmedAt
	if h.ReceiverConfirmedAt.After(at) {
		at = *h.ReceiverConfirmedAt
	}
	h.Status = "confirmed"
	h.CompletedAt = &at
	tx.MarkHandoff(h)
	from := st.Assignments[h.FromAssignmentID]
	to := st.Assignments[h.ToAssignmentID]
	j := st.Journeys[h.JourneyID]
	prevHolder := s.CurrentHolderID
	s.CurrentHolderID = h.ReceiverID
	if from != nil && !from.Finished() {
		from.Status = AsgCompleted
		from.CompletedAt = &at
		from.LastProgressAt = &at
		tx.MarkAssignment(from)
		a.emitAssignment(tx, from)
		switch from.Kind {
		case KindTransport:
			if from.ConnectionID != "" {
				a.releaseReservations(tx, from.JourneyID, s.ID, from.ConnectionID, "leg_completed")
			}
		case KindNode:
			a.releaseReservations(tx, from.JourneyID, s.ID, from.NodeID, "left_node")
		case KindCollection:
			if from.NodeID != "" {
				a.releaseReservations(tx, from.JourneyID, s.ID, from.NodeID, "left_origin_node")
			}
		}
	}
	if to != nil {
		switch to.Kind {
		case KindTransport:
			if transportOrder[to.Status] < transportOrder[AsgPickedUp] {
				to.Status = AsgPickedUp
			}
			if s.Status != SampleException {
				s.Status = SampleInTransit
			}
			if w := st.Users[h.ReceiverID]; w != nil && w.LatestLocation != nil && w.LocationRecordedAt != nil && w.LocationRecordedAt.After(at.Add(-a.cfg.StaleAfter)) {
				a.setSampleLocation(tx, s, *w.LatestLocation, at)
			} else if to.FromCoordinate != nil {
				a.setSampleLocation(tx, s, *to.FromCoordinate, at)
			}
		case KindNode:
			if to.Status == AsgAccepted {
				to.Status = AsgInProgress
			}
			if s.Status != SampleException {
				s.Status = SampleAtNode
			}
			if to.ToCoordinate != nil {
				a.setSampleLocation(tx, s, *to.ToCoordinate, at)
			}
		case KindLab:
			if to.Status == AsgAccepted {
				to.Status = AsgInProgress
			}
			if s.Status != SampleException {
				s.Status = SampleAtLab
			}
			if to.ToCoordinate != nil {
				a.setSampleLocation(tx, s, *to.ToCoordinate, at)
			}
		}
		to.LastProgressAt = &at
		tx.MarkAssignment(to)
		a.emitAssignment(tx, to)
		if j != nil {
			for i := range j.Stops {
				if j.Stops[i].CompletedAt == nil && (j.Stops[i].LocationID == to.NodeID && to.Kind == KindNode) {
					j.Stops[i].CompletedAt = &at
					tx.MarkJourney(j)
					break
				}
			}
			if from != nil && from.Kind == KindCollection && len(j.Stops) > 0 && j.Stops[0].CompletedAt == nil {
				j.Stops[0].CompletedAt = &at
				tx.MarkJourney(j)
			}
		}
	}
	tx.MarkSample(s)
	tx.SampleEvent(s, "custody_transferred", "handoff", h.ID, map[string]any{"handoffId": h.ID, "fromHolderId": prevHolder, "toHolderId": h.ReceiverID, "fromAssignmentId": h.FromAssignmentID, "toAssignmentId": h.ToAssignmentID, "completedAt": fmtTime(at)})
	a.emitSample(tx, s)
	if j != nil {
		a.emitJourney(tx, j)
	}
}

func (a *App) handleRecordCheckpoint(c *reqCtx, body []byte) (int, any, *apiError) {
	type in struct {
		SampleID             string   `json:"sampleId"`
		AssignmentID         string   `json:"assignmentId"`
		LocationID           string   `json:"locationId"`
		ContainerType        string   `json:"containerType"`
		ObservedTemperatureC *float64 `json:"observedTemperatureC"`
		RecordedAt           string   `json:"recordedAt"`
		IdempotencyKey       string   `json:"idempotencyKey"`
	}
	req, e := decodeBody[in](body, "sampleId", "assignmentId", "containerType", "observedTemperatureC", "recordedAt", "idempotencyKey")
	if e != nil {
		return 0, nil, e
	}
	at, e := reqTime(req.RecordedAt)
	if e != nil {
		return 0, nil, e
	}
	st := c.st()
	s := st.Samples[req.SampleID]
	if s == nil {
		return 0, nil, notFound("sample")
	}
	asg := st.Assignments[req.AssignmentID]
	if asg == nil || asg.SampleID != s.ID {
		return 0, nil, notFound("assignment")
	}
	if req.LocationID != "" && st.Locations[req.LocationID] == nil {
		return 0, nil, notFound("location")
	}
	me := c.user
	if asg.WorkerID != me.ID || s.CurrentHolderID != me.ID {
		return 0, nil, forbidden("only the current custodian may record a handling checkpoint")
	}
	if s.Terminal() {
		return 0, nil, conflict("terminal_sample", "sample is %s", s.Status)
	}
	if asg.Finished() {
		return 0, nil, conflict("assignment_inactive", "assignment is %s", asg.Status)
	}
	j := st.Journeys[asg.JourneyID]
	if j == nil || !j.IsActive() {
		return 0, nil, conflict("journey_inactive", "journey is not active")
	}
	if s.SealedAt != nil && at.Before(*s.SealedAt) {
		return 0, nil, conflict("invalid_checkpoint_time", "recordedAt is before the sample was sealed")
	}
	r := st.Requests[s.RequestID]
	compliant := strings.EqualFold(req.ContainerType, r.ContainerType) && *req.ObservedTemperatureC >= r.TemperatureMinC && *req.ObservedTemperatureC <= r.TemperatureMaxC
	cp := &Checkpoint{ID: newID(), SampleID: s.ID, AssignmentID: asg.ID, LocationID: req.LocationID, RecordedBy: me.ID, ContainerType: req.ContainerType, ObservedTemperatureC: *req.ObservedTemperatureC, Compliant: compliant, RecordedAt: at}
	st.Checkpoints[cp.ID] = cp
	c.tx.MarkCheckpoint(cp)
	if req.LocationID != "" {
		a.setSampleLocation(c.tx, s, st.Locations[req.LocationID].Coordinate, at)
	}
	c.tx.SampleEvent(s, "handling_checkpoint", "checkpoint", cp.ID, map[string]any{"checkpointId": cp.ID, "assignmentId": asg.ID, "containerType": req.ContainerType, "observedTemperatureC": *req.ObservedTemperatureC, "compliant": compliant, "locationId": req.LocationID, "recordedAt": fmtTime(at)})
	if !compliant {
		a.flagException(c.tx, s, "handling_noncompliant", map[string]any{"checkpointId": cp.ID, "assignmentId": asg.ID, "containerType": req.ContainerType, "observedTemperatureC": *req.ObservedTemperatureC, "requiredContainerType": r.ContainerType, "temperatureMinC": r.TemperatureMinC, "temperatureMaxC": r.TemperatureMaxC})
	}
	a.emitSample(c.tx, s)
	return 201, map[string]any{"checkpointId": cp.ID, "sampleId": s.ID, "compliant": compliant, "sampleStatus": s.Status}, nil
}

func (a *App) labAssignment(s *Sample, labID string) *Assignment {
	for _, asg := range a.sampleAssignments(s.ID, s.ActiveJourneyID) {
		if asg.Kind == KindLab && asg.LaboratoryID == labID && asg.Status != AsgCancelled {
			return asg
		}
	}
	return nil
}

func (a *App) finishJourney(tx *Tx, j *Journey, status string, reason string) {
	j.Status = status
	tx.MarkJourney(j)
	for _, sid := range j.SampleIDs {
		s := tx.st.Samples[sid]
		if s == nil {
			continue
		}
		for _, asg := range a.journeyAssignments(j.ID) {
			if asg.SampleID != sid || asg.Finished() {
				continue
			}
			if status == JourneyCompleted {
				asg.Status = AsgCompleted
			} else {
				asg.Status = AsgCancelled
				asg.CancelReason = reason
			}
			asg.CompletedAt = timePtr(tx.now)
			tx.MarkAssignment(asg)
			a.emitAssignment(tx, asg)
		}
		a.releaseReservations(tx, j.ID, sid, "", reason)
	}
	a.emitJourney(tx, j)
}

func (a *App) handleConfirmLabReceipt(c *reqCtx, body []byte) (int, any, *apiError) {
	type in struct {
		SampleID       string `json:"sampleId"`
		LaboratoryID   string `json:"laboratoryId"`
		ReceivedAt     string `json:"receivedAt"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	req, e := decodeBody[in](body, "sampleId", "laboratoryId", "receivedAt", "idempotencyKey")
	if e != nil {
		return 0, nil, e
	}
	at, e := reqTime(req.ReceivedAt)
	if e != nil {
		return 0, nil, e
	}
	st := c.st()
	s := st.Samples[req.SampleID]
	if s == nil {
		return 0, nil, notFound("sample")
	}
	lab := st.Locations[req.LaboratoryID]
	if lab == nil {
		return 0, nil, notFound("laboratory")
	}
	me := c.user
	if me.AssignedLocationID != lab.ID {
		return 0, nil, errf(403, "wrong_laboratory_operator", "you are not assigned to this laboratory")
	}
	if !lab.Fn(FnLab) {
		return 0, nil, conflict("laboratory_unavailable", "laboratory is not active")
	}
	if s.Status == SampleReceived {
		return 201, map[string]any{"sampleId": s.ID, "laboratoryId": s.ReceivedLaboratoryID, "status": "received", "receivedAt": fmtTimePtr(s.ReceivedAt)}, nil
	}
	if s.Terminal() {
		return 0, nil, conflict("receipt_not_ready", "sample is %s", s.Status)
	}
	if h := a.pendingHandoff(s.ID); h != nil {
		return 0, nil, conflict("pending_handoff_exists", "complete the pending handoff first")
	}
	asg := a.labAssignment(s, lab.ID)
	if asg == nil || !s.Sealed {
		return 0, nil, conflict("receipt_not_ready", "the sample is not expected at this laboratory yet")
	}
	if s.CurrentHolderID != me.ID {
		return 0, nil, conflict("custody_conflict", "you do not hold custody of this sample")
	}
	if asg.WorkerID != me.ID || asg.Unassigned() {
		return 0, nil, conflict("receipt_not_ready", "the laboratory assignment is not in your custody")
	}
	r := st.Requests[s.RequestID]
	if s.SealedAt != nil && at.Before(*s.SealedAt) {
		return 0, nil, conflict("invalid_receipt_time", "receivedAt is before the sample was sealed")
	}
	if asg.LastProgressAt != nil && at.Before(*asg.LastProgressAt) {
		return 0, nil, conflict("invalid_receipt_time", "receivedAt is before the sample arrived at the laboratory")
	}
	if at.After(r.DeliveryDeadline) {
		c.tx.Audit("laboratory_receipt_rejected", "sample", s.ID, s.ID, false, map[string]any{"reason": "delivery_deadline_exceeded", "receivedAt": fmtTime(at), "deadline": fmtTime(r.DeliveryDeadline)})
		return 0, nil, conflict("delivery_deadline_exceeded", "receivedAt is after the delivery deadline; record a laboratory exception instead")
	}
	s.Status = SampleReceived
	s.ReceivedLaboratoryID = lab.ID
	s.ReceivedAt = &at
	a.setSampleLocation(c.tx, s, lab.Coordinate, at)
	c.tx.MarkSample(s)
	asg.Status = AsgCompleted
	asg.CompletedAt = &at
	asg.LastProgressAt = &at
	c.tx.MarkAssignment(asg)
	j := st.Journeys[s.ActiveJourneyID]
	if j != nil {
		for i := range j.Stops {
			if j.Stops[i].StopType == "delivery" && j.Stops[i].CompletedAt == nil {
				j.Stops[i].CompletedAt = &at
			}
		}
		allDone := true
		for _, sid := range j.SampleIDs {
			if o := st.Samples[sid]; o != nil && o.Status != SampleReceived && !o.Terminal() {
				allDone = false
			}
		}
		if allDone {
			a.finishJourney(c.tx, j, JourneyCompleted, "completed")
		} else {
			a.releaseReservations(c.tx, j.ID, s.ID, "", "received")
			c.tx.MarkJourney(j)
		}
	}
	c.tx.SampleEvent(s, "laboratory_receipt_confirmed", "sample", s.ID, map[string]any{"laboratoryId": lab.ID, "operatorId": me.ID, "receivedAt": fmtTime(at), "assignmentId": asg.ID})
	a.emitAssignment(c.tx, asg)
	a.emitSample(c.tx, s)
	return 201, map[string]any{"sampleId": s.ID, "laboratoryId": lab.ID, "status": "received", "receivedAt": fmtTime(at)}, nil
}

func (a *App) handleRecordLabException(c *reqCtx, body []byte) (int, any, *apiError) {
	type in struct {
		SampleID       string `json:"sampleId"`
		LaboratoryID   string `json:"laboratoryId"`
		Reason         string `json:"reason"`
		ObservedAt     string `json:"observedAt"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	req, e := decodeBody[in](body, "sampleId", "laboratoryId", "reason", "observedAt", "idempotencyKey")
	if e != nil {
		return 0, nil, e
	}
	at, e := reqTime(req.ObservedAt)
	if e != nil {
		return 0, nil, e
	}
	st := c.st()
	s := st.Samples[req.SampleID]
	if s == nil {
		return 0, nil, notFound("sample")
	}
	lab := st.Locations[req.LaboratoryID]
	if lab == nil {
		return 0, nil, notFound("laboratory")
	}
	me := c.user
	if me.AssignedLocationID != lab.ID {
		return 0, nil, errf(403, "wrong_laboratory_operator", "you are not assigned to this laboratory")
	}
	if s.TargetLaboratoryID != "" && s.TargetLaboratoryID != lab.ID {
		return 0, nil, conflict("wrong_laboratory", "sample is routed to a different laboratory")
	}
	j := st.Journeys[s.ActiveJourneyID]
	if j == nil || !j.IsActive() {
		return 0, nil, conflict("journey_inactive", "the sample has no active journey")
	}
	if a.labAssignment(s, lab.ID) == nil {
		return 0, nil, conflict("laboratory_not_ready", "the sample is not expected at this laboratory")
	}
	if s.SealedAt != nil && at.Before(*s.SealedAt) {
		return 0, nil, conflict("invalid_exception_time", "observedAt is before the sample was sealed")
	}
	a.flagException(c.tx, s, strings.TrimSpace(req.Reason), map[string]any{"laboratoryId": lab.ID, "observedAt": fmtTime(at), "stage": "laboratory"})
	exID, _ := s.Exception["exceptionId"].(string)
	a.finishJourney(c.tx, j, JourneyException, "laboratory_exception")
	j.ReplanStatus = "exception"
	c.tx.MarkJourney(j)
	c.tx.SampleEvent(s, "laboratory_exception_recorded", "sample", s.ID, map[string]any{"exceptionId": exID, "laboratoryId": lab.ID, "reason": req.Reason, "observedAt": fmtTime(at)})
	return 201, map[string]any{"exceptionId": exID, "sampleId": s.ID, "status": "exception", "reason": req.Reason}, nil
}

