package app

import (
	"encoding/json"
	"strings"
	"time"
)

// position describes where a sample currently is within its active journey and
// where the unfinished part of the plan must start from.
type position struct {
	Sample     *Sample
	Journey    *Journey
	Request    *Request
	Head       *Assignment
	Stage      string // pre_collection | collected | at_node | in_transit | at_laboratory | done
	StartNode  string
	StartCoord *Coordinate
	StartAt    time.Time
	Origin     *visit
	Continue   bool // in-transit leg continues to its destination
}

func (a *App) samplePosition(s *Sample) *position {
	j := a.state.Journeys[s.ActiveJourneyID]
	r := a.state.Requests[s.RequestID]
	p := &position{Sample: s, Journey: j, Request: r, Stage: "done"}
	if j == nil || !j.IsActive() || s.Terminal() {
		return p
	}
	originVisit := func() {
		if r.OriginNodeID != "" {
			p.StartNode = r.OriginNodeID
		} else {
			o := r.Origin
			p.StartCoord = &o
			p.Origin = &visit{LocationID: r.ID, Coordinate: o}
		}
	}
	asgs := a.sampleAssignments(s.ID, j.ID)
	if !s.Sealed {
		p.Stage = "pre_collection"
		for _, asg := range asgs {
			if asg.Kind == KindCollection && asg.Status != AsgCancelled {
				p.Head = asg
				break
			}
		}
		originVisit()
		p.StartAt = r.EarliestCollectionAt
		return p
	}
	for _, asg := range asgs {
		if asg.WorkerID == s.CurrentHolderID && !asg.Finished() {
			p.Head = asg
			break
		}
	}
	eventTime := func(asg *Assignment) time.Time {
		if asg.LastProgressAt != nil {
			return *asg.LastProgressAt
		}
		if s.SealedAt != nil {
			return *s.SealedAt
		}
		return r.RequestedAt
	}
	if p.Head == nil {
		// Custody holder without an open assignment: fall back to the last completed leg.
		var last *Assignment
		for _, asg := range asgs {
			if asg.Status == AsgCompleted {
				last = asg
			}
		}
		if last != nil && last.Kind == KindTransport && a.state.Locations[last.ToLocationID] != nil {
			p.Stage = "at_node"
			p.StartNode = last.ToLocationID
			p.StartAt = eventTime(last)
			return p
		}
		p.Stage = "collected"
		originVisit()
		p.StartAt = eventTime(&Assignment{})
		return p
	}
	switch p.Head.Kind {
	case KindCollection:
		p.Stage = "collected"
		originVisit()
		if s.SealedAt != nil {
			p.StartAt = *s.SealedAt
		} else {
			p.StartAt = r.RequestedAt
		}
	case KindNode:
		p.Stage = "at_node"
		p.StartNode = p.Head.NodeID
		p.StartAt = eventTime(p.Head)
	case KindLab:
		p.Stage = "at_laboratory"
		p.StartNode = p.Head.LaboratoryID
		p.StartAt = eventTime(p.Head)
	case KindTransport:
		p.Stage = "in_transit"
		h := p.Head
		dest := a.state.Locations[h.ToLocationID]
		conn := a.state.Connections[h.ConnectionID]
		destOK := dest != nil && dest.Active && (h.ConnectionID == "" || (conn != nil && conn.Active))
		if destOK {
			p.Continue = true
			p.StartNode = h.ToLocationID
			p.StartAt = h.EstimatedEndAt
			if t := eventTime(h); t.After(p.StartAt) {
				p.StartAt = t
			}
			if a.state.Locations[h.FromLocationID] != nil {
				v := a.nodeVisit(h.FromLocationID)
				p.Origin = &v
			} else if h.FromCoordinate != nil {
				p.Origin = &visit{LocationID: h.FromLocationID, Coordinate: *h.FromCoordinate}
			}
		} else {
			p.StartAt = eventTime(h)
			if a.state.Locations[h.FromLocationID] != nil {
				p.StartNode = h.FromLocationID
			} else if h.FromCoordinate != nil {
				c := *h.FromCoordinate
				p.StartCoord = &c
				p.Origin = &visit{LocationID: h.FromLocationID, Coordinate: c}
			}
		}
	}
	return p
}

func (a *App) planInputFor(p *position) planInput {
	in := planInput{StartNode: p.StartNode, StartCoord: p.StartCoord, StartAt: p.StartAt, Units: 1, IgnoreJourney: p.Journey.ID,
		Deadline: p.Request.DeliveryDeadline, Types: []*SampleType{a.state.SampleTypes[p.Sample.SampleTypeID]}}
	return in
}

// remainingPath lists the locations still to be visited (starting at the
// current position when it is a node).
func (a *App) remainingPath(p *position) []string {
	var path []string
	if p.StartNode != "" {
		path = append(path, p.StartNode)
	}
	for _, asg := range a.sampleAssignments(p.Sample.ID, p.Journey.ID) {
		if asg.Kind != KindTransport || asg.Finished() {
			continue
		}
		if p.Head != nil && asg.ID == p.Head.ID && p.Continue {
			continue
		}
		if a.state.Locations[asg.ToLocationID] == nil {
			continue
		}
		if len(path) == 0 || path[len(path)-1] != asg.ToLocationID {
			path = append(path, asg.ToLocationID)
		}
	}
	return path
}

// currentPlanValid re-validates the unfinished part of the journey for a sample.
func (a *App) currentPlanValid(p *position) bool {
	path := a.remainingPath(p)
	if len(path) == 0 {
		return false
	}
	if _, e := a.validatePath(a.planInputFor(p), path); e != nil {
		return false
	}
	for _, asg := range a.sampleAssignments(p.Sample.ID, p.Journey.ID) {
		if asg.Finished() || asg.WorkerID == "" {
			continue
		}
		if p.Head != nil && asg.ID == p.Head.ID && p.Stage != "pre_collection" {
			continue
		}
		w := a.state.Users[asg.WorkerID]
		if w == nil || !w.Available || !a.qualified(w, asg, time.Now()) {
			return false
		}
	}
	return true
}

type replanOutcome struct {
	Status      string
	Replacement *Journey
}

// replanSample replans the unfinished work of one sample. Completed work and
// the current custody holder are preserved.
func (a *App) replanSample(tx *Tx, s *Sample, reason string, force bool) replanOutcome {
	p := a.samplePosition(s)
	if p.Stage == "done" || p.Stage == "at_laboratory" {
		return replanOutcome{Status: "not_required"}
	}
	j := p.Journey
	if !force && a.currentPlanValid(p) {
		return replanOutcome{Status: "not_required"}
	}
	in := a.planInputFor(p)
	plan := a.plan(in)
	if plan.Reason != "serviceable" && p.Continue && p.Head != nil {
		// The destination can no longer route onward: redirect the courier from the departure point.
		h := p.Head
		p.Continue = false
		p.Origin = nil
		p.StartAt = p.StartAt
		if a.state.Locations[h.FromLocationID] != nil {
			p.StartNode, p.StartCoord = h.FromLocationID, nil
		} else if h.FromCoordinate != nil {
			c := *h.FromCoordinate
			p.StartNode, p.StartCoord = "", &c
			p.Origin = &visit{LocationID: h.FromLocationID, Coordinate: c}
		}
		in = a.planInputFor(p)
		plan = a.plan(in)
	}
	j.PlanVersion++
	tx.MarkJourney(j)
	if plan.Reason != "serviceable" {
		a.cancelUnfinished(tx, j, s, p.Head, "replan_failed:"+plan.Reason)
		a.releaseReservations(tx, j.ID, s.ID, "", "replan_failed")
		if plan.Reason == "deadline_unreachable" {
			s.Status = SampleExpired
			tx.MarkSample(s)
			j.ReplanStatus = "expired"
			j.Status = JourneyExpired
			tx.MarkJourney(j)
			tx.SampleEvent(s, "sample_expired", "sample", s.ID, map[string]any{"reason": "delivery_deadline_unreachable", "trigger": reason, "journeyId": j.ID})
			a.emitSample(tx, s)
			a.emitJourney(tx, j)
			return replanOutcome{Status: "expired"}
		}
		j.ReplanStatus = "exception"
		tx.MarkJourney(j)
		a.flagException(tx, s, "no_valid_route", map[string]any{"planReason": plan.Reason, "trigger": reason, "journeyId": j.ID})
		a.emitJourney(tx, j)
		return replanOutcome{Status: "exception"}
	}
	nj := a.newJourney(tx, plan, []string{s.ID}, p.StartNode, p.StartCoord)
	nj.ParentJourneyID = j.ID
	tx.MarkJourney(nj)
	a.cancelUnfinished(tx, j, s, p.Head, "replanned")
	a.releaseReservations(tx, j.ID, s.ID, "", "replanned")
	head := p.Head
	if head != nil && p.Stage == "pre_collection" && head.WorkerID != "" {
		w := tx.st.Users[head.WorkerID]
		if w == nil || !w.Available || !a.qualified(w, head, tx.now) {
			tx.SampleEvent(s, "offer_withdrawn", "assignment", head.ID, map[string]any{"assignmentId": head.ID, "workerId": head.WorkerID, "reason": "worker_unavailable"})
			head.Status = AsgPending
			head.WorkerID = ""
			head.OfferExpiresAt = nil
		}
	}
	spec := chainSpec{Journey: nj, Sample: s, Request: p.Request, Plan: plan, Origin: p.Origin, Head: head, HeadKind: KindCollection, StartAt: p.StartAt}
	if head != nil && head.Status == AsgPending && head.WorkerID == "" {
		spec.Head = nil
		head.Status = AsgCancelled
		head.CancelReason = "replanned"
		head.CompletedAt = timePtr(tx.now)
		tx.MarkAssignment(head)
	}
	a.materialize(tx, spec)
	// Remove the sample from the old journey; mark it replaced when empty.
	remaining := []string{}
	for _, sid := range j.SampleIDs {
		if sid != s.ID {
			remaining = append(remaining, sid)
		}
	}
	j.SampleIDs = remaining
	j.ReplacementJourneyID = nj.ID
	j.ReplanStatus = "replaced"
	if len(remaining) == 0 {
		j.Status = JourneyReplaced
	} else {
		a.refreshRouteMode(j)
	}
	tx.MarkJourney(j)
	s.ActiveJourneyID = nj.ID
	s.JourneyIDs = append(s.JourneyIDs, nj.ID)
	s.TargetLaboratoryID = nj.TargetLaboratoryID
	tx.MarkSample(s)
	tx.SampleEvent(s, "journey_replanned", "journey", nj.ID, map[string]any{"previousJourneyId": j.ID, "journeyId": nj.ID, "reason": reason, "path": nj.Path, "estimatedDeliveryAt": fmtTime(nj.EstimatedDeliveryAt), "stage": p.Stage})
	a.emitSample(tx, s)
	a.emitJourney(tx, j)
	a.emitJourney(tx, nj)
	return replanOutcome{Status: "replaced", Replacement: nj}
}

func (a *App) replanJourney(tx *Tx, j *Journey, reason string, force bool) (string, []*Journey) {
	status := "not_required"
	var replacements []*Journey
	rank := map[string]int{"not_required": 0, "expired": 1, "exception": 2, "replaced": 3}
	for _, sid := range append([]string{}, j.SampleIDs...) {
		s := tx.st.Samples[sid]
		if s == nil {
			continue
		}
		out := a.replanSample(tx, s, reason, force)
		if out.Replacement != nil {
			replacements = append(replacements, out.Replacement)
		}
		if rank[out.Status] > rank[status] {
			status = out.Status
		}
	}
	return status, replacements
}

func (a *App) loadActiveJourney(c *reqCtx, id string, expected int) (*Journey, *apiError) {
	if expected < 1 {
		return nil, errf(400, "invalid_plan_version", "expectedPlanVersion must be at least 1")
	}
	j := c.st().Journeys[id]
	if j == nil {
		return nil, notFound("journey")
	}
	if !j.IsActive() {
		return nil, conflict("inactive_plan", "journey is %s", j.Status)
	}
	if j.PlanVersion != expected {
		return nil, conflict("stale_plan", "journey is at plan version %d", j.PlanVersion)
	}
	return j, nil
}

func (a *App) handleCancelJourney(c *reqCtx, body []byte) (int, any, *apiError) {
	type in struct {
		JourneyID           string `json:"journeyId"`
		ExpectedPlanVersion *int   `json:"expectedPlanVersion"`
		Reason              string `json:"reason"`
		IdempotencyKey      string `json:"idempotencyKey"`
	}
	req, e := decodeBody[in](body, "journeyId", "expectedPlanVersion", "idempotencyKey")
	if e != nil {
		return 0, nil, e
	}
	j, e := a.loadActiveJourney(c, req.JourneyID, *req.ExpectedPlanVersion)
	if e != nil {
		return 0, nil, e
	}
	a.cancelJourney(c.tx, j, req.Reason)
	return 201, map[string]any{"journeyId": j.ID, "status": "cancelled", "sampleIds": nonNil(j.SampleIDs)}, nil
}

func (a *App) cancelJourney(tx *Tx, j *Journey, reason string) {
	j.PlanVersion++
	a.finishJourney(tx, j, JourneyCancelled, "cancelled")
	for _, sid := range j.SampleIDs {
		s := tx.st.Samples[sid]
		if s == nil || s.Status == SampleReceived {
			continue
		}
		s.Status = SampleCancelled
		tx.MarkSample(s)
		tx.SampleEvent(s, "journey_cancelled", "journey", j.ID, map[string]any{"journeyId": j.ID, "reason": reason})
		a.emitSample(tx, s)
	}
}

func (a *App) handleRerouteJourney(c *reqCtx, body []byte) (int, any, *apiError) {
	type in struct {
		JourneyID           string `json:"journeyId"`
		ExpectedPlanVersion *int   `json:"expectedPlanVersion"`
		Reason              string `json:"reason"`
		IdempotencyKey      string `json:"idempotencyKey"`
	}
	req, e := decodeBody[in](body, "journeyId", "expectedPlanVersion", "idempotencyKey")
	if e != nil {
		return 0, nil, e
	}
	j, e := a.loadActiveJourney(c, req.JourneyID, *req.ExpectedPlanVersion)
	if e != nil {
		return 0, nil, e
	}
	status, reps := a.replanJourney(c.tx, j, "reroute:"+req.Reason, false)
	out := map[string]any{"journeyId": j.ID, "replanStatus": status}
	if len(reps) > 0 {
		out["replacementPlanId"] = reps[0].ID
		out["replacementJourney"] = a.journeyPlanJSON(reps[0], 1)
	}
	c.tx.Audit("journey_rerouted", "journey", j.ID, "", true, map[string]any{"replanStatus": status, "reason": req.Reason})
	return 201, out, nil
}

func (a *App) handleReportDisruption(c *reqCtx, body []byte) (int, any, *apiError) {
	type in struct {
		ResourceType   string `json:"resourceType"`
		ResourceID     string `json:"resourceId"`
		Reason         string `json:"reason"`
		OccurredAt     string `json:"occurredAt"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	req, e := decodeBody[in](body, "resourceType", "resourceID", "occurredAt", "idempotencyKey")
	if e != nil {
		req, e = decodeBody[in](body, "resourceType", "resourceId", "occurredAt", "idempotencyKey")
		if e != nil {
			return 0, nil, e
		}
	}
	at, e := reqTime(req.OccurredAt)
	if e != nil {
		return 0, nil, e
	}
	st := c.st()
	tx := c.tx
	affectedJourneys := map[string]*Journey{}
	touches := func(asg *Assignment) bool { return false }
	switch req.ResourceType {
	case "location", "node", "laboratory", "capacity":
		l := st.Locations[req.ResourceID]
		cn := st.Connections[req.ResourceID]
		if l == nil && (req.ResourceType != "capacity" || cn == nil) {
			return 0, nil, notFound("location")
		}
		if l != nil {
			if req.ResourceType == "capacity" {
				l.CapacityUnits, l.CooledCapacityUnits, l.CapacityConfigured = 0, 0, true
			} else {
				l.Active = false
			}
			tx.MarkLocation(l)
			tx.Emit("location.updated", "location", l.ID, a.locationEventPayload(l))
			touches = func(asg *Assignment) bool {
				return asg.FromLocationID == l.ID || asg.ToLocationID == l.ID || asg.NodeID == l.ID || asg.LaboratoryID == l.ID
			}
		} else {
			cn.CapacityUnits, cn.CooledCapacityUnits, cn.CapacityConfigured = 0, 0, true
			tx.MarkConnection(cn)
			tx.Emit("connection.updated", "connection", cn.ID, a.connectionEventPayload(cn))
			touches = func(asg *Assignment) bool { return asg.ConnectionID == cn.ID }
		}
		a.networkChanged(tx)
	case "connection", "route":
		cn := st.Connections[req.ResourceID]
		if cn == nil {
			if j := st.Journeys[req.ResourceID]; j != nil && req.ResourceType == "route" {
				affectedJourneys[j.ID] = j
				break
			}
			return 0, nil, notFound("connection")
		}
		cn.Active = false
		tx.MarkConnection(cn)
		tx.Emit("connection.updated", "connection", cn.ID, a.connectionEventPayload(cn))
		touches = func(asg *Assignment) bool { return asg.ConnectionID == cn.ID }
		a.networkChanged(tx)
	case "worker":
		w := st.Users[req.ResourceID]
		if w == nil {
			return 0, nil, notFound("worker")
		}
		w.Available = false
		tx.MarkUser(w)
		tx.Emit("user.updated", "user", w.ID, userEventPayload(w))
		touches = func(asg *Assignment) bool { return asg.WorkerID == w.ID }
	default:
		return 0, nil, errf(400, "invalid_resource_type", "unknown resourceType %q", req.ResourceType)
	}
	for _, j := range st.Journeys {
		if !j.IsActive() {
			continue
		}
		for _, asg := range a.journeyAssignments(j.ID) {
			if !asg.Finished() && touches(asg) {
				affectedJourneys[j.ID] = j
				break
			}
		}
	}
	d := &Disruption{ID: newID(), ResourceType: req.ResourceType, ResourceID: req.ResourceID, Reason: req.Reason, OccurredAt: at, ReportedBy: c.user.ID,
		AffectedSampleIDs: []string{}, ReplacementPlanIDs: []string{}, ReplanStatus: "not_required", CreatedAt: tx.now}
	rank := map[string]int{"not_required": 0, "expired": 1, "exception": 2, "replaced": 3}
	for _, id := range sortedKeys(affectedJourneys) {
		j := affectedJourneys[id]
		d.AffectedSampleIDs = append(d.AffectedSampleIDs, j.SampleIDs...)
		status, reps := a.replanJourney(tx, j, "disruption:"+req.ResourceType, true)
		for _, r := range reps {
			d.ReplacementPlanIDs = append(d.ReplacementPlanIDs, r.ID)
		}
		if rank[status] > rank[d.ReplanStatus] {
			d.ReplanStatus = status
		}
	}
	d.AffectedSampleIDs = uniqueStrs(d.AffectedSampleIDs)
	st.Disruptions[d.ID] = d
	tx.MarkDisruption(d)
	tx.Audit("disruption_reported", "disruption", d.ID, "", true, map[string]any{"resourceType": d.ResourceType, "resourceId": d.ResourceID, "reason": d.Reason, "affectedSampleIds": d.AffectedSampleIDs, "replacementPlanIds": d.ReplacementPlanIDs, "replanStatus": d.ReplanStatus})
	if req.ResourceType == "worker" {
		a.reofferIneligible(tx)
	}
	return 201, map[string]any{"disruptionId": d.ID, "affectedSampleIds": d.AffectedSampleIDs, "replacementPlanIds": d.ReplacementPlanIDs, "replanStatus": d.ReplanStatus}, nil
}

// ---- split ----

func (a *App) splitJourney(c *reqCtx, j *Journey, sampleIDs []string) (*Journey, *apiError) {
	if len(sampleIDs) == 0 {
		return nil, conflict("invalid_split", "sampleIds must not be empty")
	}
	set := uniqueStrs(sampleIDs)
	for _, sid := range set {
		if !containsStr(j.SampleIDs, sid) {
			return nil, conflict("invalid_split", "sample %s is not part of this journey", sid)
		}
		if a.pendingHandoff(sid) != nil {
			return nil, conflict("split_in_progress", "sample %s has a pending handoff", sid)
		}
	}
	if len(set) >= len(j.SampleIDs) {
		return nil, conflict("invalid_split", "at least one sample must remain in the journey")
	}
	tx := c.tx
	nj := &Journey{ID: newID(), ParentJourneyID: j.ID, PlanVersion: 1, Status: JourneyActive, ReplanStatus: "not_required", SampleIDs: set,
		Path: append([]string{}, j.Path...), StartNodeID: j.StartNodeID, StartCoordinate: j.StartCoordinate, TargetLaboratoryID: j.TargetLaboratoryID,
		EstimatedDeliveryAt: j.EstimatedDeliveryAt, TotalCostUnits: j.TotalCostUnits, CreatedAt: tx.now}
	for _, st := range j.Stops {
		ns := st
		ns.ID = newID()
		nj.Stops = append(nj.Stops, ns)
	}
	tx.st.Journeys[nj.ID] = nj
	for _, asg := range a.journeyAssignments(j.ID) {
		if containsStr(set, asg.SampleID) {
			asg.JourneyID = nj.ID
			tx.MarkAssignment(asg)
		}
	}
	for _, r := range tx.st.Reservations {
		if r.JourneyID == j.ID && containsStr(set, r.SampleID) {
			r.JourneyID = nj.ID
			tx.MarkReservation(r)
		}
	}
	remaining := []string{}
	for _, sid := range j.SampleIDs {
		if !containsStr(set, sid) {
			remaining = append(remaining, sid)
		}
	}
	j.SampleIDs = remaining
	j.SplitJourneyID = nj.ID
	j.PlanVersion++
	a.refreshRouteMode(j)
	a.refreshRouteMode(nj)
	tx.MarkJourney(j)
	tx.MarkJourney(nj)
	for _, sid := range set {
		s := tx.st.Samples[sid]
		s.ActiveJourneyID = nj.ID
		s.JourneyIDs = append(s.JourneyIDs, nj.ID)
		tx.MarkSample(s)
		tx.SampleEvent(s, "journey_split", "journey", nj.ID, map[string]any{"previousJourneyId": j.ID, "journeyId": nj.ID})
		a.emitSample(tx, s)
	}
	a.emitJourney(tx, j)
	a.emitJourney(tx, nj)
	return nj, nil
}

func (a *App) handleSplitJourney(c *reqCtx, body []byte) (int, any, *apiError) {
	type in struct {
		JourneyID           string   `json:"journeyId"`
		ExpectedPlanVersion *int     `json:"expectedPlanVersion"`
		SampleIDs           []string `json:"sampleIds"`
		IdempotencyKey      string   `json:"idempotencyKey"`
	}
	req, e := decodeBody[in](body, "journeyId", "expectedPlanVersion", "sampleIds", "idempotencyKey")
	if e != nil {
		return 0, nil, e
	}
	j, e := a.loadActiveJourney(c, req.JourneyID, *req.ExpectedPlanVersion)
	if e != nil {
		return 0, nil, e
	}
	nj, e := a.splitJourney(c, j, req.SampleIDs)
	if e != nil {
		return 0, nil, e
	}
	return 201, map[string]any{"journey": a.journeyPlanJSON(j, 1), "splitJourney": a.journeyPlanJSON(nj, 1)}, nil
}

// ---- merge ----

func temperatureCompatible(reqs []*Request) bool {
	lo, hi := -1e9, 1e9
	for _, r := range reqs {
		if r.TemperatureMinC > lo {
			lo = r.TemperatureMinC
		}
		if r.TemperatureMaxC < hi {
			hi = r.TemperatureMaxC
		}
	}
	return lo <= hi
}

func (a *App) mergeJourneys(c *reqCtx, target *Journey, sourceIDs []string) *apiError {
	tx := c.tx
	st := c.st()
	sourceIDs = uniqueStrs(sourceIDs)
	if len(sourceIDs) == 0 {
		return conflict("invalid_merge", "sourceJourneyIds must not be empty")
	}
	var sources []*Journey
	for _, id := range sourceIDs {
		if id == target.ID {
			return conflict("invalid_merge", "a journey cannot be merged into itself")
		}
		sj := st.Journeys[id]
		if sj == nil {
			return notFound("source journey")
		}
		if !sj.IsActive() {
			return conflict("inactive_plan", "source journey %s is %s", sj.ID, sj.Status)
		}
		sources = append(sources, sj)
	}
	if len(target.SampleIDs) == 0 {
		return conflict("invalid_merge", "target journey has no samples")
	}
	tp := a.samplePosition(st.Samples[target.SampleIDs[0]])
	if tp.Stage == "done" || tp.Stage == "in_transit" || tp.Stage == "at_laboratory" {
		return conflict("work_in_progress", "target journey is %s", tp.Stage)
	}
	if tp.StartNode == "" {
		return conflict("invalid_merge", "journeys can only be merged at a network node")
	}
	var positions []*position
	var samples []*Sample
	var reqs []*Request
	var types []*SampleType
	for _, sid := range target.SampleIDs {
		s := st.Samples[sid]
		samples = append(samples, s)
		reqs = append(reqs, st.Requests[s.RequestID])
		types = append(types, st.SampleTypes[s.SampleTypeID])
		if a.pendingHandoff(sid) != nil {
			return conflict("work_in_progress", "sample %s has a pending handoff", sid)
		}
	}
	for _, sj := range sources {
		for _, sid := range sj.SampleIDs {
			s := st.Samples[sid]
			p := a.samplePosition(s)
			if p.Stage == "in_transit" || p.Stage == "done" || p.Stage == "at_laboratory" || a.pendingHandoff(sid) != nil {
				return conflict("work_in_progress", "sample %s is %s", sid, p.Stage)
			}
			if p.StartNode != tp.StartNode {
				return conflict("partial_journey_merge", "sample %s is not at the same node as the target journey", sid)
			}
			positions = append(positions, p)
			samples = append(samples, s)
			reqs = append(reqs, st.Requests[s.RequestID])
			types = append(types, st.SampleTypes[s.SampleTypeID])
		}
	}
	for _, t := range types {
		if !t.BatchingAllowed {
			return conflict("pulse_no_batch", "sample type %s must not be batched", t.Name)
		}
	}
	for i, r := range reqs {
		for k, o := range reqs {
			if i == k {
				continue
			}
			if containsStr(r.IncompatibleSampleTypes, o.SampleTypeID) || containsStr(types[i].IncompatibleSampleTypes, o.SampleTypeID) {
				return conflict("incompatible_batch", "sample types %s and %s must not share a container", types[i].Name, types[k].Name)
			}
		}
	}
	if !temperatureCompatible(reqs) {
		return conflict("incompatible_batch", "temperature requirements are not compatible")
	}
	deadline := reqs[0].DeliveryDeadline
	startAt := tp.StartAt
	for i, r := range reqs {
		if r.DeliveryDeadline.Before(deadline) {
			deadline = r.DeliveryDeadline
		}
		if i > 0 && positions[i-1].StartAt.After(startAt) {
			startAt = positions[i-1].StartAt
		}
	}
	// Release the source reservations so the shared route can be validated with the combined load.
	for _, sj := range sources {
		for _, sid := range sj.SampleIDs {
			a.releaseReservations(tx, sj.ID, sid, "", "merged")
		}
	}
	path := a.remainingPath(tp)
	in := planInput{StartNode: tp.StartNode, StartAt: startAt, Types: types, Deadline: deadline, Units: len(samples), IgnoreJourney: target.ID}
	plan, e := a.validatePath(in, path)
	if e != nil {
		return e
	}
	// Re-reserve the target's own samples at the validated route (fresh reservations replace the old ones).
	for _, sid := range target.SampleIDs {
		a.releaseReservations(tx, target.ID, sid, "", "rebatched")
		for _, id := range plan.Path {
			a.reserve(tx, target, sid, "location", id, plan.Cooled)
		}
		for _, id := range plan.Conns {
			a.reserve(tx, target, sid, "connection", id, plan.Cooled)
		}
	}
	templates := map[string]*Assignment{}
	for _, asg := range a.journeyAssignments(target.ID) {
		if asg.SampleID == target.SampleIDs[0] && !asg.Finished() {
			templates[asg.Kind+"|"+asg.FromLocationID+"|"+asg.ToLocationID] = asg
		}
	}
	for _, p := range positions {
		s := p.Sample
		sj := p.Journey
		a.cancelUnfinished(tx, sj, s, p.Head, "merged")
		spec := chainSpec{Journey: target, Sample: s, Request: p.Request, Plan: plan, Head: p.Head, HeadKind: KindCollection, StartAt: p.StartAt}
		if p.Head != nil && p.Head.Status == AsgPending && p.Head.WorkerID == "" {
			spec.Head = nil
			p.Head.Status = AsgCancelled
			p.Head.CancelReason = "merged"
			tx.MarkAssignment(p.Head)
		}
		target.SampleIDs = append(target.SampleIDs, s.ID)
		created := a.materialize(tx, spec)
		for _, asg := range created {
			if p.Head != nil && asg.ID == p.Head.ID {
				continue
			}
			tmpl := templates[asg.Kind+"|"+asg.FromLocationID+"|"+asg.ToLocationID]
			if tmpl == nil || tmpl.WorkerID == "" || asg.Finished() {
				continue
			}
			w := st.Users[tmpl.WorkerID]
			if w == nil || !a.qualified(w, asg, tx.now) || !w.Available {
				continue
			}
			if asg.WorkerID != w.ID && a.activeAssignmentCount(w.ID) >= w.CapacityUnits {
				continue
			}
			asg.WorkerID = w.ID
			asg.Status = tmpl.Status
			asg.OfferedAt = tmpl.OfferedAt
			asg.OfferExpiresAt = tmpl.OfferExpiresAt
			asg.AcceptedAt = tmpl.AcceptedAt
			if asg.Status == AsgInProgress || asg.Status == AsgPickedUp || asg.Status == AsgInTransit || asg.Status == AsgArrived || asg.Status == AsgAtPickup {
				asg.Status = AsgAccepted
			}
			tx.MarkAssignment(asg)
			tx.SampleEvent(s, "assignment_batched", "assignment", asg.ID, map[string]any{"assignmentId": asg.ID, "workerId": w.ID, "status": asg.Status, "journeyId": target.ID})
			a.emitAssignment(tx, asg)
		}
		sj.Status = JourneyMerged
		sj.ReplacementJourneyID = target.ID
		sj.ReplanStatus = "replaced"
		sj.PlanVersion++
		tx.MarkJourney(sj)
		s.ActiveJourneyID = target.ID
		s.JourneyIDs = append(s.JourneyIDs, target.ID)
		s.TargetLaboratoryID = plan.Lab
		tx.MarkSample(s)
		tx.SampleEvent(s, "journey_merged", "journey", target.ID, map[string]any{"previousJourneyId": sj.ID, "journeyId": target.ID})
		a.emitSample(tx, s)
		a.emitJourney(tx, sj)
	}
	target.PlanVersion++
	target.EstimatedDeliveryAt = plan.ETA
	target.TotalCostUnits = plan.Cost
	a.refreshRouteMode(target)
	tx.MarkJourney(target)
	a.emitJourney(tx, target)
	return nil
}

func (a *App) handleMergeJourneys(c *reqCtx, body []byte) (int, any, *apiError) {
	type in struct {
		TargetJourneyID     string   `json:"targetJourneyId"`
		ExpectedPlanVersion *int     `json:"expectedPlanVersion"`
		SourceJourneyIDs    []string `json:"sourceJourneyIds"`
		IdempotencyKey      string   `json:"idempotencyKey"`
	}
	req, e := decodeBody[in](body, "targetJourneyId", "expectedPlanVersion", "sourceJourneyIds", "idempotencyKey")
	if e != nil {
		return 0, nil, e
	}
	j, e := a.loadActiveJourney(c, req.TargetJourneyID, *req.ExpectedPlanVersion)
	if e != nil {
		return 0, nil, e
	}
	if e := a.mergeJourneys(c, j, req.SourceJourneyIDs); e != nil {
		return 0, nil, e
	}
	return 201, a.journeyPlanJSON(j, 1), nil
}

// ---- edit active plan ----

// rebuildJourney replaces the unfinished part of every sample's chain with the
// validated path, keeping custody and completed work intact.
func (a *App) rebuildJourney(c *reqCtx, j *Journey, path []string) *apiError {
	tx := c.tx
	st := c.st()
	var plans []*planResult
	var positions []*position
	var types []*SampleType
	for _, sid := range j.SampleIDs {
		s := st.Samples[sid]
		p := a.samplePosition(s)
		if p.Stage == "done" || p.Stage == "at_laboratory" {
			return conflict("work_in_progress", "sample %s can no longer be rerouted", sid)
		}
		if a.pendingHandoff(sid) != nil {
			return conflict("work_in_progress", "sample %s has a pending handoff", sid)
		}
		positions = append(positions, p)
		types = append(types, st.SampleTypes[s.SampleTypeID])
	}
	for i, p := range positions {
		in := a.planInputFor(p)
		in.Types = types
		in.Units = len(j.SampleIDs)
		plan, e := a.validatePath(in, path)
		if e != nil {
			return e
		}
		plans = append(plans, plan)
		_ = i
	}
	for i, p := range positions {
		s := p.Sample
		a.cancelUnfinished(tx, j, s, p.Head, "plan_edited")
		a.releaseReservations(tx, j.ID, s.ID, "", "plan_edited")
		spec := chainSpec{Journey: j, Sample: s, Request: p.Request, Plan: plans[i], Origin: p.Origin, Head: p.Head, HeadKind: KindCollection, StartAt: p.StartAt}
		if p.Head != nil && p.Head.Status == AsgPending && p.Head.WorkerID == "" {
			spec.Head = nil
			p.Head.Status = AsgCancelled
			p.Head.CancelReason = "plan_edited"
			tx.MarkAssignment(p.Head)
		}
		if i == 0 {
			j.Stops = nil
		}
		a.materialize(tx, spec)
		s.TargetLaboratoryID = plans[i].Lab
		tx.MarkSample(s)
		tx.SampleEvent(s, "journey_plan_edited", "journey", j.ID, map[string]any{"journeyId": j.ID, "path": path, "planVersion": j.PlanVersion + 1})
		a.emitSample(tx, s)
	}
	j.Path = append([]string{}, plans[0].Path...)
	j.TargetLaboratoryID = plans[0].Lab
	j.EstimatedDeliveryAt = plans[0].ETA
	j.TotalCostUnits = plans[0].Cost
	j.PlanVersion++
	a.refreshRouteMode(j)
	tx.MarkJourney(j)
	a.emitJourney(tx, j)
	return nil
}

func (a *App) handleEditActivePlan(c *reqCtx, body []byte) (int, any, *apiError) {
	type in struct {
		JourneyID           string          `json:"journeyId"`
		ExpectedPlanVersion *int            `json:"expectedPlanVersion"`
		ChangeType          string          `json:"changeType"`
		Changes             json.RawMessage `json:"changes"`
		IdempotencyKey      string          `json:"idempotencyKey"`
	}
	req, e := decodeBody[in](body, "journeyId", "expectedPlanVersion", "changeType", "changes", "idempotencyKey")
	if e != nil {
		return 0, nil, e
	}
	changes := map[string]any{}
	if err := json.Unmarshal(req.Changes, &changes); err != nil {
		return 0, nil, badJSON("changes must be an object")
	}
	str := func(keys ...string) string {
		for _, k := range keys {
			if v, ok := changes[k].(string); ok {
				return v
			}
		}
		return ""
	}
	strs := func(keys ...string) []string {
		for _, k := range keys {
			if v, ok := changes[k].([]any); ok {
				var out []string
				for _, x := range v {
					if s, ok := x.(string); ok {
						out = append(out, s)
					}
				}
				return out
			}
		}
		return nil
	}
	validTypes := []string{"add_stop", "remove_stop", "reorder_stops", "replace_worker", "reassign_worker", "merge_samples", "split_samples", "split_batch", "cancel_work", "reroute", "replace_route"}
	if !containsStr(validTypes, req.ChangeType) {
		return 0, nil, errf(400, "invalid_change_type", "unknown changeType %q", req.ChangeType)
	}
	j, e := a.loadActiveJourney(c, req.JourneyID, *req.ExpectedPlanVersion)
	if e != nil {
		return 0, nil, e
	}
	st := c.st()
	tx := c.tx
	audit := func(details map[string]any) {
		details["changeType"] = req.ChangeType
		tx.Audit("plan_edited", "journey", j.ID, "", true, details)
	}
	switch req.ChangeType {
	case "cancel_work":
		a.cancelJourney(tx, j, str("reason"))
		audit(map[string]any{"reason": str("reason")})
		return 201, a.journeyPlanJSON(j, 1), nil
	case "reroute", "replace_route":
		if path := strs("path", "locationIds"); len(path) > 0 {
			if e := a.rebuildJourney(c, j, path); e != nil {
				return 0, nil, e
			}
			audit(map[string]any{"path": path})
			return 201, a.journeyPlanJSON(j, 1), nil
		}
		status, reps := a.replanJourney(tx, j, "edit:"+req.ChangeType, true)
		audit(map[string]any{"replanStatus": status})
		if len(reps) > 0 {
			return 201, a.journeyPlanJSON(reps[0], 1), nil
		}
		return 201, a.journeyPlanJSON(j, 1), nil
	case "merge_samples":
		if e := a.mergeJourneys(c, j, strs("sourceJourneyIds", "journeyIds")); e != nil {
			return 0, nil, e
		}
		audit(map[string]any{"sourceJourneyIds": strs("sourceJourneyIds", "journeyIds")})
		return 201, a.journeyPlanJSON(j, 1), nil
	case "split_samples", "split_batch":
		if _, e := a.splitJourney(c, j, strs("sampleIds")); e != nil {
			return 0, nil, e
		}
		audit(map[string]any{"sampleIds": strs("sampleIds")})
		return 201, a.journeyPlanJSON(j, 1), nil
	case "replace_worker", "reassign_worker":
		asg := st.Assignments[str("assignmentId")]
		if asg == nil || asg.JourneyID != j.ID {
			return 0, nil, conflict("invalid_assignment", "assignment is not part of this journey")
		}
		if asg.Finished() {
			return 0, nil, conflict("completed_work_immutable", "completed or cancelled assignments cannot be reassigned")
		}
		s := st.Samples[asg.SampleID]
		if s != nil && s.CurrentHolderID != "" && s.CurrentHolderID == asg.WorkerID {
			return 0, nil, conflict("work_in_progress", "the worker currently holds custody of the sample")
		}
		w := st.Users[str("workerId", "newWorkerId")]
		if w == nil {
			return 0, nil, errf(400, "invalid_worker", "workerId must reference an existing user")
		}
		if !a.qualified(w, asg, tx.now) {
			return 0, nil, conflict("ineligible_worker", "worker is not eligible for this assignment")
		}
		if !w.Available || a.activeAssignmentCount(w.ID) >= w.CapacityUnits {
			return 0, nil, conflict("worker_unavailable", "worker is unavailable or at capacity")
		}
		prev := asg.WorkerID
		asg.WorkerID = w.ID
		asg.Status = AsgOffered
		asg.OfferedAt = timePtr(tx.now)
		asg.OfferExpiresAt = timePtr(tx.now.Add(a.cfg.OfferTimeout))
		asg.AcceptedAt = nil
		asg.OfferCount++
		tx.MarkAssignment(asg)
		w.LastOfferedAt = timePtr(tx.now)
		tx.MarkUser(w)
		j.PlanVersion++
		tx.MarkJourney(j)
		if s != nil {
			tx.SampleEvent(s, "assignment_reassigned", "assignment", asg.ID, map[string]any{"assignmentId": asg.ID, "previousWorkerId": prev, "workerId": w.ID, "offerExpiresAt": fmtTime(*asg.OfferExpiresAt)})
		}
		a.emitAssignment(tx, asg)
		audit(map[string]any{"assignmentId": asg.ID, "previousWorkerId": prev, "workerId": w.ID})
		return 201, a.journeyPlanJSON(j, 1), nil
	}
	// Stop edits operate on the remaining path of the first sample.
	if len(j.SampleIDs) == 0 {
		return 0, nil, conflict("invalid_plan", "journey has no samples")
	}
	p := a.samplePosition(st.Samples[j.SampleIDs[0]])
	if p.Stage == "done" || p.Stage == "at_laboratory" {
		return 0, nil, conflict("work_in_progress", "journey can no longer be edited")
	}
	path := a.remainingPath(p)
	if len(path) == 0 {
		return 0, nil, conflict("invalid_plan", "journey has no remaining route")
	}
	fixedPrefix := 0
	if p.StartNode != "" {
		fixedPrefix = 1 // the current position cannot be edited
	}
	resolveLocation := func(id string) string {
		if st.Locations[id] != nil {
			return id
		}
		for _, stp := range j.Stops {
			if stp.ID == id {
				return stp.LocationID
			}
		}
		return ""
	}
	var newPath []string
	switch req.ChangeType {
	case "add_stop":
		loc := resolveLocation(str("locationId", "stopLocationId"))
		if loc == "" {
			return 0, nil, conflict("invalid_stop", "locationId must reference an existing location")
		}
		if d, ok := changes["dwellMinutes"].(float64); ok && d < 0 {
			return 0, nil, errf(400, "invalid_dwell", "dwellMinutes must not be negative")
		}
		if containsStr(path, loc) {
			return 0, nil, conflict("ambiguous_stop", "location is already part of the route")
		}
		idx := len(path) - 1
		if after := resolveLocation(str("afterLocationId", "afterStopId")); after != "" {
			found := false
			for i, id := range path {
				if id == after {
					idx = i + 1
					found = true
				}
			}
			if !found {
				return 0, nil, conflict("invalid_stop", "afterLocationId is not part of the remaining route")
			}
		} else if pos, ok := changes["position"].(float64); ok {
			idx = int(pos)
		}
		if idx < fixedPrefix || idx > len(path)-1 {
			return 0, nil, conflict("invalid_stop_order", "stop position must lie between the current position and the laboratory")
		}
		newPath = append(append(append([]string{}, path[:idx]...), loc), path[idx:]...)
	case "remove_stop":
		loc := resolveLocation(str("locationId", "stopId"))
		if loc == "" {
			return 0, nil, conflict("invalid_stop", "stopId or locationId must reference a stop")
		}
		idx := -1
		for i, id := range path {
			if id == loc {
				idx = i
			}
		}
		if idx == -1 {
			for _, stp := range j.Stops {
				if stp.LocationID == loc && stp.CompletedAt != nil {
					return 0, nil, conflict("completed_work_immutable", "completed stops cannot be removed")
				}
			}
			return 0, nil, conflict("invalid_stop", "stop is not part of the remaining route")
		}
		if idx < fixedPrefix {
			return 0, nil, conflict("completed_work_immutable", "the current position cannot be removed")
		}
		if idx == len(path)-1 {
			return 0, nil, conflict("invalid_destination", "the laboratory stop cannot be removed")
		}
		newPath = append(append([]string{}, path[:idx]...), path[idx+1:]...)
	case "reorder_stops":
		order := strs("stopIds", "locationIds", "order")
		if len(order) == 0 {
			return 0, nil, conflict("invalid_stop_order", "stopIds is required")
		}
		var resolved []string
		seen := map[string]bool{}
		for _, id := range order {
			loc := resolveLocation(id)
			if loc == "" {
				return 0, nil, conflict("invalid_stop", "unknown stop %s", id)
			}
			if seen[loc] {
				return 0, nil, conflict("ambiguous_stop_order", "stop %s listed more than once", id)
			}
			seen[loc] = true
			resolved = append(resolved, loc)
		}
		editable := path[fixedPrefix:]
		if len(resolved) == len(editable)-1 && !containsStr(resolved, editable[len(editable)-1]) {
			resolved = append(resolved, editable[len(editable)-1])
		}
		if len(resolved) != len(editable) {
			return 0, nil, conflict("invalid_stop_order", "the new order must include every remaining stop")
		}
		for _, id := range resolved {
			if !containsStr(editable, id) {
				return 0, nil, conflict("invalid_stop_order", "stop %s is not part of the remaining route", id)
			}
		}
		if resolved[len(resolved)-1] != editable[len(editable)-1] {
			return 0, nil, conflict("invalid_stop_order", "the laboratory must remain the final stop")
		}
		newPath = append(append([]string{}, path[:fixedPrefix]...), resolved...)
	}
	if e := a.rebuildJourney(c, j, newPath); e != nil {
		return 0, nil, e
	}
	audit(map[string]any{"previousPath": path, "path": newPath})
	return 201, a.journeyPlanJSON(j, 1), nil
}

