package app

import (
	"sort"
	"time"
)

type visit struct {
	LocationID string
	Coordinate Coordinate
	IsNode     bool
}

func (a *App) nodeVisit(id string) visit {
	l := a.state.Locations[id]
	return visit{LocationID: id, Coordinate: l.Coordinate, IsNode: true}
}

func routeMode(samples int, transportLegs int) string {
	if samples > 1 {
		return "batched"
	}
	if transportLegs > 1 {
		return "multi_stop"
	}
	return "direct"
}

// chainSpec describes how to materialise the assignment chain of one sample
// into a journey.
type chainSpec struct {
	Journey    *Journey
	Sample     *Sample
	Request    *Request
	Plan       *planResult
	Origin     *visit      // first visit when it is not Plan.Path[0]
	Head       *Assignment // carried assignment that stays with its worker
	HeadKind   string      // kind of a new head created for HeadWorker
	HeadWorker *User       // pre-sealed registrant holding the sample
	StartAt    time.Time
}

func (a *App) journeyAssignments(jID string) []*Assignment {
	var out []*Assignment
	for _, asg := range a.state.Assignments {
		if asg.JourneyID == jID {
			out = append(out, asg)
		}
	}
	sort.Slice(out, func(i, k int) bool {
		if out[i].Sequence != out[k].Sequence {
			return out[i].Sequence < out[k].Sequence
		}
		return out[i].CreatedAt.Before(out[k].CreatedAt)
	})
	return out
}

func (a *App) sampleAssignments(sampleID, journeyID string) []*Assignment {
	var out []*Assignment
	for _, asg := range a.state.Assignments {
		if asg.SampleID == sampleID && (journeyID == "" || asg.JourneyID == journeyID) {
			out = append(out, asg)
		}
	}
	sort.Slice(out, func(i, k int) bool {
		if out[i].JourneyID != out[k].JourneyID {
			return out[i].CreatedAt.Before(out[k].CreatedAt)
		}
		return out[i].Sequence < out[k].Sequence
	})
	return out
}

func (a *App) nextSequence(jID string) int {
	max := 0
	for _, asg := range a.state.Assignments {
		if asg.JourneyID == jID && asg.Sequence > max {
			max = asg.Sequence
		}
	}
	return max + 1
}

func (a *App) reserve(tx *Tx, j *Journey, sampleID, poolType, poolID string, cooled bool) {
	r := &Reservation{ID: newID(), PoolType: poolType, PoolID: poolID, JourneyID: j.ID, SampleID: sampleID, Cooled: cooled, Units: 1, Status: "active", CreatedAt: tx.now}
	tx.st.Reservations[r.ID] = r
	tx.MarkReservation(r)
	tx.Audit("capacity_reserved", "capacity", poolID, sampleID, true, map[string]any{"journeyId": j.ID, "cooled": cooled, "units": 1, "poolType": poolType, "capacity": a.capacityOf(poolID)})
}

func (a *App) releaseReservations(tx *Tx, journeyID, sampleID, poolID string, reason string) {
	for _, r := range tx.st.Reservations {
		if r.Status != "active" || r.JourneyID != journeyID {
			continue
		}
		if sampleID != "" && r.SampleID != sampleID {
			continue
		}
		if poolID != "" && r.PoolID != poolID {
			continue
		}
		r.Status = "released"
		r.ReleasedAt = timePtr(tx.now)
		tx.MarkReservation(r)
		tx.Audit("capacity_released", "capacity", r.PoolID, r.SampleID, true, map[string]any{"journeyId": journeyID, "cooled": r.Cooled, "reason": reason, "capacity": a.capacityOf(r.PoolID)})
	}
}

func (a *App) newAssignment(tx *Tx, j *Journey, s *Sample, kind string, seq int) *Assignment {
	asg := &Assignment{ID: newID(), JourneyID: j.ID, SampleID: s.ID, Kind: kind, Status: AsgPending, Sequence: seq, DeclinedBy: []string{}, CreatedAt: tx.now}
	tx.st.Assignments[asg.ID] = asg
	return asg
}

// materialize creates the stops, assignments and reservations for one sample
// following spec.Plan. New assignments (other than the head) are offered.
func (a *App) materialize(tx *Tx, spec chainSpec) []*Assignment {
	j, s, plan := spec.Journey, spec.Sample, spec.Plan
	visits := []visit{}
	if spec.Origin != nil {
		visits = append(visits, *spec.Origin)
	}
	for _, id := range plan.Path {
		visits = append(visits, a.nodeVisit(id))
	}
	// Stops (journey-level; rebuilt from the visits).
	if len(j.Stops) == 0 || (len(j.SampleIDs) > 0 && j.SampleIDs[0] == s.ID) {
		j.Stops = nil
		for k, v := range visits {
			st := Stop{ID: newID(), LocationID: v.LocationID, StopType: "handoff", Sequence: k + 1}
			coord := v.Coordinate
			st.Coordinate = &coord
			if k == 0 {
				st.StopType = "pickup"
				st.EstimatedAt = spec.StartAt
				if v.IsNode {
					st.DwellMinutes = a.state.Locations[v.LocationID].HandlingMinutes
				}
			} else {
				st.EstimatedAt = plan.Arrivals[k-len(visits)+len(plan.Path)]
				st.DwellMinutes = a.state.Locations[v.LocationID].HandlingMinutes
			}
			if k == len(visits)-1 {
				st.StopType = "delivery"
			}
			j.Stops = append(j.Stops, st)
		}
	}
	arrivalAt := func(k int) time.Time {
		idx := k - (len(visits) - len(plan.Path))
		if idx < 0 {
			return spec.StartAt
		}
		return plan.Arrivals[idx]
	}
	connFor := func(k int) string {
		idx := k - (len(visits) - len(plan.Path)) - 1
		if idx < 0 || idx >= len(plan.Conns) {
			return ""
		}
		return plan.Conns[idx]
	}
	seq := a.nextSequence(j.ID)
	var created []*Assignment
	headIsTransport := false
	fill := func(asg *Assignment, from, to visit) {
		asg.FromLocationID, asg.ToLocationID = from.LocationID, to.LocationID
		fc, tc := from.Coordinate, to.Coordinate
		asg.FromCoordinate, asg.ToCoordinate = &fc, &tc
		asg.Cooled = plan.Cooled
	}
	if spec.Head != nil {
		h := spec.Head
		h.JourneyID = j.ID
		h.Sequence = seq
		seq++
		if h.Kind == KindTransport {
			headIsTransport = true
			fill(h, visits[0], visits[1])
			h.ConnectionID = connFor(1)
			h.EstimatedEndAt = arrivalAt(1)
		}
		tx.MarkAssignment(h)
		created = append(created, h)
	} else {
		head := a.newAssignment(tx, j, s, spec.HeadKind, seq)
		seq++
		if spec.HeadKind == "" {
			head.Kind = KindCollection
		}
		switch head.Kind {
		case KindTransport:
			headIsTransport = true
			fill(head, visits[0], visits[1])
			head.ConnectionID = connFor(1)
			head.EstimatedStartAt, head.EstimatedEndAt = spec.StartAt, arrivalAt(1)
		default:
			fill(head, visits[0], visits[0])
			if visits[0].IsNode {
				head.NodeID = visits[0].LocationID
			}
			if head.Kind == KindLab {
				head.LaboratoryID = visits[0].LocationID
			}
			head.EstimatedStartAt, head.EstimatedEndAt = spec.StartAt, spec.StartAt
			if head.Kind == KindCollection && spec.Request != nil {
				head.EstimatedStartAt, head.EstimatedEndAt = spec.Request.EarliestCollectionAt, spec.Request.LatestCollectionAt
			}
		}
		if spec.HeadWorker != nil {
			head.WorkerID = spec.HeadWorker.ID
			head.AcceptedAt = timePtr(tx.now)
			head.Status = AsgInProgress
			if head.Kind == KindTransport {
				head.Status = AsgPickedUp
			}
		}
		tx.MarkAssignment(head)
		created = append(created, head)
	}
	for k := 1; k < len(visits); k++ {
		if !(k == 1 && headIsTransport) {
			t := a.newAssignment(tx, j, s, KindTransport, seq)
			seq++
			fill(t, visits[k-1], visits[k])
			t.ConnectionID = connFor(k)
			t.EstimatedStartAt, t.EstimatedEndAt = arrivalAt(k-1), arrivalAt(k)
			tx.MarkAssignment(t)
			created = append(created, t)
		}
		var n *Assignment
		if k < len(visits)-1 {
			n = a.newAssignment(tx, j, s, KindNode, seq)
			n.NodeID = visits[k].LocationID
		} else {
			n = a.newAssignment(tx, j, s, KindLab, seq)
			n.LaboratoryID = visits[k].LocationID
		}
		seq++
		fill(n, visits[k], visits[k])
		n.EstimatedStartAt, n.EstimatedEndAt = arrivalAt(k), arrivalAt(k)
		tx.MarkAssignment(n)
		created = append(created, n)
	}
	// Capacity reservations for every pool on the planned path.
	for _, id := range plan.Path {
		a.reserve(tx, j, s.ID, "location", id, plan.Cooled)
	}
	for _, id := range plan.Conns {
		a.reserve(tx, j, s.ID, "connection", id, plan.Cooled)
	}
	for _, asg := range created {
		if asg.Status == AsgPending && asg.WorkerID == "" {
			tx.SampleEvent(s, "assignment_created", "assignment", asg.ID, map[string]any{"assignmentId": asg.ID, "kind": asg.Kind, "journeyId": j.ID, "sequence": asg.Sequence, "fromLocationId": asg.FromLocationID, "toLocationId": asg.ToLocationID})
			a.offer(tx, asg)
		} else {
			tx.SampleEvent(s, "assignment_created", "assignment", asg.ID, map[string]any{"assignmentId": asg.ID, "kind": asg.Kind, "journeyId": j.ID, "sequence": asg.Sequence, "status": asg.Status, "workerId": asg.WorkerID})
		}
	}
	return created
}

func (a *App) newJourney(tx *Tx, plan *planResult, sampleIDs []string, startNode string, startCoord *Coordinate) *Journey {
	j := &Journey{ID: newID(), PlanVersion: 1, Status: JourneyActive, ReplanStatus: "not_required", SampleIDs: sampleIDs, Path: append([]string{}, plan.Path...),
		StartNodeID: startNode, StartCoordinate: startCoord, TargetLaboratoryID: plan.Lab, EstimatedDeliveryAt: plan.ETA, TotalCostUnits: plan.Cost, CreatedAt: tx.now}
	legs := len(plan.Conns)
	if startNode == "" {
		legs++
	}
	j.RouteMode = routeMode(len(sampleIDs), legs)
	tx.st.Journeys[j.ID] = j
	tx.MarkJourney(j)
	return j
}

func (a *App) refreshRouteMode(j *Journey) {
	legs := 0
	seen := map[int]bool{}
	for _, asg := range a.journeyAssignments(j.ID) {
		if asg.Kind == KindTransport && asg.Status != AsgCancelled && !seen[asg.Sequence] {
			seen[asg.Sequence] = true
			legs++
		}
	}
	j.RouteMode = routeMode(len(j.SampleIDs), legs)
}

// cancelUnfinished cancels every unfinished assignment of the sample in the
// journey except the carried one.
func (a *App) cancelUnfinished(tx *Tx, j *Journey, s *Sample, keep *Assignment, reason string) {
	for _, asg := range a.journeyAssignments(j.ID) {
		if asg.SampleID != s.ID || asg.Finished() || (keep != nil && asg.ID == keep.ID) {
			continue
		}
		asg.Status = AsgCancelled
		asg.CancelReason = reason
		asg.CompletedAt = timePtr(tx.now)
		tx.MarkAssignment(asg)
		tx.SampleEvent(s, "assignment_cancelled", "assignment", asg.ID, map[string]any{"assignmentId": asg.ID, "kind": asg.Kind, "workerId": asg.WorkerID, "reason": reason, "journeyId": j.ID})
		a.emitAssignment(tx, asg)
	}
}

func (a *App) participantIDs(s *Sample) []string {
	ids := []string{s.RequesterID}
	for _, asg := range a.state.Assignments {
		if asg.SampleID == s.ID && asg.WorkerID != "" {
			ids = append(ids, asg.WorkerID)
		}
	}
	if s.CurrentHolderID != "" {
		ids = append(ids, s.CurrentHolderID)
	}
	return uniqueStrs(ids)
}

func (a *App) emitSample(tx *Tx, s *Sample) {
	tx.Emit("sample.updated", "sample", s.ID, map[string]any{
		"sampleId": s.ID, "requestId": s.RequestID, "requesterId": s.RequesterID, "status": s.Status, "sealed": s.Sealed,
		"currentHolderId": s.CurrentHolderID, "activeJourneyId": s.ActiveJourneyID, "latestLocation": s.LatestLocation,
		"locationRecordedAt": fmtTimePtr(s.LocationRecordedAt), "participantIds": a.participantIDs(s),
	})
}

func (a *App) emitAssignment(tx *Tx, asg *Assignment) {
	s := tx.st.Samples[asg.SampleID]
	payload := map[string]any{"assignmentId": asg.ID, "sampleId": asg.SampleID, "journeyId": asg.JourneyID, "kind": asg.Kind, "status": asg.Status, "workerId": asg.WorkerID, "sequence": asg.Sequence}
	if s != nil {
		payload["requesterId"] = s.RequesterID
		payload["participantIds"] = a.participantIDs(s)
	}
	tx.Emit("assignment.updated", "assignment", asg.ID, payload)
}

func (a *App) emitJourney(tx *Tx, j *Journey) {
	parts := []string{}
	for _, sid := range j.SampleIDs {
		if s := tx.st.Samples[sid]; s != nil {
			parts = append(parts, a.participantIDs(s)...)
		}
	}
	tx.Emit("journey.updated", "journey", j.ID, map[string]any{"journeyId": j.ID, "status": j.Status, "planVersion": j.PlanVersion, "routeMode": j.RouteMode, "sampleIds": nonNil(j.SampleIDs), "participantIds": uniqueStrs(parts)})
}

// ---- plan views ----

func stopJSON(st Stop) map[string]any {
	m := map[string]any{"stopId": st.ID, "locationId": st.LocationID, "stopType": st.StopType, "sequence": st.Sequence,
		"estimatedAt": fmtTime(st.EstimatedAt), "dwellMinutes": st.DwellMinutes}
	if st.Coordinate != nil {
		m["coordinate"] = *st.Coordinate
	}
	if st.CompletedAt != nil {
		m["completedAt"] = fmtTime(*st.CompletedAt)
	}
	return m
}

func legJSON(asg *Assignment, includeWorker bool) map[string]any {
	m := map[string]any{"assignmentId": asg.ID, "sequence": asg.Sequence, "status": asg.Status, "sampleId": asg.SampleID}
	if asg.FromLocationID != "" {
		m["fromLocationId"] = asg.FromLocationID
	}
	if asg.ToLocationID != "" {
		m["toLocationId"] = asg.ToLocationID
	}
	if includeWorker && asg.WorkerID != "" {
		m["workerId"] = asg.WorkerID
	}
	return m
}

func (a *App) journeyStopsJSON(j *Journey) []map[string]any {
	out := []map[string]any{}
	for _, st := range j.Stops {
		out = append(out, stopJSON(st))
	}
	return out
}

func (a *App) journeyPlanJSON(j *Journey, depth int) map[string]any {
	asgs := a.journeyAssignments(j.ID)
	legs := []map[string]any{}
	var collection, nodes, labs, transports []string
	workers := []string{}
	for _, asg := range asgs {
		if asg.Status == AsgCancelled {
			continue
		}
		if asg.WorkerID != "" {
			workers = append(workers, asg.WorkerID)
		}
		switch asg.Kind {
		case KindTransport:
			legs = append(legs, legJSON(asg, true))
			transports = append(transports, asg.ID)
		case KindCollection:
			collection = append(collection, asg.ID)
		case KindNode:
			nodes = append(nodes, asg.ID)
		case KindLab:
			labs = append(labs, asg.ID)
		}
	}
	// Transport leg sequence numbers are reported relative to the transport chain.
	seqMap := map[int]int{}
	for _, l := range legs {
		s := l["sequence"].(int)
		if _, ok := seqMap[s]; !ok {
			seqMap[s] = len(seqMap) + 1
		}
	}
	for _, l := range legs {
		l["sequence"] = seqMap[l["sequence"].(int)]
	}
	m := map[string]any{
		"journeyId": j.ID, "planVersion": j.PlanVersion, "routeMode": j.RouteMode, "status": j.Status,
		"estimatedDeliveryAt": fmtTime(j.EstimatedDeliveryAt), "totalCostUnits": j.TotalCostUnits,
		"sampleIds": nonNil(j.SampleIDs), "orderedStops": a.journeyStopsJSON(j), "legs": legs,
		"assignedWorkerIds": uniqueStrs(workers), "collectionAssignmentIds": nonNil(collection),
		"nodeAssignmentIds": nonNil(nodes), "laboratoryAssignmentIds": nonNil(labs), "valid": j.Status == JourneyActive || j.Status == JourneyCompleted,
		"capacityUsed": len(j.SampleIDs), "capacityAvailable": a.journeyCapacityAvailable(j),
	}
	if j.ParentJourneyID != "" {
		m["parentJourneyId"] = j.ParentJourneyID
	}
	if len(collection) > 0 {
		m["collectionAssignmentId"] = collection[0]
	}
	// First/middle/final transport ids follow the chain of the first sample.
	uniqTransports := []string{}
	for _, asg := range asgs {
		if asg.Kind == KindTransport && asg.Status != AsgCancelled && len(j.SampleIDs) > 0 && asg.SampleID == j.SampleIDs[0] {
			uniqTransports = append(uniqTransports, asg.ID)
		}
	}
	if len(uniqTransports) == 0 {
		uniqTransports = transports
	}
	if len(uniqTransports) > 0 {
		m["firstTransportAssignmentId"] = uniqTransports[0]
		m["finalTransportAssignmentId"] = uniqTransports[len(uniqTransports)-1]
		if len(uniqTransports) >= 3 {
			m["middleTransportAssignmentId"] = uniqTransports[1]
		}
	}
	if j.ReplanStatus != "" {
		m["replanStatus"] = j.ReplanStatus
	}
	if depth < 2 {
		if j.SplitJourneyID != "" {
			if sj := a.state.Journeys[j.SplitJourneyID]; sj != nil {
				m["splitJourney"] = a.journeyPlanJSON(sj, depth+1)
			}
		}
		if j.ReplacementJourneyID != "" {
			if rj := a.state.Journeys[j.ReplacementJourneyID]; rj != nil {
				m["replacementJourney"] = a.journeyPlanJSON(rj, depth+1)
			}
		}
	}
	return m
}

func (a *App) journeyCapacityAvailable(j *Journey) int {
	min := unlimitedUnits
	cooled := false
	for _, sid := range j.SampleIDs {
		if s := a.state.Samples[sid]; s != nil {
			if t := a.state.SampleTypes[s.SampleTypeID]; t != nil && t.RequiresCooledRoute {
				cooled = true
			}
		}
	}
	for _, id := range j.Path {
		if a.poolConfigured(id) {
			if v := a.available(id, cooled, ""); v < min {
				min = v
			}
		}
	}
	for _, asg := range a.journeyAssignments(j.ID) {
		if asg.ConnectionID != "" && a.poolConfigured(asg.ConnectionID) {
			if v := a.available(asg.ConnectionID, cooled, ""); v < min {
				min = v
			}
		}
	}
	if min == unlimitedUnits {
		return 0
	}
	if min < 0 {
		return 0
	}
	return min
}

func (a *App) workerJourneyPlanJSON(j *Journey, u *User) map[string]any {
	asgs := a.journeyAssignments(j.ID)
	mine := map[string]bool{}
	ids := []string{}
	for _, asg := range asgs {
		if asg.WorkerID == u.ID {
			mine[asg.ID] = true
			ids = append(ids, asg.ID)
		}
	}
	// Workers see their own legs plus the adjacent legs they hand off with.
	visible := map[string]bool{}
	for i, asg := range asgs {
		if !mine[asg.ID] {
			continue
		}
		visible[asg.ID] = true
		for k := i - 1; k >= 0; k-- {
			if asgs[k].SampleID == asg.SampleID && asgs[k].Status != AsgCancelled {
				visible[asgs[k].ID] = true
				break
			}
		}
		for k := i + 1; k < len(asgs); k++ {
			if asgs[k].SampleID == asg.SampleID && asgs[k].Status != AsgCancelled {
				visible[asgs[k].ID] = true
				break
			}
		}
	}
	legs := []map[string]any{}
	stopLocs := map[string]bool{}
	var collection, nodes, labs []string
	workers := []string{}
	for _, asg := range asgs {
		if !visible[asg.ID] {
			continue
		}
		legs = append(legs, legJSON(asg, true))
		stopLocs[asg.FromLocationID] = true
		stopLocs[asg.ToLocationID] = true
		if asg.WorkerID != "" {
			workers = append(workers, asg.WorkerID)
		}
		if mine[asg.ID] {
			switch asg.Kind {
			case KindCollection:
				collection = append(collection, asg.ID)
			case KindNode:
				nodes = append(nodes, asg.ID)
			case KindLab:
				labs = append(labs, asg.ID)
			}
		}
	}
	stops := []map[string]any{}
	for _, st := range j.Stops {
		if stopLocs[st.LocationID] {
			stops = append(stops, stopJSON(st))
		}
	}
	m := map[string]any{
		"journeyId": j.ID, "planVersion": j.PlanVersion, "routeMode": j.RouteMode, "status": j.Status,
		"estimatedDeliveryAt": fmtTime(j.EstimatedDeliveryAt), "scope": "assigned_legs", "assignmentIds": nonNil(ids),
		"sampleIds": nonNil(j.SampleIDs), "legs": legs, "orderedStops": stops, "collectionAssignmentIds": nonNil(collection),
		"nodeAssignmentIds": nonNil(nodes), "laboratoryAssignmentIds": nonNil(labs), "assignedWorkerIds": uniqueStrs(workers),
	}
	if j.ParentJourneyID != "" {
		m["parentJourneyId"] = j.ParentJourneyID
	}
	return m
}

func (a *App) requesterJourneyPlanJSON(j *Journey, requesterID string) map[string]any {
	legs := []map[string]any{}
	sampleIDs := []string{}
	for _, sid := range j.SampleIDs {
		if s := a.state.Samples[sid]; s != nil && s.RequesterID == requesterID {
			sampleIDs = append(sampleIDs, sid)
		}
	}
	for _, asg := range a.journeyAssignments(j.ID) {
		if asg.Status == AsgCancelled || !containsStr(sampleIDs, asg.SampleID) {
			continue
		}
		l := legJSON(asg, false)
		l["kind"] = asg.Kind
		legs = append(legs, l)
	}
	m := map[string]any{
		"journeyId": j.ID, "planVersion": j.PlanVersion, "routeMode": j.RouteMode, "status": j.Status,
		"estimatedDeliveryAt": fmtTime(j.EstimatedDeliveryAt), "totalCostUnits": j.TotalCostUnits,
		"sampleIds": sampleIDs, "orderedStops": a.journeyStopsJSON(j), "legs": legs,
	}
	if j.ParentJourneyID != "" {
		m["parentJourneyId"] = j.ParentJourneyID
	}
	return m
}

