}

// ---- audit ----

func auditJSON(r store.AuditRow) map[string]any {
	id := itoa(r.ID)
	return map[string]any{
		"auditId": id, "audit_id": id, "actorId": r.ActorID, "actor_id": r.ActorID, "role": r.Role, "actorRole": r.Role,
		"action": r.Action, "entityType": r.EntityType, "entity_type": r.EntityType, "entityId": r.EntityID, "entity_id": r.EntityID,
		"success": r.Success, "occurredAt": fmtTime(r.OccurredAt), "occurred_at": fmtTime(r.OccurredAt), "details": r.Details,
	}
}

func itoa(v int64) string {
	if v == 0 {
		return "0"
	}
	neg := v < 0
	if neg {
		v = -v
	}
	var b [24]byte
	i := len(b)
	for v > 0 {
		i--
		b[i] = byte('0' + v%10)
		v /= 10
	}
	if neg {
		i--
		b[i] = '-'
	}
	return string(b[i:])
}

func (a *App) handleSearchAudit(c *reqCtx, body []byte) (int, any, *apiError) {
	type in struct {
		Query      string  `json:"query"`
		ActorID    string  `json:"actorId"`
		EntityType string  `json:"entityType"`
		EntityID   string  `json:"entityId"`
		Action     string  `json:"action"`
		Role       string  `json:"role"`
		Success    *bool   `json:"success"`
		FromTime   *string `json:"fromTime"`
		ToTime     *string `json:"toTime"`
		Limit      *int    `json:"limit"`
		Offset     *int    `json:"offset"`
		Order      string  `json:"order"`
	}
	req, e := decodeBody[in](body)
	if e != nil {
		return 0, nil, e
	}
	limit, offset := 500, 0
	if req.Limit != nil {
		if *req.Limit < 1 || *req.Limit > 5000 {
			return 0, nil, errf(400, "invalid_limit", "limit must be between 1 and 5000")
		}
		limit = *req.Limit
	}
	if req.Offset != nil {
		if *req.Offset < 0 {
			return 0, nil, errf(400, "invalid_offset", "offset must not be negative")
		}
		offset = *req.Offset
	}
	order := "newest_first"
	if req.Order != "" {
		if req.Order != "newest_first" && req.Order != "oldest_first" {
			return 0, nil, errf(400, "invalid_order", "order must be newest_first or oldest_first")
		}
		order = req.Order
	}
	from, e := optTime(req.FromTime)
	if e != nil {
		return 0, nil, e
	}
	to, e := optTime(req.ToTime)
	if e != nil {
		return 0, nil, e
	}
	f := store.AuditFilter{Query: strings.TrimSpace(req.Query), ActorID: req.ActorID, EntityType: req.EntityType, EntityID: req.EntityID, Action: req.Action,
		Role: req.Role, Success: req.Success, FromTime: from, ToTime: to, Limit: limit, Offset: offset, NewestFirst: order == "newest_first"}
	rows, total, err := a.store.SearchAudit(c.r.Context(), f)
	if err != nil {
		return 0, nil, errf(500, "internal_error", "audit search failed")
	}
	entries := []map[string]any{}
	for _, r := range rows {
		entries = append(entries, auditJSON(r))
	}
	out := map[string]any{"entries": entries, "total": total, "returned": len(entries), "offset": offset, "limit": limit, "order": order, "hasMore": offset+len(entries) < total}
	if offset+len(entries) < total {
		out["nextOffset"] = offset + len(entries)
	}
	c.tx.Audit("audit_searched", "audit", "search", "", true, map[string]any{"query": req.Query, "entityId": req.EntityID, "returned": len(entries), "total": total})
	return 200, out, nil
}

