// canViewSample applies data-level access control for sample reads.
func (a *App) canViewSample(u *User, role string, s *Sample) bool {
	roles := u.Roles
	if role != "" {
		roles = []string{role}
	}
	for _, r := range roles {
		switch r {
		case RoleAdmin, RoleDispatcher:
			return true
		case RoleRequester:
			if s.RequesterID == u.ID {
				return true
			}
		case RoleCollector, RoleCourier, RoleNode, RoleLab:
			if s.CurrentHolderID == u.ID {
				return true
			}
			for _, asg := range a.state.Assignments {
				if asg.SampleID == s.ID && asg.WorkerID == u.ID {
					return true
				}
			}
		}
	}
	return false
}

func (a *App) handleReadSampleState(c *reqCtx, body []byte) (int, any, *apiError) {
