func (a *App) assignmentHistory(asg *Assignment, s *Sample) []TimelineEntry {
	var out []TimelineEntry
	for _, e := range s.Timeline {
		if e.EntityID == asg.ID {
			out = append(out, e)
			continue
		}
		if id, ok := e.Details["assignmentId"].(string); ok && id == asg.ID {
			out = append(out, e)
		}
