func (a *App) assignmentWorkItem(asg *Assignment) map[string]any {
	s := a.state.Samples[asg.SampleID]
	m := map[string]any{"kind": asg.Kind, "assignmentId": asg.ID, "assignment_id": asg.ID, "sampleId": asg.SampleID, "sample_id": asg.SampleID,
		"status": asg.Status, "journeyId": asg.JourneyID, "sequence": asg.Sequence}
	if s != nil {
		m["history"] = timelineJSON(a.assignmentHistory(asg, s))
	} else {
		m["history"] = []any{}
	}
	if asg.FromLocationID != "" {
		m["fromLocationId"] = asg.FromLocationID
	}
	if asg.ToLocationID != "" {
		m["toLocationId"] = asg.ToLocationID
	}
	if asg.OfferExpiresAt != nil && asg.Status == AsgOffered {
		m["offerExpiresAt"] = fmtTime(*asg.OfferExpiresAt)
	}
	switch asg.Kind {
	case KindTransport:
		if asg.ToLocationID != "" && a.state.Locations[asg.ToLocationID] != nil {
			m["destinationCapacity"] = a.capacityOf(asg.ToLocationID)
		}
	case KindNode:
		m["nodeId"] = asg.NodeID
		if prev := a.priorAssignment(asg); prev != nil && prev.FromLocationID != "" {
			m["incomingFromLocationId"] = prev.FromLocationID
		}
		if next := a.nextAssignment(asg); next != nil && next.ToLocationID != "" {
			m["outgoingToLocationId"] = next.ToLocationID
		}
	case KindLab:
		m["laboratoryId"] = asg.LaboratoryID
		if s != nil {
			m["expectedSampleTypeId"] = s.SampleTypeID
		}
	}
	return m
}

func (a *App) journeyWorkItem(j *Journey) map[string]any {
	history := []TimelineEntry{}
	for _, sid := range j.SampleIDs {
		if s := a.state.Samples[sid]; s != nil {
			for _, e := range s.Timeline {
				if e.EntityID == j.ID || e.Details["journeyId"] == j.ID {
					history = append(history, e)
				}
			}
		}
	}
	sort.SliceStable(history, func(i, k int) bool { return history[i].OccurredAt.Before(history[k].OccurredAt) })
	count := 0
	for _, asg := range a.journeyAssignments(j.ID) {
		if asg.Status != AsgCancelled {
			count++
		}
	}
	return map[string]any{"kind": "journey", "journeyId": j.ID, "journey_id": j.ID, "status": j.Status, "routeMode": j.RouteMode, "planVersion": j.PlanVersion,
		"sampleIds": nonNil(j.SampleIDs), "estimatedDeliveryAt": fmtTime(j.EstimatedDeliveryAt), "assignmentCount": count, "history": timelineJSON(history)}
}

func (a *App) handleListRoleWork(c *reqCtx, body []byte) (int, any, *apiError) {
	type in struct {
		Role   string `json:"role"`
		Status string `json:"status"`
	}
	req, e := decodeBody[in](body)
	if e != nil {
		return 0, nil, e
	}
	role := c.role
	if req.Role != "" {
		if !containsStr(AllRoles, req.Role) {
			return 0, nil, errf(400, "invalid_role", "unknown role %q", req.Role)
		}
		if !c.user.HasRole(req.Role) {
			return 0, nil, forbidden("you do not hold the role " + req.Role)
		}
		role = req.Role
	}
	if role == "" {
		return 0, nil, conflict("role_not_selected", "select an active role first")
	}
	pending, inProgress, completed := []map[string]any{}, []map[string]any{}, []map[string]any{}
	push := func(bucket string, item map[string]any) {
		if req.Status != "" && item["status"] != req.Status {
			return
		}
		switch bucket {
		case "pending":
			pending = append(pending, item)
		case "inProgress":
			inProgress = append(inProgress, item)
		default:
			completed = append(completed, item)
		}
	}
	switch role {
	case RoleRequester:
		for _, s := range a.samplesSorted() {
			if s.RequesterID != c.user.ID {
				continue
			}
			item := a.sampleWorkItem(s)
			switch s.Status {
			case SampleRequested, SampleUnserviceable:
				push("pending", item)
			case SampleReceived, SampleCancelled, SampleExpired:
				push("completed", item)
			default:
				push("inProgress", item)
			}
		}
	case RoleDispatcher, RoleAdmin:
		var js []*Journey
		for _, j := range a.state.Journeys {
			js = append(js, j)
		}
		sort.Slice(js, func(i, k int) bool { return js[i].CreatedAt.Before(js[k].CreatedAt) })
		for _, j := range js {
			item := a.journeyWorkItem(j)
			if !j.IsActive() {
				push("completed", item)
				continue
			}
			started := false
			for _, asg := range a.journeyAssignments(j.ID) {
				if asg.Started() || asg.Status == AsgCompleted {
					started = true
					break
				}
			}
			if started {
				push("inProgress", item)
			} else {
				push("pending", item)
			}
		}
	default:
		var asgs []*Assignment
		for _, asg := range a.state.Assignments {
			if asg.WorkerID == c.user.ID && roleForKind(asg.Kind) == role {
				asgs = append(asgs, asg)
			}
		}
		sort.Slice(asgs, func(i, k int) bool {
			if !asgs[i].CreatedAt.Equal(asgs[k].CreatedAt) {
				return asgs[i].CreatedAt.Before(asgs[k].CreatedAt)
			}
			return asgs[i].Sequence < asgs[k].Sequence
		})
		for _, asg := range asgs {
			item := a.assignmentWorkItem(asg)
			switch {
			case asg.Status == AsgOffered:
				push("pending", item)
			case asg.Finished():
				push("completed", item)
			default:
				push("inProgress", item)
			}
		}
	}
	return 200, map[string]any{"pending": pending, "inProgress": inProgress, "completed": completed}, nil
}

// ---- operations state ----

func (a *App) operationsState(sampleTypeFilter string) map[string]any {
	now := time.Now()
	samples := []map[string]any{}
	exceptions := []map[string]any{}
	delays := []map[string]any{}
	for _, s := range a.samplesSorted() {
		if sampleTypeFilter != "" && s.SampleTypeID != sampleTypeFilter {
			continue
		}
		r := a.state.Requests[s.RequestID]
		m := map[string]any{"sampleId": s.ID, "sample_id": s.ID, "status": s.Status, "requestId": s.RequestID, "locationStale": a.isStale(s.LocationRecordedAt, now)}
		if r != nil {
			m["origin"] = r.Origin
			m["deliveryDeadline"] = fmtTime(r.DeliveryDeadline)
		}
		if s.CurrentHolderID != "" {
			m["currentHolderId"] = s.CurrentHolderID
		}
		if s.ActiveJourneyID != "" {
			m["activeJourneyId"] = s.ActiveJourneyID
		}
		if s.LatestLocation != nil {
			m["latestLocation"] = *s.LatestLocation
		}
		if s.LocationRecordedAt != nil {
			m["locationRecordedAt"] = fmtTime(*s.LocationRecordedAt)
		}
		samples = append(samples, m)
		if s.Exception != nil || s.Status == SampleException || s.Status == SampleExpired {
			ex := map[string]any{"sampleId": s.ID, "status": s.Status, "requestId": s.RequestID}
			if s.Exception != nil {
				for k, v := range s.Exception {
					ex[k] = v
				}
			} else {
				ex["reason"] = "delivery_deadline_missed"
			}
			exceptions = append(exceptions, ex)
		}
		if j := a.state.Journeys[s.ActiveJourneyID]; j != nil && j.IsActive() && r != nil && j.EstimatedDeliveryAt.After(r.DeliveryDeadline) {
			delays = append(delays, map[string]any{"sampleId": s.ID, "journeyId": j.ID, "estimatedDeliveryAt": fmtTime(j.EstimatedDeliveryAt), "deliveryDeadline": fmtTime(r.DeliveryDeadline), "reason": "estimated_arrival_after_deadline"})
		}
		for _, asg := range a.sampleAssignments(s.ID, s.ActiveJourneyID) {
			if asg.Status == AsgPending && asg.WorkerID == "" {
				delays = append(delays, map[string]any{"sampleId": s.ID, "assignmentId": asg.ID, "kind": asg.Kind, "reason": "awaiting_eligible_worker", "since": fmtTime(asg.CreatedAt)})
			}
		}
	}
	workers := []map[string]any{}
	counts := []int{}
	ineligible := 0
	for _, id := range sortedKeys(a.state.Users) {
		u := a.state.Users[id]
		if !u.IsWorker() {
			continue
		}
		roles := []string{}
		for _, r := range u.Roles {
			if containsStr(WorkerRoles, r) {
				roles = append(roles, r)
			}
		}
		count := a.activeAssignmentCount(u.ID)
		status := "unavailable"
		if u.Available && u.Active {
			status = "available"
			counts = append(counts, count)
		}
		w := map[string]any{"workerId": u.ID, "worker_id": u.ID, "fullName": u.FullName, "roles": roles, "available": u.Available && u.Active, "status": status,
			"capacityUnits": u.CapacityUnits, "assignmentCount": count, "locationStale": a.isStale(u.LocationRecordedAt, now)}
		if u.LatestLocation != nil {
			w["latestLocation"] = *u.LatestLocation
			w["latest_location"] = *u.LatestLocation
		}
		if u.LocationRecordedAt != nil {
			w["locationRecordedAt"] = fmtTime(*u.LocationRecordedAt)
		}
		workers = append(workers, w)
	}
	for _, asg := range a.state.Assignments {
		if asg.Finished() || asg.WorkerID == "" {
			continue
		}
		w := a.state.Users[asg.WorkerID]
		if w == nil || !a.qualified(w, asg, now) {
			ineligible++
		}
	}
	spread := 0
	if len(counts) > 0 {
		min, max := counts[0], counts[0]
		for _, c := range counts {
			if c < min {
				min = c
			}
			if c > max {
				max = c
			}
		}
		spread = max - min
	}
	locations := []map[string]any{}
	for _, id := range sortedKeys(a.state.Locations) {
		l := a.state.Locations[id]
		m := a.locationEventPayload(l)
		m["id"] = l.ID
		locations = append(locations, m)
	}
	connections := []map[string]any{}
	for _, id := range sortedKeys(a.state.Connections) {
		cn := a.state.Connections[id]
		m := a.connectionEventPayload(cn)
		m["id"] = cn.ID
		connections = append(connections, m)
	}
	routes := []map[string]any{}
	for _, id := range sortedKeys(a.state.Journeys) {
		j := a.state.Journeys[id]
		if !j.IsActive() {
			continue
		}
		routes = append(routes, map[string]any{"journeyId": j.ID, "status": j.Status, "routeMode": j.RouteMode, "planVersion": j.PlanVersion, "sampleIds": nonNil(j.SampleIDs),
			"path": nonNil(j.Path), "targetLaboratoryId": j.TargetLaboratoryID, "estimatedDeliveryAt": fmtTime(j.EstimatedDeliveryAt), "orderedStops": a.journeyStopsJSON(j), "startCoordinate": j.StartCoordinate})
	}
	handoffs := []map[string]any{}
	for _, id := range sortedKeys(a.state.Handoffs) {
		h := a.state.Handoffs[id]
		if h.Status == "pending" {
			handoffs = append(handoffs, handoffJSON(h))
		}
	}
	return map[string]any{
		"samples": samples, "workers": workers, "locations": locations, "connections": connections, "routes": routes,
		"handoffs": handoffs, "delays": delays, "exceptions": exceptions, "assignmentCountSpread": spread, "ineligibleAssignmentCount": ineligible,
	}
}

func (a *App) handleReadOperationsState(c *reqCtx, body []byte) (int, any, *apiError) {
	type in struct {
		Filters *struct {
			SampleTypeID  string `json:"sampleTypeId"`
			SampleTypeID2 string `json:"sample_type_id"`
		} `json:"filters"`
	}
	req, e := decodeBody[in](body)
	if e != nil {
		return 0, nil, e
	}
	filter := ""
	if req.Filters != nil {
		filter = req.Filters.SampleTypeID
		if filter == "" {
			filter = req.Filters.SampleTypeID2
		}
	}
	return 200, a.operationsState(filter), nil
}

// ---- audit ----

func auditJSON(r store.AuditRow) map[string]any {
	id := itoa(r.ID)
	return map[string]any{
		"auditId": id, "audit_id": id, "actorId": r.ActorID, "actor_id": r.ActorID, "role": r.Role, "actorRole": r.Role,
		"action": r.Action, "entityType": r.EntityType, "entity_type": r.EntityType, "entityId": r.EntityID, "entity_id": r.EntityID,
		"success": r.Success, "occurredAt": fmtTime(r.OccurredAt), "occurred_at": fmtTime(r.OccurredAt), "details": r.Details,
	}
}

func itoa(v int64) string {
	if v == 0 {
		return "0"
	}
	neg := v < 0
	if neg {
		v = -v
	}
	var b [24]byte
	i := len(b)
	for v > 0 {
		i--
		b[i] = byte('0' + v%10)
		v /= 10
	}
	if neg {
		i--
		b[i] = '-'
	}
	return string(b[i:])
}

func (a *App) handleSearchAudit(c *reqCtx, body []byte) (int, any, *apiError) {
	type in struct {
		Query      string  `json:"query"`
		ActorID    string  `json:"actorId"`
		EntityType string  `json:"entityType"`
		EntityID   string  `json:"entityId"`
		Action     string  `json:"action"`
		Role       string  `json:"role"`
		Success    *bool   `json:"success"`
		FromTime   *string `json:"fromTime"`
		ToTime     *string `json:"toTime"`
		Limit      *int    `json:"limit"`
		Offset     *int    `json:"offset"`
		Order      string  `json:"order"`
	}
	req, e := decodeBody[in](body)
	if e != nil {
		return 0, nil, e
	}
	limit, offset := 500, 0
	if req.Limit != nil {
		if *req.Limit < 1 || *req.Limit > 5000 {
			return 0, nil, errf(400, "invalid_limit", "limit must be between 1 and 5000")
		}
		limit = *req.Limit
	}
	if req.Offset != nil {
		if *req.Offset < 0 {
			return 0, nil, errf(400, "invalid_offset", "offset must not be negative")
		}
		offset = *req.Offset
	}
	order := "newest_first"
	if req.Order != "" {
		if req.Order != "newest_first" && req.Order != "oldest_first" {
			return 0, nil, errf(400, "invalid_order", "order must be newest_first or oldest_first")
		}
		order = req.Order
	}
	from, e := optTime(req.FromTime)
	if e != nil {
		return 0, nil, e
	}
	to, e := optTime(req.ToTime)
	if e != nil {
		return 0, nil, e
	}
	f := store.AuditFilter{Query: strings.TrimSpace(req.Query), ActorID: req.ActorID, EntityType: req.EntityType, EntityID: req.EntityID, Action: req.Action,
		Role: req.Role, Success: req.Success, FromTime: from, ToTime: to, Limit: limit, Offset: offset, NewestFirst: order == "newest_first"}
	rows, total, err := a.store.SearchAudit(c.r.Context(), f)
	if err != nil {
		return 0, nil, errf(500, "internal_error", "audit search failed")
	}
	entries := []map[string]any{}
	for _, r := range rows {
		entries = append(entries, auditJSON(r))
	}
	out := map[string]any{"entries": entries, "total": total, "returned": len(entries), "offset": offset, "limit": limit, "order": order, "hasMore": offset+len(entries) < total}
	if offset+len(entries) < total {
		out["nextOffset"] = offset + len(entries)
	}
	c.tx.Audit("audit_searched", "audit", "search", "", true, map[string]any{"query": req.Query, "entityId": req.EntityID, "returned": len(entries), "total": total})
	return 200, out, nil
}
