export type Role =
  | "administrator"
  | "dispatcher"
  | "requester"
  | "collection_professional"
  | "delivery_partner"
  | "node_handler"
  | "laboratory_team";

export const ROLE_LABELS: Record<string, string> = {
  administrator: "Administrator",
  dispatcher: "Dispatcher",
  requester: "Requester",
  collection_professional: "Certified collection professional",
  delivery_partner: "Relay courier",
  node_handler: "Node handler",
  laboratory_team: "Laboratory intake operator",
};

export const ALL_ROLES: Role[] = [
  "administrator",
  "dispatcher",
  "requester",
  "collection_professional",
  "delivery_partner",
  "node_handler",
  "laboratory_team",
];

export interface Coordinate {
  latitude: number;
  longitude: number;
}

export interface Session {
  userId: string;
  username: string;
  fullName?: string;
  roles: string[];
  activeRole: string;
  roleSelectionRequired: boolean;
}

export interface TimelineEntry {
  eventId: number;
  action: string;
  actorId: string;
  role: string;
  entityType: string;
  entityId: string;
  success: boolean;
  occurredAt: string;
  details: Record<string, unknown>;
}

export interface Capacity {
  capacityUnits: number;
  reservedUnits: number;
  availableUnits: number;
  cooledCapacityUnits: number;
  cooledReservedUnits: number;
  cooledAvailableUnits: number;
}

export interface WorkItem {
  kind: "sample" | "journey" | "collection" | "transport" | "node" | "laboratory";
  status: string;
  history: TimelineEntry[];
  sampleId?: string;
  requestId?: string;
  journeyId?: string;
  assignmentId?: string;
  fromLocationId?: string;
  toLocationId?: string;
  sequence?: number;
  offerExpiresAt?: string;
  nodeId?: string;
  laboratoryId?: string;
  incomingFromLocationId?: string;
  outgoingToLocationId?: string;
  expectedSampleTypeId?: string;
  destinationCapacity?: Capacity;
  deliveryDeadline?: string;
  earliestCollectionAt?: string;
  latestCollectionAt?: string;
  currentHolderId?: string;
  locationStale?: boolean;
  locationRecordedAt?: string;
  sampleIds?: string[];
  routeMode?: string;
  planVersion?: number;
  estimatedDeliveryAt?: string;
  assignmentCount?: number;
  activeJourneyId?: string;
  serviceability?: string;
}

export interface RoleWork {
  pending: WorkItem[];
  inProgress: WorkItem[];
  completed: WorkItem[];
}

export interface Location {
  id?: string;
  locationId: string;
  name: string;
  coordinate: Coordinate;
  coverageKm: number;
  handlingMinutes: number;
  active: boolean;
  functions: Record<string, boolean>;
  capacity?: Capacity;
  acceptedSampleTypeIds?: string[];
}

export interface Connection {
  connectionId: string;
  fromLocationId: string;
  toLocationId: string;
  travelMinutes: number;
  costUnits: number;
  cooled: boolean;
  active: boolean;
  capacity?: Capacity;
}

export interface OpsSample {
  sampleId: string;
  status: string;
  requestId?: string;
  origin?: Coordinate;
  deliveryDeadline?: string;
  currentHolderId?: string;
  activeJourneyId?: string;
  latestLocation?: Coordinate;
  locationRecordedAt?: string;
  locationStale: boolean;
}

export interface OpsWorker {
  workerId: string;
  fullName?: string;
  roles?: string[];
  available: boolean;
  status: string;
  capacityUnits: number;
  assignmentCount: number;
  latestLocation?: Coordinate;
  locationRecordedAt?: string;
  locationStale: boolean;
}

export interface OperationsState {
  samples: OpsSample[];
  workers: OpsWorker[];
  locations: Location[];
  connections: Connection[];
  routes: Record<string, any>[];
  handoffs: Record<string, any>[];
  delays: Record<string, any>[];
  exceptions: Record<string, any>[];
  assignmentCountSpread: number;
  ineligibleAssignmentCount: number;
}

export interface SampleType {
  sampleTypeId: string;
  name: string;
  qualifiedCollectorRequired: boolean;
  requiredQualification: string;
  containerType: string;
  temperatureMinC: number;
  temperatureMaxC: number;
  incompatibleSampleTypes: string[];
  requiresCooledRoute: boolean;
  batchingAllowed: boolean;
}

export interface JourneyLeg {
  assignmentId: string;
  sequence: number;
  status: string;
  fromLocationId?: string;
  toLocationId?: string;
  workerId?: string;
  sampleId?: string;
}

export interface JourneyStop {
  stopId: string;
  locationId: string;
  stopType: string;
  sequence: number;
  estimatedAt: string;
  completedAt?: string;
  coordinate?: Coordinate;
}

export interface JourneyPlan {
  journeyId: string;
  parentJourneyId?: string;
  planVersion?: number;
  routeMode?: string;
  status?: string;
  estimatedDeliveryAt?: string;
  sampleIds?: string[];
  orderedStops?: JourneyStop[];
  legs: JourneyLeg[];
  assignmentIds?: string[];
  scope?: string;
  replanStatus?: string;
  valid?: boolean;
  collectionAssignmentId?: string;
  assignedWorkerIds?: string[];
}

export interface SampleLifecycle {
  sampleId: string;
  status: string;
  sealed: boolean;
  completedLegIds: string[];
  activeReplacementPlanIds: string[];
  timeline: TimelineEntry[];
  activeJourneyId?: string;
  currentHolderId?: string;
  receivedLaboratoryId?: string;
  exception?: Record<string, any>;
  pendingHandoffId?: string;
  pendingHandoff?: Record<string, any>;
  latestLocation?: Coordinate;
  locationRecordedAt?: string;
  locationStale: boolean;
}

export interface SampleState {
  sampleId: string;
  requestId: string;
  requesterId: string;
  origin: Coordinate;
  originType: string;
  requestedAt: string;
  deliveryDeadline: string;
  sampleTypeId: string;
  containerType: string;
  temperatureMinC: number;
  temperatureMaxC: number;
  serviceability: string;
  activeAssignmentIds: string[];
  state: { status: string };
  timeline: TimelineEntry[];
  activeJourneyId?: string;
  targetLaboratoryId?: string;
  latestLocation?: Coordinate;
  locationRecordedAt?: string;
  locationStale: boolean;
}

