import { createContext, useCallback, useContext, useEffect, useMemo, useRef, useState, type ReactNode } from "react";
import { api, getToken, onUnauthorized, setToken } from "./api";
import type { Connection, Location, SampleType, Session } from "./types";

interface RefUser {
  userId: string;
  username: string;
  fullName?: string;
  roles: string[];
  assignedLocationId?: string;
  active: boolean;
  available?: boolean;
  capacityUnits?: number;
  qualifications?: string[];
}

interface ReferenceData {
  sampleTypes: Record<string, SampleType>;
  locations: Record<string, Location>;
  connections: Record<string, Connection>;
  users: Record<string, RefUser>;
}

interface StoreValue {
  session: Session | null;
  loading: boolean;
  refreshSession: () => Promise<void>;
  signIn: (username: string, password: string) => Promise<Session>;
  signOut: () => void;
  selectRole: (role: string) => Promise<void>;
  ref: ReferenceData;
  tick: number;
  locationName: (id?: string) => string;
  sampleTypeName: (id?: string) => string;
  userName: (id?: string) => string;
}

const StoreContext = createContext<StoreValue | null>(null);

const emptyRef: ReferenceData = { sampleTypes: {}, locations: {}, connections: {}, users: {} };

function applyEvent(ref: ReferenceData, ev: { type: string; entityId: string; payload: any }): ReferenceData {
  const p = ev.payload ?? {};
  if (ev.type.startsWith("sample_type.")) {
    return { ...ref, sampleTypes: { ...ref.sampleTypes, [ev.entityId]: p as SampleType } };
  }
  if (ev.type.startsWith("location.")) {
    return { ...ref, locations: { ...ref.locations, [ev.entityId]: p as Location } };
  }
  if (ev.type.startsWith("connection.")) {
    return { ...ref, connections: { ...ref.connections, [ev.entityId]: p as Connection } };
  }
  if (ev.type.startsWith("user.")) {
    const existing = ref.users[ev.entityId] ?? {};
    return { ...ref, users: { ...ref.users, [ev.entityId]: { ...existing, ...(p as RefUser) } } };
  }
  return ref;
}

export function StoreProvider({ children }: { children: ReactNode }) {
  const [session, setSession] = useState<Session | null>(null);
  const [loading, setLoading] = useState(true);
  const [ref, setRef] = useState<ReferenceData>(emptyRef);
  const [tick, setTick] = useState(0);
  const cursorRef = useRef(0);

  const refreshSession = useCallback(async () => {
    if (!getToken()) {
      setSession(null);
      setLoading(false);
      return;
    }
    try {
      const boot = await api<{ user: Session }>("ui/bootstrap", undefined, "GET");
      setSession(boot.user);
    } catch {
      setSession(null);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    void refreshSession();
    return onUnauthorized(() => setSession(null));
  }, [refreshSession]);

  const signIn = useCallback(async (username: string, password: string) => {
    const r = await api<{ sessionToken: string; userId: string; roles: string[]; activeRole: string }>("authenticate-user", {
      username,
      password,
    });
    setToken(r.sessionToken);
    const boot = await api<{ user: Session }>("ui/bootstrap", undefined, "GET");
    setSession(boot.user);
    setRef(emptyRef);
    cursorRef.current = 0;
    return boot.user;
  }, []);

  const signOut = useCallback(() => {
    setToken(null);
    setSession(null);
    setRef(emptyRef);
    cursorRef.current = 0;
  }, []);

  const selectRole = useCallback(async (role: string) => {
    const r = await api<{ activeRole: string; roles: string[] }>("select-active-role", { role });
    setSession((s) => (s ? { ...s, activeRole: r.activeRole, roles: r.roles, roleSelectionRequired: false } : s));
  }, []);

  // Realtime feed: WebSocket with polling fallback. Reference data is folded from the stream.
  useEffect(() => {
    if (!session) return;
    let stopped = false;
    let ws: WebSocket | null = null;
    let pollTimer: number | undefined;

    const ingest = (events: any[]) => {
      if (!events.length) return;
      setRef((r) => events.reduce(applyEvent, r));
      cursorRef.current = Math.max(cursorRef.current, ...events.map((e) => Number(e.id) || 0));
      setTick((t) => t + 1);
    };

    const poll = async () => {
      try {
        const r = await api<{ events: any[]; cursor: number }>(`events?since=${cursorRef.current}`, undefined, "GET");
        ingest(r.events);
        if (r.cursor > cursorRef.current) cursorRef.current = r.cursor;
      } catch {
        /* ignore transient poll errors */
      }
    };

    const connect = () => {
      if (stopped) return;
      const token = getToken();
      if (!token) return;
      const proto = location.protocol === "https:" ? "wss" : "ws";
      try {
        ws = new WebSocket(`${proto}://${location.host}/api/events?since=${cursorRef.current}`, ["labsample", `bearer.${token}`]);
      } catch {
        ws = null;
        return;
      }
      ws.onmessage = (m) => {
        try {
          const data = JSON.parse(m.data);
          if (Array.isArray(data)) ingest(data);
          else if (data && data.id) ingest([data]);
          else if (data && Array.isArray(data.events)) ingest(data.events);
        } catch {
          /* ignore malformed frame */
        }
      };
      ws.onclose = () => {
        ws = null;
        if (!stopped) window.setTimeout(connect, 3000);
      };
    };

    void poll().then(connect);
    pollTimer = window.setInterval(poll, 5000);
    return () => {
      stopped = true;
      if (pollTimer) window.clearInterval(pollTimer);
      ws?.close();
    };
  }, [session?.userId]);

  const value = useMemo<StoreValue>(
    () => ({
      session,
      loading,
      refreshSession,
      signIn,
      signOut,
      selectRole,
      ref,
      tick,
      locationName: (id?: string) => (id ? ref.locations[id]?.name ?? id.slice(0, 8) : "—"),
      sampleTypeName: (id?: string) => (id ? ref.sampleTypes[id]?.name ?? id.slice(0, 8) : "—"),
      userName: (id?: string) => {
        if (!id) return "—";
        const u = ref.users[id];
        if (u) return u.fullName || u.username;
        if (session && session.userId === id) return session.fullName || session.username;
        return id.slice(0, 8);
      },
    }),
    [session, loading, refreshSession, signIn, signOut, selectRole, ref, tick],
  );
  return <StoreContext.Provider value={value}>{children}</StoreContext.Provider>;
}

export function useStore(): StoreValue {
  const v = useContext(StoreContext);
  if (!v) throw new Error("StoreProvider missing");
  return v;
}

