import { useState, type FormEvent, type ReactNode } from "react";
import { ApiError, fmt } from "../api";
import type { Capacity, TimelineEntry } from "../types";

export function errorText(e: unknown): string {
  if (e instanceof ApiError) return `${e.message} (${e.code})`;
  if (e instanceof Error) return e.message;
  return String(e);
}

export function ErrorBanner({ error }: { error: string | null }) {
  if (!error) return null;
  return (
    <div role="alert" className="error">
      {error}
    </div>
  );
}

export function Notice({ text }: { text: string | null }) {
  if (!text) return null;
  return (
    <div role="status" className="notice">
      {text}
    </div>
  );
}

export function Timeline({ entries, title = "Status timeline" }: { entries: TimelineEntry[]; title?: string }) {
  const sorted = [...entries].sort((a, b) => a.eventId - b.eventId);
  return (
    <section aria-label={title}>
      <h4>{title}</h4>
      {sorted.length === 0 ? (
        <p className="muted">No history yet.</p>
      ) : (
        <ol className="timeline">
          {sorted.map((e) => (
            <li key={e.eventId}>
              <span className="time">{fmt(e.occurredAt)}</span> <strong>{humanize(e.action)}</strong>
              {e.details && (e.details as any).status ? <span className="muted"> → {String((e.details as any).status)}</span> : null}
              <span className="muted"> by {e.role || "system"}</span>
              {!e.success ? <span className="tag warn">failed</span> : null}
            </li>
          ))}
        </ol>
      )}
    </section>
  );
}

export function humanize(s: string): string {
  return s.replace(/[_.]/g, " ");
}

export function CapacityTable({ capacity, caption }: { capacity?: Capacity; caption: string }) {
  if (!capacity) return <p className="muted">{caption}: capacity not configured (unconstrained).</p>;
  return (
    <table className="data" aria-label={caption}>
      <caption>{caption}</caption>
      <thead>
        <tr>
          <th>Pool</th>
          <th>Configured</th>
          <th>Reserved</th>
          <th>Available</th>
        </tr>
      </thead>
      <tbody>
        <tr>
          <th scope="row">Regular</th>
          <td>{capacity.capacityUnits}</td>
          <td>{capacity.reservedUnits}</td>
          <td>{capacity.availableUnits}</td>
        </tr>
        <tr>
          <th scope="row">Cooled</th>
          <td>{capacity.cooledCapacityUnits}</td>
          <td>{capacity.cooledReservedUnits}</td>
          <td>{capacity.cooledAvailableUnits}</td>
        </tr>
      </tbody>
    </table>
  );
}

export function StatusTag({ status }: { status: string }) {
  const cls =
    status === "exception" || status === "expired" || status === "cancelled"
      ? "tag danger"
      : status === "received" || status === "completed"
        ? "tag ok"
        : "tag";
  return <span className={cls}>{humanize(status)}</span>;
}

export function Freshness({ stale, recordedAt }: { stale: boolean; recordedAt?: string }) {
  return (
    <span className={stale ? "tag warn" : "tag ok"}>
      {stale ? "Location stale" : "Location fresh"}
      {recordedAt ? ` · last update ${fmt(recordedAt)}` : ""}
    </span>
  );
}

interface ActionFormProps {
  title: string;
  submitLabel: string;
  onSubmit: () => Promise<string | void>;
  children?: ReactNode;
  onDone?: () => void;
}

/** Small form wrapper that renders its own error / success messages. */
export function ActionForm({ title, submitLabel, onSubmit, children, onDone }: ActionFormProps) {
  const [error, setError] = useState<string | null>(null);
  const [ok, setOk] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);
  const submit = async (e: FormEvent) => {
    e.preventDefault();
    setError(null);
    setOk(null);
    setBusy(true);
    try {
      const msg = await onSubmit();
      setOk(msg || `${title}: done`);
      onDone?.();
    } catch (err) {
      setError(errorText(err));
    } finally {
      setBusy(false);
    }
  };
  return (
    <form onSubmit={submit} className="action-form" aria-label={title}>
      <h4>{title}</h4>
      {children}
      <button type="submit" disabled={busy}>
        {submitLabel}
      </button>
      <ErrorBanner error={error} />
      <Notice text={ok} />
    </form>
  );
}

export function Field({
  label,
  value,
  onChange,
  type = "text",
  required,
  step,
  placeholder,
}: {
  label: string;
  value: string;
  onChange: (v: string) => void;
  type?: string;
  required?: boolean;
  step?: string;
  placeholder?: string;
}) {
  return (
    <label className="field">
      <span>{label}</span>
      <input type={type} value={value} onChange={(e) => onChange(e.target.value)} required={required} step={step} placeholder={placeholder} />
    </label>
  );
}

export function SelectField({
  label,
  value,
  onChange,
  options,
  allowEmpty,
}: {
  label: string;
  value: string;
  onChange: (v: string) => void;
  options: { value: string; label: string }[];
  allowEmpty?: boolean;
}) {
  return (
    <label className="field">
      <span>{label}</span>
      <select value={value} onChange={(e) => onChange(e.target.value)}>
        {allowEmpty ? <option value="">—</option> : null}
        {options.map((o) => (
          <option key={o.value} value={o.value}>
            {o.label}
          </option>
        ))}
      </select>
    </label>
  );
}

export function CheckField({ label, checked, onChange }: { label: string; checked: boolean; onChange: (v: boolean) => void }) {
  return (
    <label className="field check">
      <input type="checkbox" checked={checked} onChange={(e) => onChange(e.target.checked)} />
      <span>{label}</span>
    </label>
  );
}

export function KeyValue({ items }: { items: [string, ReactNode][] }) {
  return (
    <dl className="kv">
      {items.map(([k, v]) => (
        <div key={k}>
          <dt>{k}</dt>
          <dd>{v}</dd>
        </div>
      ))}
    </dl>
  );
}

