import { useEffect, useState } from "react";
import { api, fmt } from "../api";
import { ErrorBanner, Freshness, KeyValue, StatusTag, Timeline, errorText, humanize } from "../components/common";
import { useStore } from "../store";
import type { JourneyPlan, SampleLifecycle, SampleState } from "../types";

export function SampleView({ sampleId, onClose }: { sampleId: string; onClose?: () => void }) {
  const { tick, locationName, userName, sampleTypeName, session } = useStore();
  const [state, setState] = useState<SampleState | null>(null);
  const [life, setLife] = useState<SampleLifecycle | null>(null);
  const [plan, setPlan] = useState<JourneyPlan | null>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    let cancelled = false;
    (async () => {
      try {
        const [s, l] = await Promise.all([
          api<SampleState>(`read-sample-state/${sampleId}`, undefined, "GET").catch(() => null),
          api<SampleLifecycle>("read-sample-lifecycle", { sampleId }),
        ]);
        if (cancelled) return;
        setState(s);
        setLife(l);
        setError(null);
        const jid = l.activeJourneyId || s?.activeJourneyId;
        if (jid) {
          const p = await api<JourneyPlan>("read-journey-plan", { journeyId: jid }).catch(() => null);
          if (!cancelled) setPlan(p);
        } else {
          setPlan(null);
        }
      } catch (e) {
        if (!cancelled) setError(errorText(e));
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [sampleId, tick]);

  if (error) return <ErrorBanner error={error} />;
  if (!life) return <p className="muted">Loading sample…</p>;

  const status = life.status;
  const stops = plan?.orderedStops ?? [];
  const completedStops = stops.filter((s) => s.completedAt).length;
  const legs = plan?.legs ?? [];
  const completedLegs = legs.filter((l) => l.status === "completed").length;
  const isException = status === "exception" || !!life.exception;
  const loc = life.latestLocation ?? state?.latestLocation;

  return (
    <article className="sample-view" aria-label={`Sample ${sampleId.slice(0, 8)}`}>
      <header className="row">
        <h3>
          Sample {sampleId.slice(0, 8)} <StatusTag status={status} />
          {isException ? <span className="tag danger">Exception</span> : null}
        </h3>
        {onClose ? (
          <button type="button" onClick={onClose}>
            Close
          </button>
        ) : null}
      </header>
      {isException ? (
        <div role="alert" className="error">
          Exception: {String(life.exception?.reason ?? "flagged")}
          {life.exception?.detail ? ` — ${String(life.exception.detail)}` : ""}
        </div>
      ) : null}
      <KeyValue
        items={[
          ["Status", humanize(status)],
          ["Sealed", life.sealed ? "yes" : "no"],
          ["Current custodian", life.currentHolderId ? userName(life.currentHolderId) : "none (not yet collected)"],
          ["Current location", loc ? `${loc.latitude.toFixed(5)}, ${loc.longitude.toFixed(5)}` : "unknown"],
          ["Last update", fmt(life.locationRecordedAt ?? state?.locationRecordedAt)],
          ["Freshness", <Freshness stale={life.locationStale} recordedAt={undefined} />],
          ["Route progress", plan ? `${completedLegs} of ${legs.length} legs · ${completedStops} of ${stops.length} stops` : "no active plan"],
          ...(state
            ? ([
                ["Sample type", sampleTypeName(state.sampleTypeId)],
                ["Origin", `${state.originType} · ${state.origin.latitude.toFixed(4)}, ${state.origin.longitude.toFixed(4)}`],
                ["Delivery deadline", fmt(state.deliveryDeadline)],
                ["Target laboratory", locationName(state.targetLaboratoryId)],
                ["Serviceability", state.serviceability],
              ] as [string, any][])
            : []),
          ["Received at laboratory", life.receivedLaboratoryId ? locationName(life.receivedLaboratoryId) : "—"],
          ["Pending handoff", life.pendingHandoff ? `${userName(String(life.pendingHandoff.senderId))} → ${userName(String(life.pendingHandoff.receiverId))}` : "none"],
        ]}
      />
      {plan ? (
        <section aria-label="Route">
          <h4>
            Route ({plan.routeMode ?? "—"}, plan version {plan.planVersion ?? "—"}, {humanize(plan.status ?? "")})
          </h4>
          <ol className="stops">
            {stops.map((s) => (
              <li key={s.stopId} className={s.completedAt ? "done" : ""}>
                {humanize(s.stopType)} at {locationName(s.locationId)} · est. {fmt(s.estimatedAt)}
                {s.completedAt ? ` · completed ${fmt(s.completedAt)}` : ""}
              </li>
            ))}
          </ol>
          <table className="data" aria-label="Legs">
            <thead>
              <tr>
                <th>#</th>
                <th>From</th>
                <th>To</th>
                <th>Worker</th>
                <th>Status</th>
              </tr>
            </thead>
            <tbody>
              {legs.map((l) => (
                <tr key={l.assignmentId}>
                  <td>{l.sequence}</td>
                  <td>{locationName(l.fromLocationId)}</td>
                  <td>{locationName(l.toLocationId)}</td>
                  <td>{l.workerId ? userName(l.workerId) : session?.activeRole === "requester" ? "assigned" : "unassigned"}</td>
                  <td>
                    <StatusTag status={l.status} />
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </section>
      ) : null}
      <Timeline entries={life.timeline} />
    </article>
  );
}

