import { useEffect, useState } from "react";
import { api, fmt, newKey, nowIso, toIso, localInput } from "../api";
import { ActionForm, CapacityTable, ErrorBanner, Field, SelectField, StatusTag, Timeline, errorText, humanize } from "../components/common";
import { useStore } from "../store";
import type { JourneyPlan, RoleWork, SampleLifecycle, WorkItem } from "../types";
import { SampleView } from "./SampleView";

const PROGRESS_STATUSES = ["at_pickup", "picked_up", "in_transit", "arrived", "delivered", "in_progress", "completed"];

export function WorkView() {
  const { session, tick } = useStore();
  const [work, setWork] = useState<RoleWork | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [openSample, setOpenSample] = useState<string | null>(null);
  const [reloadKey, setReloadKey] = useState(0);
  const reload = () => setReloadKey((k) => k + 1);

  useEffect(() => {
    let cancelled = false;
    api<RoleWork>("list-role-work", {})
      .then((w) => {
        if (!cancelled) {
          setWork(w);
          setError(null);
        }
      })
      .catch((e) => !cancelled && setError(errorText(e)));
    return () => {
      cancelled = true;
    };
  }, [tick, reloadKey, session?.activeRole]);

  if (error) return <ErrorBanner error={error} />;
  if (!work) return <p className="muted">Loading work…</p>;
  const current = [...work.pending, ...work.inProgress];

  return (
    <div className="work">
      <section aria-labelledby="current-work">
        <h2 id="current-work">Current work</h2>
        {current.length === 0 ? <p className="muted">No current work.</p> : null}
        <ul className="cards">
          {current.map((item) => (
            <li key={itemKey(item)}>
              <WorkCard item={item} onChanged={reload} onOpenSample={setOpenSample} />
            </li>
          ))}
        </ul>
      </section>
      <section aria-labelledby="past-work">
        <h2 id="past-work">Past work</h2>
        {work.completed.length === 0 ? <p className="muted">No completed work yet.</p> : null}
        <ul className="cards">
          {work.completed.map((item) => (
            <li key={itemKey(item)}>
              <WorkCard item={item} onChanged={reload} onOpenSample={setOpenSample} past />
            </li>
          ))}
        </ul>
      </section>
      {openSample ? (
        <section className="panel" aria-label="Sample details">
          <SampleView sampleId={openSample} onClose={() => setOpenSample(null)} />
        </section>
      ) : null}
    </div>
  );
}

function itemKey(item: WorkItem): string {
  return item.assignmentId ?? item.journeyId ?? item.sampleId ?? Math.random().toString();
}

function WorkCard({ item, onChanged, onOpenSample, past }: { item: WorkItem; onChanged: () => void; onOpenSample: (id: string) => void; past?: boolean }) {
  const { locationName, sampleTypeName } = useStore();
  const [showTimeline, setShowTimeline] = useState(false);
  const [showActions, setShowActions] = useState(!past);
  const title =
    item.kind === "sample"
      ? `Sample ${item.sampleId?.slice(0, 8)}`
      : item.kind === "journey"
        ? `Journey ${item.journeyId?.slice(0, 8)} (${item.routeMode}, v${item.planVersion})`
        : `${humanize(item.kind)} assignment ${item.assignmentId?.slice(0, 8)}`;
  return (
    <article className="card" aria-label={title}>
      <header className="row">
        <h3>
          {title} <StatusTag status={item.status} />
        </h3>
      </header>
      <dl className="kv compact">
        {item.sampleId ? (
          <div>
            <dt>Sample</dt>
            <dd>
              <button type="button" className="link" onClick={() => onOpenSample(item.sampleId!)}>
                {item.sampleId.slice(0, 8)}
              </button>
            </dd>
          </div>
        ) : null}
        {item.fromLocationId || item.toLocationId ? (
          <div>
            <dt>Leg</dt>
            <dd>
              {item.fromLocationId ? locationName(item.fromLocationId) : "origin"} → {locationName(item.toLocationId)}
              {item.sequence ? ` (#${item.sequence})` : ""}
            </dd>
          </div>
        ) : null}
        {item.nodeId ? (
          <div>
            <dt>Node</dt>
            <dd>
              {locationName(item.nodeId)} · in from {locationName(item.incomingFromLocationId)} · out to {locationName(item.outgoingToLocationId)}
            </dd>
          </div>
        ) : null}
        {item.laboratoryId ? (
          <div>
            <dt>Laboratory</dt>
            <dd>
              {locationName(item.laboratoryId)} · expecting {sampleTypeName(item.expectedSampleTypeId)}
            </dd>
          </div>
        ) : null}
        {item.deliveryDeadline ? (
          <div>
            <dt>Deadline</dt>
            <dd>{fmt(item.deliveryDeadline)}</dd>
          </div>
        ) : null}
        {item.offerExpiresAt && item.status === "offered" ? (
          <div>
            <dt>Offer expires</dt>
            <dd>{fmt(item.offerExpiresAt)}</dd>
          </div>
        ) : null}
        {item.kind === "journey" ? (
          <div>
            <dt>Samples</dt>
            <dd>{(item.sampleIds ?? []).map((s) => s.slice(0, 8)).join(", ")}</dd>
          </div>
        ) : null}
      </dl>
      {item.destinationCapacity ? <CapacityTable capacity={item.destinationCapacity} caption="Destination capacity" /> : null}
      <div className="row">
        <button type="button" onClick={() => setShowTimeline((v) => !v)}>
          {showTimeline ? "Hide timeline" : "Show timeline"}
        </button>
        {past || item.kind === "sample" || item.kind === "journey" ? null : (
          <button type="button" onClick={() => setShowActions((v) => !v)}>
            {showActions ? "Hide actions" : "Show actions"}
          </button>
        )}
      </div>
      {showTimeline ? <Timeline entries={item.history} /> : null}
      {showActions && !past && item.assignmentId ? <AssignmentActions item={item} onChanged={onChanged} /> : null}
    </article>
  );
}

function AssignmentActions({ item, onChanged }: { item: WorkItem; onChanged: () => void }) {
  const { session, tick, userName, locationName } = useStore();
  const asg = item.assignmentId!;
  const [life, setLife] = useState<SampleLifecycle | null>(null);
  const [plan, setPlan] = useState<JourneyPlan | null>(null);

  useEffect(() => {
    let cancelled = false;
    if (!item.sampleId) return;
    api<SampleLifecycle>("read-sample-lifecycle", { sampleId: item.sampleId })
      .then((l) => {
        if (cancelled) return;
        setLife(l);
        if (l.activeJourneyId) {
          api<JourneyPlan>("read-journey-plan", { journeyId: l.activeJourneyId })
            .then((p) => !cancelled && setPlan(p))
            .catch(() => setPlan(null));
        }
      })
      .catch(() => setLife(null));
    return () => {
      cancelled = true;
    };
  }, [item.sampleId, tick]);

  if (item.status === "offered") {
    return (
      <div className="actions">
        <OfferActions assignmentId={asg} onChanged={onChanged} />
      </div>
    );
  }
  if (!life) return null;
  const me = session!.userId;
  const iHold = life.currentHolderId === me;
  const pending = life.pendingHandoff;
  const myLeg = plan?.legs.find((l) => l.assignmentId === asg);
  const nextLeg = plan && myLeg ? plan.legs.find((l) => l.sampleId === myLeg.sampleId && l.sequence > myLeg.sequence) : undefined;
  const nextLegs = plan && myLeg ? plan.legs.filter((l) => l.sampleId === myLeg.sampleId && l.sequence > myLeg.sequence) : [];
  const canSeal = item.kind === "collection" && !life.sealed && life.status !== "received";

  return (
    <div className="actions">
      {pending ? (
        <HandoffConfirm handoff={pending} me={me} onChanged={onChanged} />
      ) : null}
      {canSeal ? <CollectAndSealForm sampleId={item.sampleId!} assignmentId={asg} onChanged={onChanged} /> : null}
      {item.kind === "transport" ? <ProgressForm assignmentId={asg} current={item.status} onChanged={onChanged} /> : null}
      {item.kind === "collection" || item.kind === "transport" ? <LocationForm assignmentId={asg} onChanged={onChanged} /> : null}
      {iHold && !pending && life.status !== "received" ? (
        <CheckpointForm sampleId={item.sampleId!} assignmentId={asg} locationId={item.nodeId ?? item.laboratoryId} onChanged={onChanged} />
      ) : null}
      {iHold && !pending && nextLeg && item.kind !== "laboratory" ? (
        <HandoffInitiateForm
          sampleId={item.sampleId!}
          fromAssignmentId={asg}
          options={nextLegs.map((l) => ({
            value: l.assignmentId,
            label: `Leg #${l.sequence} → ${locationName(l.toLocationId)} · ${l.workerId ? userName(l.workerId) : "unassigned"}`,
            workerId: l.workerId ?? "",
          }))}
          onChanged={onChanged}
        />
      ) : null}
      {item.kind === "laboratory" && iHold && !pending ? (
        <>
          <ReceiptForm sampleId={item.sampleId!} laboratoryId={item.laboratoryId!} onChanged={onChanged} />
          <LabExceptionForm sampleId={item.sampleId!} laboratoryId={item.laboratoryId!} onChanged={onChanged} />
        </>
      ) : null}
      {item.kind === "laboratory" && !iHold && !pending && life.status !== "received" ? (
        <LabExceptionForm sampleId={item.sampleId!} laboratoryId={item.laboratoryId!} onChanged={onChanged} />
      ) : null}
    </div>
  );
}

function OfferActions({ assignmentId, onChanged }: { assignmentId: string; onChanged: () => void }) {
  const [error, setError] = useState<string | null>(null);
  const [reason, setReason] = useState("");
  const act = async (op: "accept-assignment" | "decline-assignment") => {
    setError(null);
    try {
      const body: any = { assignmentId, idempotencyKey: newKey() };
      if (op === "decline-assignment") {
        body.declinedAt = nowIso();
        if (reason) body.reason = reason;
      }
      await api(op, body);
      onChanged();
    } catch (e) {
      setError(errorText(e));
    }
  };
  return (
    <div className="offer">
      <button type="button" onClick={() => act("accept-assignment")}>
        Accept assignment
      </button>
      <Field label="Decline reason" value={reason} onChange={setReason} />
      <button type="button" className="secondary" onClick={() => act("decline-assignment")}>
        Decline assignment
      </button>
      <ErrorBanner error={error} />
    </div>
  );
}

function LocationForm({ assignmentId, onChanged }: { assignmentId: string; onChanged: () => void }) {
  const [lat, setLat] = useState("");
  const [lon, setLon] = useState("");
  const [seq, setSeq] = useState(() => String(Math.floor(Date.now() / 1000) % 1_000_000_000));
  return (
    <ActionForm
      title="Record my location"
      submitLabel="Record location"
      onDone={onChanged}
      onSubmit={async () => {
        const r = await api("record-worker-location", {
          assignmentId,
          coordinate: { latitude: Number(lat), longitude: Number(lon) },
          sequence: Number(seq),
          recordedAt: nowIso(),
        });
        setSeq(String(Number(seq) + 1));
        return `Location recorded at ${fmt(r.recordedAt)} (sequence ${r.sequence})`;
      }}
    >
      <Field label="Latitude" value={lat} onChange={setLat} type="number" step="any" required />
      <Field label="Longitude" value={lon} onChange={setLon} type="number" step="any" required />
      <Field label="Sequence" value={seq} onChange={setSeq} type="number" required />
      <button
        type="button"
        className="secondary"
        onClick={() =>
          navigator.geolocation?.getCurrentPosition((p) => {
            setLat(String(p.coords.latitude));
            setLon(String(p.coords.longitude));
          })
        }
      >
        Use device position
      </button>
    </ActionForm>
  );
}

function CollectAndSealForm({ sampleId, assignmentId, onChanged }: { sampleId: string; assignmentId: string; onChanged: () => void }) {
  const [container, setContainer] = useState("");
  const [temp, setTemp] = useState("");
  const [at, setAt] = useState(localInput(0));
  return (
    <ActionForm
      title="Collect and seal sample"
      submitLabel="Record collected and sealed"
      onDone={onChanged}
      onSubmit={async () => {
        const r = await api("collect-and-seal-sample", {
          sampleId,
          assignmentId,
          collectedAt: toIso(at),
          containerType: container,
          observedTemperatureC: Number(temp),
          idempotencyKey: newKey(),
        });
        return `Sample sealed at ${fmt(r.sealedAt)}${r.handlingCompliant ? "" : " — handling non-compliant"}`;
      }}
    >
      <Field label="Collected at" value={at} onChange={setAt} type="datetime-local" required />
      <Field label="Container type" value={container} onChange={setContainer} required />
      <Field label="Observed temperature (°C)" value={temp} onChange={setTemp} type="number" step="any" required />
    </ActionForm>
  );
}

function ProgressForm({ assignmentId, current, onChanged }: { assignmentId: string; current: string; onChanged: () => void }) {
  const idx = PROGRESS_STATUSES.indexOf(current);
  const next = PROGRESS_STATUSES[Math.min(idx + 1, PROGRESS_STATUSES.length - 1)] ?? "at_pickup";
  const [status, setStatus] = useState(idx < 0 ? "at_pickup" : next);
  return (
    <ActionForm
      title="Update progress"
      submitLabel="Update progress"
      onDone={onChanged}
      onSubmit={async () => {
        const r = await api("update-assignment-progress", { assignmentId, status, occurredAt: nowIso(), idempotencyKey: newKey() });
        return `Progress updated to ${humanize(r.status)}`;
      }}
    >
      <SelectField label="Progress status" value={status} onChange={setStatus} options={PROGRESS_STATUSES.map((s) => ({ value: s, label: humanize(s) }))} />
    </ActionForm>
  );
}

function CheckpointForm({ sampleId, assignmentId, locationId, onChanged }: { sampleId: string; assignmentId: string; locationId?: string; onChanged: () => void }) {
  const [container, setContainer] = useState("");
  const [temp, setTemp] = useState("");
  return (
    <ActionForm
      title="Record handling checkpoint"
      submitLabel="Record checkpoint"
      onDone={onChanged}
      onSubmit={async () => {
        const body: any = { sampleId, assignmentId, containerType: container, observedTemperatureC: Number(temp), recordedAt: nowIso(), idempotencyKey: newKey() };
        if (locationId) body.locationId = locationId;
        const r = await api("record-handling-checkpoint", body);
        return r.compliant ? "Checkpoint compliant" : `Checkpoint NON-compliant — sample marked ${r.sampleStatus}`;
      }}
    >
      <Field label="Observed container type" value={container} onChange={setContainer} required />
      <Field label="Observed temperature (°C)" value={temp} onChange={setTemp} type="number" step="any" required />
    </ActionForm>
  );
}

function HandoffInitiateForm({
  sampleId,
  fromAssignmentId,
  options,
  onChanged,
}: {
  sampleId: string;
  fromAssignmentId: string;
  options: { value: string; label: string; workerId: string }[];
  onChanged: () => void;
}) {
  const [to, setTo] = useState(options[0]?.value ?? "");
  const chosen = options.find((o) => o.value === to);
  return (
    <ActionForm
      title="Hand off sample"
      submitLabel="Initiate handoff"
      onDone={onChanged}
      onSubmit={async () => {
        if (!chosen?.workerId) throw new Error("the next leg has no assigned worker yet");
        const r = await api("initiate-handoff", {
          sampleId,
          fromAssignmentId,
          toAssignmentId: to,
          receiverId: chosen.workerId,
          initiatedAt: nowIso(),
          idempotencyKey: newKey(),
        });
        return `Handoff ${String(r.handoffId).slice(0, 8)} initiated — awaiting both confirmations`;
      }}
    >
      <SelectField label="Hand off to" value={to} onChange={setTo} options={options} />
    </ActionForm>
  );
}

function HandoffConfirm({ handoff, me, onChanged }: { handoff: Record<string, any>; me: string; onChanged: () => void }) {
  const { userName } = useStore();
  const side = handoff.senderId === me ? "sender" : handoff.receiverId === me ? "receiver" : null;
  const already = side === "sender" ? handoff.senderConfirmed : side === "receiver" ? handoff.receiverConfirmed : true;
  return (
    <div className="handoff">
      <h4>Pending handoff</h4>
      <p>
        {userName(handoff.senderId)} → {userName(handoff.receiverId)} · sender {handoff.senderConfirmed ? "confirmed" : "pending"} · receiver{" "}
        {handoff.receiverConfirmed ? "confirmed" : "pending"}
      </p>
      {side && !already ? (
        <ActionForm
          title={`Confirm handoff as ${side}`}
          submitLabel={side === "sender" ? "Confirm handoff (sender)" : "Confirm handoff (receiver)"}
          onDone={onChanged}
          onSubmit={async () => {
            const r = await api("confirm-handoff", { handoffId: handoff.handoffId, confirmationSide: side, confirmedAt: nowIso(), idempotencyKey: newKey() });
            return r.status === "confirmed" ? `Custody transferred to ${userName(r.currentHolderId)}` : "Confirmation recorded — waiting for the other party";
          }}
        />
      ) : null}
    </div>
  );
}

function ReceiptForm({ sampleId, laboratoryId, onChanged }: { sampleId: string; laboratoryId: string; onChanged: () => void }) {
  return (
    <ActionForm
      title="Confirm laboratory receipt"
      submitLabel="Confirm sample received"
      onDone={onChanged}
      onSubmit={async () => {
        const r = await api("confirm-laboratory-receipt", { sampleId, laboratoryId, receivedAt: nowIso(), idempotencyKey: newKey() });
        return `Sample received at ${fmt(r.receivedAt)}`;
      }}
    />
  );
}

function LabExceptionForm({ sampleId, laboratoryId, onChanged }: { sampleId: string; laboratoryId: string; onChanged: () => void }) {
  const [reason, setReason] = useState("");
  return (
    <ActionForm
      title="Record laboratory exception"
      submitLabel="Record exception"
      onDone={onChanged}
      onSubmit={async () => {
        const r = await api("record-laboratory-exception", { sampleId, laboratoryId, reason, observedAt: nowIso(), idempotencyKey: newKey() });
        return `Exception ${String(r.exceptionId).slice(0, 8)} recorded`;
      }}
    >
      <Field label="Exception reason" value={reason} onChange={setReason} required />
    </ActionForm>
  );
}

