import { useEffect, useMemo, useState, type FormEvent } from "react";
import { api, fmt, localInput, newKey, toIso } from "../api";
import { ErrorBanner, Field, Notice, SelectField, StatusTag, errorText, humanize } from "../components/common";
import { useStore } from "../store";
import type { RoleWork, WorkItem } from "../types";
import { SampleView } from "./SampleView";

interface FormState {
  originType: string;
  originNodeId: string;
  latitude: string;
  longitude: string;
  sampleTypeId: string;
  earliest: string;
  latest: string;
  deadline: string;
  containerType: string;
  tempMin: string;
  tempMax: string;
}

export function RequesterView({ presealed }: { presealed?: boolean }) {
  const { ref, tick, locationName } = useStore();
  const sampleTypes = useMemo(() => Object.values(ref.sampleTypes).sort((a, b) => a.name.localeCompare(b.name)), [ref.sampleTypes]);
  const nodes = useMemo(() => Object.values(ref.locations).filter((l) => l.active).sort((a, b) => a.name.localeCompare(b.name)), [ref.locations]);
  const [form, setForm] = useState<FormState>({
    originType: presealed ? "node" : "home",
    originNodeId: "",
    latitude: "12.9716",
    longitude: "77.5946",
    sampleTypeId: "",
    earliest: localInput(0),
    latest: localInput(120),
    deadline: localInput(360),
    containerType: "",
    tempMin: "",
    tempMax: "",
  });
  const set = (k: keyof FormState) => (v: string) => setForm((f) => ({ ...f, [k]: v }));
  const [error, setError] = useState<string | null>(null);
  const [result, setResult] = useState<string | null>(null);
  const [serviceability, setServiceability] = useState<Record<string, any> | null>(null);
  const [work, setWork] = useState<RoleWork | null>(null);
  const [openSample, setOpenSample] = useState<string | null>(null);
  const [reloadKey, setReloadKey] = useState(0);

  useEffect(() => {
    if (!form.sampleTypeId && sampleTypes.length) {
      const t = sampleTypes[0];
      setForm((f) => ({ ...f, sampleTypeId: t.sampleTypeId, containerType: t.containerType, tempMin: String(t.temperatureMinC), tempMax: String(t.temperatureMaxC) }));
    }
  }, [sampleTypes, form.sampleTypeId]);

  useEffect(() => {
    if (presealed) return;
    api<RoleWork>("list-role-work", {})
      .then(setWork)
      .catch((e) => setError(errorText(e)));
  }, [tick, reloadKey, presealed]);

  useEffect(() => {
    if (form.originType === "node" && form.originNodeId) {
      const n = ref.locations[form.originNodeId];
      if (n) setForm((f) => ({ ...f, latitude: String(n.coordinate.latitude), longitude: String(n.coordinate.longitude) }));
    }
  }, [form.originType, form.originNodeId, ref.locations]);

  const onTypeChange = (id: string) => {
    const t = ref.sampleTypes[id];
    setForm((f) => ({
      ...f,
      sampleTypeId: id,
      containerType: t ? t.containerType : f.containerType,
      tempMin: t ? String(t.temperatureMinC) : f.tempMin,
      tempMax: t ? String(t.temperatureMaxC) : f.tempMax,
    }));
  };

  const basePayload = () => {
    const body: Record<string, unknown> = {
      origin: { latitude: Number(form.latitude), longitude: Number(form.longitude) },
      originType: form.originType,
      sampleTypeId: form.sampleTypeId,
      requestedAt: toIso(localInput(0)),
      deliveryDeadline: toIso(form.deadline),
      earliestCollectionAt: toIso(form.earliest),
      latestCollectionAt: toIso(form.latest),
    };
    if (form.originType === "node" && form.originNodeId) body.originNodeId = form.originNodeId;
    return body;
  };

  const validate = (): string | null => {
    if (!form.sampleTypeId) return "Choose a sample type.";
    if (form.latitude === "" || form.longitude === "" || Number.isNaN(Number(form.latitude)) || Number.isNaN(Number(form.longitude)))
      return "Enter a valid origin latitude and longitude.";
    if (!form.deadline) return "Enter a delivery deadline.";
    if (new Date(form.deadline).getTime() <= Date.now()) return "The delivery deadline must be in the future.";
    if (form.earliest && form.latest && new Date(form.latest).getTime() < new Date(form.earliest).getTime())
      return "The collection window end must not be before its start.";
    return null;
  };

  const check = async (e: FormEvent) => {
    e.preventDefault();
    setError(null);
    setResult(null);
    const v = validate();
    if (v) {
      setError(v);
      return;
    }
    try {
      const r = await api("check-serviceability", basePayload());
      setServiceability(r);
    } catch (err) {
      setError(errorText(err));
    }
  };

  const create = async () => {
    setError(null);
    setResult(null);
    const v = validate();
    if (v) {
      setError(v);
      return;
    }
    if (!form.containerType) {
      setError("Enter the container type.");
      return;
    }
    try {
      const body = {
        ...basePayload(),
        containerType: form.containerType,
        temperatureMinC: Number(form.tempMin),
        temperatureMaxC: Number(form.tempMax),
        idempotencyKey: newKey(),
      };
      const r = await api(presealed ? "ingest-presealed-sample" : "create-collection-request", body);
      setResult(
        `${presealed ? "Pre-sealed sample registered" : "Request created"}: sample ${String(r.sampleId).slice(0, 8)} is ${r.serviceability}` +
          (r.serviceabilityReason && r.serviceability !== "serviceable" ? ` (${humanize(r.serviceabilityReason)})` : "") +
          (r.targetLaboratoryId ? ` · target laboratory ${locationName(r.targetLaboratoryId)}` : ""),
      );
      setServiceability(null);
      setReloadKey((k) => k + 1);
      setOpenSample(r.sampleId);
    } catch (err) {
      setError(errorText(err));
    }
  };

  const originOptions = presealed ? ["clinic", "node"] : ["home", "clinic", "node"];
  const title = presealed ? "Register pre-sealed sample" : "New collection request";

  return (
    <div className="requester">
      <section className="panel" aria-labelledby="request-form-title">
        <h2 id="request-form-title">{title}</h2>
        <form onSubmit={check} aria-label={title}>
          <div className="grid">
            <SelectField label="Origin type" value={form.originType} onChange={set("originType")} options={originOptions.map((o) => ({ value: o, label: o }))} />
            {form.originType === "node" ? (
              <SelectField
                label="Origin node"
                value={form.originNodeId}
                onChange={set("originNodeId")}
                allowEmpty
                options={nodes.map((n) => ({ value: n.locationId, label: n.name }))}
              />
            ) : null}
            <Field label="Origin latitude" value={form.latitude} onChange={set("latitude")} type="number" step="any" />
            <Field label="Origin longitude" value={form.longitude} onChange={set("longitude")} type="number" step="any" />
            <SelectField
              label="Sample type"
              value={form.sampleTypeId}
              onChange={onTypeChange}
              allowEmpty
              options={sampleTypes.map((t) => ({ value: t.sampleTypeId, label: t.name }))}
            />
            <Field label="Collection window start" value={form.earliest} onChange={set("earliest")} type="datetime-local" />
            <Field label="Collection window end" value={form.latest} onChange={set("latest")} type="datetime-local" />
            <Field label="Delivery deadline" value={form.deadline} onChange={set("deadline")} type="datetime-local" />
            <Field label="Container type" value={form.containerType} onChange={set("containerType")} />
            <Field label="Temperature min (°C)" value={form.tempMin} onChange={set("tempMin")} type="number" step="any" />
            <Field label="Temperature max (°C)" value={form.tempMax} onChange={set("tempMax")} type="number" step="any" />
          </div>
          <div className="row">
            <button type="submit">Check serviceability</button>
            <button type="button" onClick={create}>
              {presealed ? "Register sample" : "Create request"}
            </button>
          </div>
          <ErrorBanner error={error} />
          {serviceability ? (
            <div role="status" className={serviceability.serviceable ? "notice" : "warning"}>
              Serviceability check (dry run, version {serviceability.serviceabilityVersion}): {serviceability.serviceable ? "serviceable" : "not serviceable"} —{" "}
              {humanize(serviceability.reason)}
              {serviceability.targetLaboratoryId ? ` · laboratory ${locationName(serviceability.targetLaboratoryId)}` : ""}
              {serviceability.estimatedArrivalAt ? ` · estimated arrival ${fmt(serviceability.estimatedArrivalAt)}` : ""}
            </div>
          ) : null}
          <Notice text={result} />
        </form>
      </section>
      {!presealed ? (
        <section className="panel" aria-labelledby="my-samples">
          <h2 id="my-samples">My samples</h2>
          {work ? (
            <>
              <h3>Current</h3>
              <SampleList items={[...work.pending, ...work.inProgress]} onOpen={setOpenSample} />
              <h3>Past</h3>
              <SampleList items={work.completed} onOpen={setOpenSample} />
            </>
          ) : (
            <p className="muted">Loading…</p>
          )}
        </section>
      ) : null}
      {openSample ? (
        <section className="panel" aria-label="Sample details">
          <SampleView sampleId={openSample} onClose={() => setOpenSample(null)} />
        </section>
      ) : null}
    </div>
  );
}

function SampleList({ items, onOpen }: { items: WorkItem[]; onOpen: (id: string) => void }) {
  if (items.length === 0) return <p className="muted">None.</p>;
  return (
    <table className="data" aria-label="Samples">
      <thead>
        <tr>
          <th>Sample</th>
          <th>Status</th>
          <th>Deadline</th>
          <th>Location</th>
          <th></th>
        </tr>
      </thead>
      <tbody>
        {items.map((s) => (
          <tr key={s.sampleId}>
            <td>{s.sampleId?.slice(0, 8)}</td>
            <td>
              <StatusTag status={s.status} />
            </td>
            <td>{fmt(s.deliveryDeadline)}</td>
            <td>
              <span className={s.locationStale ? "tag warn" : "tag ok"}>{s.locationStale ? "Location stale" : "Location fresh"}</span>
            </td>
            <td>
              <button type="button" onClick={() => onOpen(s.sampleId!)}>
                View sample
              </button>
            </td>
          </tr>
        ))}
      </tbody>
    </table>
  );
}

