import { useEffect, useState } from "react";
import { api } from "../api";
import { ActionForm, CapacityTable, Field, KeyValue } from "../components/common";
import { useStore } from "../store";
import type { RoleWork } from "../types";

/** Capacity for the node or laboratory the current worker is assigned to. */
export function CapacityView() {
  const { session, ref, tick, sampleTypeName } = useStore();
  const me = session ? ref.users[session.userId] : undefined;
  const [fallbackLoc, setFallbackLoc] = useState<string | undefined>();
  const locId = me?.assignedLocationId || fallbackLoc;
  const loc = locId ? ref.locations[locId] : undefined;
  const [regular, setRegular] = useState("");
  const [cooled, setCooled] = useState("");

  useEffect(() => {
    if (me?.assignedLocationId) return;
    api<RoleWork>("list-role-work", {})
      .then((w) => {
        const item = [...w.pending, ...w.inProgress, ...w.completed].find((i) => i.nodeId || i.laboratoryId);
        if (item) setFallbackLoc(item.nodeId ?? item.laboratoryId);
      })
      .catch(() => undefined);
  }, [me?.assignedLocationId, tick]);

  useEffect(() => {
    if (loc?.capacity) {
      setRegular(String(loc.capacity.capacityUnits));
      setCooled(String(loc.capacity.cooledCapacityUnits));
    }
  }, [loc?.capacity?.capacityUnits, loc?.capacity?.cooledCapacityUnits]);

  if (!locId) return <p className="muted">You are not assigned to a node or laboratory.</p>;
  const fns = loc ? Object.entries(loc.functions).filter(([, v]) => v).map(([k]) => k.replace("_", " ")) : [];

  return (
    <section className="panel" aria-labelledby="capacity-title">
      <h2 id="capacity-title">Capacity at {loc?.name ?? locId.slice(0, 8)}</h2>
      {loc ? (
        <KeyValue
          items={[
            ["Functions", fns.join(", ") || "—"],
            ["Active", loc.active ? "yes" : "no"],
            ["Handling time", `${loc.handlingMinutes} min`],
            ["Accepted sample types", (loc.acceptedSampleTypeIds ?? []).map(sampleTypeName).join(", ") || "—"],
          ]}
        />
      ) : null}
      <CapacityTable capacity={loc?.capacity} caption="My location capacity" />
      <ActionForm
        title="Configure capacity"
        submitLabel="Save capacity"
        onSubmit={async () => {
          const r = await api("configure-capacity", { resourceId: locId, capacityUnits: Number(regular), cooledCapacityUnits: Number(cooled || 0) });
          return `Capacity set to ${r.capacityUnits} regular / ${r.cooledCapacityUnits} cooled units`;
        }}
      >
        <Field label="Regular capacity units" value={regular} onChange={setRegular} type="number" required />
        <Field label="Cooled capacity units" value={cooled} onChange={setCooled} type="number" />
      </ActionForm>
    </section>
  );
}

