import maplibregl from "maplibre-gl";
import "maplibre-gl/dist/maplibre-gl.css";
import { Protocol } from "pmtiles";
import { useEffect, useRef } from "react";
import type { Connection, Location, OpsSample, OpsWorker } from "../types";

let protocolRegistered = false;
function ensureProtocol() {
  if (protocolRegistered) return;
  const protocol = new Protocol();
  maplibregl.addProtocol("pmtiles", protocol.tile);
  protocolRegistered = true;
}

interface Props {
  locations: Location[];
  connections: Connection[];
  workers: OpsWorker[];
  samples: OpsSample[];
  routes: Record<string, any>[];
}

function featureCollection(features: GeoJSON.Feature[]): GeoJSON.FeatureCollection {
  return { type: "FeatureCollection", features };
}

/** Live map rendered from the local PMTiles basemap only (no remote tile requests). */
export function MapView({ locations, connections, workers, samples, routes }: Props) {
  const container = useRef<HTMLDivElement>(null);
  const mapRef = useRef<maplibregl.Map | null>(null);
  const ready = useRef(false);

  useEffect(() => {
    if (!container.current) return;
    ensureProtocol();
    const map = new maplibregl.Map({
      container: container.current,
      style: "/map-assets/style.json",
      center: [77.5946, 12.9716],
      zoom: 10,
      attributionControl: { compact: false },
    });
    map.addControl(new maplibregl.NavigationControl(), "top-right");
    map.on("load", () => {
      map.addSource("connections", { type: "geojson", data: featureCollection([]) });
      map.addLayer({
        id: "connections",
        type: "line",
        source: "connections",
        paint: { "line-color": ["case", ["get", "active"], "#1f6feb", "#b0b0b0"], "line-width": 2, "line-dasharray": [2, 1] },
      });
      map.addSource("routes", { type: "geojson", data: featureCollection([]) });
      map.addLayer({ id: "routes", type: "line", source: "routes", paint: { "line-color": "#d97706", "line-width": 3 } });
      map.addSource("coverage", { type: "geojson", data: featureCollection([]) });
      map.addLayer({ id: "coverage", type: "fill", source: "coverage", paint: { "fill-color": "#16a34a", "fill-opacity": 0.08 } });
      map.addSource("locations", { type: "geojson", data: featureCollection([]) });
      map.addLayer({
        id: "locations",
        type: "circle",
        source: "locations",
        paint: {
          "circle-radius": 7,
          "circle-color": ["case", ["get", "laboratory"], "#7c3aed", ["get", "hub"], "#2563eb", "#16a34a"],
          "circle-opacity": ["case", ["get", "active"], 1, 0.35],
          "circle-stroke-width": 1.5,
          "circle-stroke-color": "#ffffff",
        },
      });
      map.addLayer({
        id: "location-labels",
        type: "symbol",
        source: "locations",
        layout: { "text-field": ["get", "name"], "text-font": ["Noto Sans Regular"], "text-size": 11, "text-offset": [0, 1.2], "text-anchor": "top" },
        paint: { "text-halo-color": "#fff", "text-halo-width": 1 },
      });
      map.addSource("workers", { type: "geojson", data: featureCollection([]) });
      map.addLayer({
        id: "workers",
        type: "circle",
        source: "workers",
        paint: { "circle-radius": 6, "circle-color": ["case", ["get", "stale"], "#9ca3af", "#dc2626"], "circle-stroke-width": 1, "circle-stroke-color": "#fff" },
      });
      map.addLayer({
        id: "worker-labels",
        type: "symbol",
        source: "workers",
        layout: { "text-field": ["get", "name"], "text-font": ["Noto Sans Regular"], "text-size": 10, "text-offset": [0, -1.2] },
        paint: { "text-color": "#7f1d1d", "text-halo-color": "#fff", "text-halo-width": 1 },
      });
      map.addSource("samples", { type: "geojson", data: featureCollection([]) });
      map.addLayer({
        id: "samples",
        type: "circle",
        source: "samples",
        paint: { "circle-radius": 4, "circle-color": "#f59e0b", "circle-stroke-width": 1, "circle-stroke-color": "#78350f" },
      });
      for (const layer of ["locations", "workers", "samples"]) {
        map.on("click", layer, (e) => {
          const f = e.features?.[0];
          if (!f) return;
