import { useState, type FormEvent } from "react";
import { api, fmt, toIso } from "../api";
import { ErrorBanner, Field, SelectField, errorText } from "../components/common";
import { useStore } from "../store";

interface AuditEntry {
  auditId: string;
  actorId: string;
  actorRole: string;
  action: string;
  entityType: string;
  entityId: string;
  success: boolean;
  occurredAt: string;
  details: Record<string, unknown>;
}

interface Result {
  entries: AuditEntry[];
  total: number;
  returned: number;
  offset: number;
  limit: number;
  hasMore: boolean;
  nextOffset?: number;
}

export function AuditView() {
  const { userName } = useStore();
  const [query, setQuery] = useState("");
  const [entityId, setEntityId] = useState("");
  const [action, setAction] = useState("");
  const [role, setRole] = useState("");
  const [success, setSuccess] = useState("");
  const [from, setFrom] = useState("");
  const [to, setTo] = useState("");
  const [order, setOrder] = useState("newest_first");
  const [result, setResult] = useState<Result | null>(null);
  const [error, setError] = useState<string | null>(null);

  const search = async (offset = 0) => {
    setError(null);
    const body: Record<string, unknown> = { limit: 100, offset, order };
    if (query) body.query = query;
    if (entityId) body.entityId = entityId;
    if (action) body.action = action;
    if (role) body.role = role;
    if (success) body.success = success === "true";
    if (from) body.fromTime = toIso(from);
    if (to) body.toTime = toIso(to);
    try {
      setResult(await api<Result>("search-audit-trail", body));
    } catch (e) {
      setError(errorText(e));
    }
  };

  const submit = (e: FormEvent) => {
    e.preventDefault();
    void search(0);
  };

  return (
    <div className="audit">
      <section className="panel" aria-labelledby="audit-title">
        <h2 id="audit-title">Audit history</h2>
        <form onSubmit={submit} aria-label="Search audit history">
          <div className="grid">
            <Field label="Search text" value={query} onChange={setQuery} placeholder="request id, sample id, action…" />
            <Field label="Entity id" value={entityId} onChange={setEntityId} />
            <Field label="Action" value={action} onChange={setAction} placeholder="e.g. sign_in, custody_transferred" />
            <Field label="Role" value={role} onChange={setRole} />
            <SelectField
              label="Outcome"
              value={success}
              onChange={setSuccess}
              options={[
                { value: "", label: "any" },
                { value: "true", label: "success" },
                { value: "false", label: "failure" },
              ]}
            />
            <Field label="From time" value={from} onChange={setFrom} type="datetime-local" />
            <Field label="To time" value={to} onChange={setTo} type="datetime-local" />
            <SelectField
              label="Order"
              value={order}
              onChange={setOrder}
              options={[
                { value: "newest_first", label: "newest first" },
                { value: "oldest_first", label: "oldest first" },
              ]}
            />
          </div>
          <button type="submit">Search audit</button>
        </form>
        <ErrorBanner error={error} />
      </section>
      {result ? (
        <section className="panel" aria-labelledby="audit-results">
          <h2 id="audit-results">
            Audit results ({result.returned} of {result.total})
          </h2>
          <table className="data">
            <thead>
              <tr>
                <th>Time</th>
                <th>User</th>
                <th>Role</th>
                <th>Action</th>
                <th>Entity</th>
                <th>Outcome</th>
                <th>Changes</th>
              </tr>
            </thead>
            <tbody>
              {result.entries.map((e) => (
                <tr key={e.auditId}>
                  <td>{fmt(e.occurredAt)}</td>
                  <td>{e.actorId ? userName(e.actorId) : "system"}</td>
                  <td>{e.actorRole || "—"}</td>
                  <td>{e.action}</td>
                  <td>
                    {e.entityType} {e.entityId ? e.entityId.slice(0, 8) : ""}
                  </td>
                  <td>{e.success ? <span className="tag ok">success</span> : <span className="tag danger">failure</span>}</td>
                  <td>
                    <code className="details">{JSON.stringify(e.details)}</code>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
          <div className="row">
            {result.offset > 0 ? (
              <button type="button" onClick={() => search(Math.max(0, result.offset - result.limit))}>
                Previous page
              </button>
            ) : null}
            {result.hasMore ? (
              <button type="button" onClick={() => search(result.nextOffset ?? result.offset + result.limit)}>
                Next page
              </button>
            ) : null}
          </div>
        </section>
      ) : null}
    </div>
  );
}

