import { useEffect, useMemo, useState } from "react";
import { api, fmt, newKey, nowIso } from "../api";
import { ActionForm, ErrorBanner, Field, SelectField, StatusTag, errorText, humanize } from "../components/common";
import { useStore } from "../store";
import type { JourneyPlan, OperationsState } from "../types";

const CHANGE_TYPES = ["add_stop", "remove_stop", "reorder_stops", "replace_worker", "reassign_worker", "merge_samples", "split_samples", "split_batch", "cancel_work", "reroute", "replace_route"];
const RESOURCE_TYPES = ["location", "node", "laboratory", "connection", "route", "worker", "capacity"];

export function ReplanView() {
  const { tick, locationName, userName, ref } = useStore();
  const [ops, setOps] = useState<OperationsState | null>(null);
  const [selected, setSelected] = useState("");
  const [plan, setPlan] = useState<JourneyPlan | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [reloadKey, setReloadKey] = useState(0);
  const reload = () => setReloadKey((k) => k + 1);

  useEffect(() => {
    api<OperationsState>("read-operations-state", {})
      .then((o) => {
        setOps(o);
        setError(null);
      })
      .catch((e) => setError(errorText(e)));
  }, [tick, reloadKey]);

  useEffect(() => {
    if (!selected) {
      setPlan(null);
      return;
    }
    api<JourneyPlan>("read-journey-plan", { journeyId: selected })
      .then(setPlan)
      .catch((e) => setError(errorText(e)));
  }, [selected, tick, reloadKey]);

  const routes = ops?.routes ?? [];
  const otherJourneys = useMemo(() => routes.filter((r) => r.journeyId !== selected), [routes, selected]);
  const resourceOptions = useMemo(() => {
    const locs = Object.values(ref.locations).map((l) => ({ value: l.locationId, label: `location: ${l.name}` }));
    const conns = Object.values(ref.connections).map((c) => ({ value: c.connectionId, label: `connection: ${locationName(c.fromLocationId)} → ${locationName(c.toLocationId)}` }));
    const workers = (ops?.workers ?? []).map((w) => ({ value: w.workerId, label: `worker: ${w.fullName || w.workerId.slice(0, 8)}` }));
    return [...locs, ...conns, ...workers];
  }, [ref.locations, ref.connections, ops?.workers]);

  return (
    <div className="replan">
      <section className="panel" aria-labelledby="journeys-title">
        <h2 id="journeys-title">Journeys</h2>
        <ErrorBanner error={error} />
        <table className="data">
          <thead>
            <tr>
              <th>Journey</th>
              <th>Mode</th>
              <th>Status</th>
              <th>Samples</th>
              <th>Path</th>
              <th></th>
            </tr>
          </thead>
          <tbody>
            {routes.map((r) => (
              <tr key={String(r.journeyId)}>
                <td>
                  {String(r.journeyId).slice(0, 8)} v{String(r.planVersion)}
                </td>
                <td>{String(r.routeMode)}</td>
                <td>
                  <StatusTag status={String(r.status)} />
                </td>
                <td>{((r.sampleIds as string[]) ?? []).map((s) => s.slice(0, 8)).join(", ")}</td>
                <td>{((r.path as string[]) ?? []).map(locationName).join(" → ")}</td>
                <td>
                  <button type="button" onClick={() => setSelected(String(r.journeyId))}>
                    Manage
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </section>

      <section className="panel" aria-labelledby="disruption-title">
        <h2 id="disruption-title">Report disruption</h2>
        <DisruptionForm options={resourceOptions} onDone={reload} />
      </section>

      {plan ? (
        <section className="panel" aria-labelledby="plan-title">
          <h2 id="plan-title">
            Journey {plan.journeyId.slice(0, 8)} · plan version {plan.planVersion} · {humanize(plan.status ?? "")}
            {plan.replanStatus ? ` · replan ${plan.replanStatus}` : ""}
          </h2>
          <p>
            Samples: {(plan.sampleIds ?? []).map((s) => s.slice(0, 8)).join(", ")} · ETA {fmt(plan.estimatedDeliveryAt)}
          </p>
          <ol className="stops">
            {(plan.orderedStops ?? []).map((s) => (
              <li key={s.stopId} className={s.completedAt ? "done" : ""}>
                {humanize(s.stopType)} at {locationName(s.locationId)} · est. {fmt(s.estimatedAt)}
              </li>
            ))}
          </ol>
          <table className="data" aria-label="Journey legs">
            <thead>
              <tr>
                <th>#</th>
                <th>Assignment</th>
                <th>Sample</th>
                <th>From</th>
                <th>To</th>
                <th>Worker</th>
                <th>Status</th>
              </tr>
            </thead>
            <tbody>
              {plan.legs.map((l) => (
                <tr key={l.assignmentId}>
                  <td>{l.sequence}</td>
                  <td>{l.assignmentId.slice(0, 8)}</td>
                  <td>{l.sampleId?.slice(0, 8)}</td>
                  <td>{locationName(l.fromLocationId)}</td>
                  <td>{locationName(l.toLocationId)}</td>
                  <td>{l.workerId ? userName(l.workerId) : "unassigned"}</td>
                  <td>
                    <StatusTag status={l.status} />
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
          <div className="actions">
            <ActionForm
              title="Reroute journey"
              submitLabel="Reroute"
              onDone={reload}
              onSubmit={async () => {
                const r = await api("reroute-journey", { journeyId: plan.journeyId, expectedPlanVersion: plan.planVersion, idempotencyKey: newKey() });
                return `Replan status: ${r.replanStatus}${r.replacementPlanId ? ` · replacement ${String(r.replacementPlanId).slice(0, 8)}` : ""}`;
              }}
            />
            <CancelForm plan={plan} onDone={reload} />
            {(plan.sampleIds?.length ?? 0) > 1 ? <SplitForm plan={plan} onDone={reload} /> : null}
            {otherJourneys.length ? <MergeForm plan={plan} others={otherJourneys} onDone={reload} /> : null}
            <EditForm plan={plan} onDone={reload} />
          </div>
        </section>
      ) : null}
    </div>
  );
}

function DisruptionForm({ options, onDone }: { options: { value: string; label: string }[]; onDone: () => void }) {
  const [type, setType] = useState("connection");
  const [resource, setResource] = useState("");
  const [reason, setReason] = useState("");
  return (
    <ActionForm
      title="Report disruption"
      submitLabel="Report disruption"
      onDone={onDone}
      onSubmit={async () => {
        const r = await api("report-disruption", { resourceType: type, resourceId: resource, reason, occurredAt: nowIso(), idempotencyKey: newKey() });
        return `Replan ${r.replanStatus}: ${r.affectedSampleIds.length} sample(s) affected, ${r.replacementPlanIds.length} replacement plan(s)`;
      }}
    >
      <SelectField label="Resource type" value={type} onChange={setType} options={RESOURCE_TYPES.map((t) => ({ value: t, label: t }))} />
      <SelectField label="Resource" value={resource} onChange={setResource} allowEmpty options={options} />
      <Field label="Resource id" value={resource} onChange={setResource} required />
      <Field label="Reason" value={reason} onChange={setReason} />
    </ActionForm>
  );
}

function CancelForm({ plan, onDone }: { plan: JourneyPlan; onDone: () => void }) {
  const [reason, setReason] = useState("");
  return (
    <ActionForm
      title="Cancel journey"
      submitLabel="Cancel journey"
      onDone={onDone}
      onSubmit={async () => {
        const r = await api("cancel-journey", { journeyId: plan.journeyId, expectedPlanVersion: plan.planVersion, reason, idempotencyKey: newKey() });
        return `Journey ${String(r.journeyId).slice(0, 8)} cancelled`;
      }}
    >
      <Field label="Cancellation reason" value={reason} onChange={setReason} />
    </ActionForm>
  );
}

function SplitForm({ plan, onDone }: { plan: JourneyPlan; onDone: () => void }) {
  const [ids, setIds] = useState<string[]>([]);
  const toggle = (id: string) => setIds((cur) => (cur.includes(id) ? cur.filter((x) => x !== id) : [...cur, id]));
  return (
    <ActionForm
      title="Split journey"
      submitLabel="Split selected samples"
      onDone={onDone}
      onSubmit={async () => {
