      onDone={onDone}
      onSubmit={async () => {
        const r = await api("split-journey", { journeyId: plan.journeyId, expectedPlanVersion: plan.planVersion, sampleIds: ids, idempotencyKey: newKey() });
        return `Split journey ${String(r.splitJourney.journeyId).slice(0, 8)} created`;
      }}
    >
      {(plan.sampleIds ?? []).map((s) => (
        <label key={s} className="field check">
          <input type="checkbox" checked={ids.includes(s)} onChange={() => toggle(s)} />
          <span>Sample {s.slice(0, 8)}</span>
        </label>
      ))}
    </ActionForm>
  );
}

function MergeForm({ plan, others, onDone }: { plan: JourneyPlan; others: Record<string, any>[]; onDone: () => void }) {
  const [ids, setIds] = useState<string[]>([]);
  const toggle = (id: string) => setIds((cur) => (cur.includes(id) ? cur.filter((x) => x !== id) : [...cur, id]));
  return (
    <ActionForm
      title="Merge journeys into this one"
      submitLabel="Merge selected journeys"
      onDone={onDone}
      onSubmit={async () => {
        const r = await api("merge-journeys", { targetJourneyId: plan.journeyId, expectedPlanVersion: plan.planVersion, sourceJourneyIds: ids, idempotencyKey: newKey() });
        return `Merged: journey now ${r.routeMode} with ${r.sampleIds.length} samples (version ${r.planVersion})`;
      }}
    >
      {others.map((o) => (
        <label key={String(o.journeyId)} className="field check">
          <input type="checkbox" checked={ids.includes(String(o.journeyId))} onChange={() => toggle(String(o.journeyId))} />
          <span>
            Journey {String(o.journeyId).slice(0, 8)} ({((o.sampleIds as string[]) ?? []).length} samples)
          </span>
        </label>
      ))}
    </ActionForm>
  );
}

function EditForm({ plan, onDone }: { plan: JourneyPlan; onDone: () => void }) {
  const [changeType, setChangeType] = useState("replace_worker");
  const [changes, setChanges] = useState("{}");
  return (
    <ActionForm
      title="Edit active plan"
      submitLabel="Apply change"
      onDone={onDone}
      onSubmit={async () => {
        let parsed: unknown;
        try {
          parsed = JSON.parse(changes);
        } catch {
          throw new Error("changes must be valid JSON");
        }
        const r = await api("edit-active-plan", { journeyId: plan.journeyId, expectedPlanVersion: plan.planVersion, changeType, changes: parsed, idempotencyKey: newKey() });
        return `Plan updated to version ${r.planVersion}`;
      }}
    >
      <SelectField label="Change type" value={changeType} onChange={setChangeType} options={CHANGE_TYPES.map((t) => ({ value: t, label: humanize(t) }))} />
      <label className="field">
        <span>Changes (JSON)</span>
        <textarea value={changes} onChange={(e) => setChanges(e.target.value)} rows={4} />
      </label>
      <p className="muted">
        Examples: replace_worker {"{"}"assignmentId": "…", "workerId": "…"{"}"} · add_stop {"{"}"locationId": "…", "afterLocationId": "…", "dwellMinutes": 0{"}"} · remove_stop{" "}
        {"{"}"locationId": "…"{"}"} · reorder_stops {"{"}"locationIds": ["…"]{"}"} · split_samples {"{"}"sampleIds": ["…"]{"}"} · merge_samples {"{"}"sourceJourneyIds": ["…"]{"}"}
      </p>
    </ActionForm>
  );
}

