}

function certsFromText(text: string) {
  return text
    .split(",")
    .map((s) => s.trim())
    .filter(Boolean)
    .map((code) => ({ code, active: true }));
}

function CreateUserForm({ locOptions }: { locOptions: { value: string; label: string }[] }) {
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [fullName, setFullName] = useState("");
  const [email, setEmail] = useState("");
  const [roles, setRoles] = useState<string[]>(["requester"]);
  const [quals, setQuals] = useState("");
  const [loc, setLoc] = useState("");
  return (
    <ActionForm
      title="Create user"
      submitLabel="Create user"
      onSubmit={async () => {
        const body: any = { username, initialPassword: password, fullName, roles, active: true };
