import { useEffect, useMemo, useState } from "react";
import { api, fmt } from "../api";
import { ActionForm, CheckField, Field, SelectField, humanize } from "../components/common";
import { useStore } from "../store";
import type { OperationsState } from "../types";

const ROLES = ["administrator", "dispatcher", "requester", "collection_professional", "delivery_partner", "node_handler", "laboratory_team"];
const FUNCTIONS = ["collection_point", "transfer_point", "hub", "laboratory"];

export function AdminView() {
  const { ref, tick, locationName } = useStore();
  const [ops, setOps] = useState<OperationsState | null>(null);
  const locations = useMemo(() => Object.values(ref.locations).sort((a, b) => a.name.localeCompare(b.name)), [ref.locations]);
  const sampleTypes = useMemo(() => Object.values(ref.sampleTypes).sort((a, b) => a.name.localeCompare(b.name)), [ref.sampleTypes]);
  const connections = useMemo(() => Object.values(ref.connections), [ref.connections]);
  const locOptions = locations.map((l) => ({ value: l.locationId, label: l.name }));
  const labOptions = locations.filter((l) => l.functions.laboratory).map((l) => ({ value: l.locationId, label: l.name }));
  const stOptions = sampleTypes.map((t) => ({ value: t.sampleTypeId, label: t.name }));

  useEffect(() => {
    api<OperationsState>("read-operations-state", {}).then(setOps).catch(() => undefined);
  }, [tick]);

  return (
    <div className="admin">
      <section className="panel" aria-labelledby="admin-users">
        <h2 id="admin-users">Users and roles</h2>
        <UsersTable workers={ops?.workers ?? []} />
        <div className="two-col">
          <CreateUserForm locOptions={locOptions} />
          <UpdateUserForm locOptions={locOptions} workers={ops?.workers ?? []} />
        </div>
      </section>

      <section className="panel" aria-labelledby="admin-locations">
        <h2 id="admin-locations">Locations</h2>
        <table className="data">
          <thead>
            <tr>
              <th>Name</th>
              <th>Coordinate</th>
              <th>Functions</th>
              <th>Coverage</th>
              <th>Handling</th>
              <th>Active</th>
            </tr>
          </thead>
          <tbody>
            {locations.map((l) => (
              <tr key={l.locationId}>
                <td>{l.name}</td>
                <td>
                  {l.coordinate.latitude.toFixed(4)}, {l.coordinate.longitude.toFixed(4)}
                </td>
                <td>
                  {FUNCTIONS.map((f) => (
                    <span key={f} className={l.functions[f as keyof typeof l.functions] ? "tag ok" : "tag"}>
                      {humanize(f)}
                    </span>
                  ))}
                </td>
                <td>{l.coverageKm} km</td>
                <td>{l.handlingMinutes} min</td>
                <td>{l.active ? "yes" : "no"}</td>
              </tr>
            ))}
          </tbody>
        </table>
        <div className="two-col">
          <LocationForm />
          <LocationForm existing={locOptions} />
          <StatusForm locOptions={locOptions} />
          <FunctionStatusForm locOptions={locOptions} />
        </div>
      </section>

      <section className="panel" aria-labelledby="admin-connections">
        <h2 id="admin-connections">Connections</h2>
        <table className="data">
          <thead>
            <tr>
              <th>From</th>
              <th>To</th>
              <th>Travel</th>
              <th>Cost</th>
              <th>Cooled</th>
              <th>Active</th>
            </tr>
          </thead>
          <tbody>
            {connections.map((c) => (
              <tr key={c.connectionId}>
                <td>{locationName(c.fromLocationId)}</td>
                <td>{locationName(c.toLocationId)}</td>
                <td>{c.travelMinutes} min</td>
                <td>{c.costUnits}</td>
                <td>{c.cooled ? "yes" : "no"}</td>
                <td>{c.active ? "yes" : "no"}</td>
              </tr>
            ))}
          </tbody>
        </table>
        <div className="two-col">
          <ConnectionForm locOptions={locOptions} />
          <ConnectionStatusForm connections={connections.map((c) => ({ value: c.connectionId, label: `${locationName(c.fromLocationId)} → ${locationName(c.toLocationId)}` }))} />
        </div>
      </section>

      <section className="panel" aria-labelledby="admin-capacity">
        <h2 id="admin-capacity">Capacity and laboratory acceptance</h2>
        <div className="two-col">
          <CapacityForm
            options={[
              ...locOptions.map((o) => ({ ...o, label: `location: ${o.label}` })),
              ...connections.map((c) => ({ value: c.connectionId, label: `connection: ${locationName(c.fromLocationId)} → ${locationName(c.toLocationId)}` })),
            ]}
          />
          <AcceptanceForm labOptions={labOptions} stOptions={stOptions} />
        </div>
      </section>

      <section className="panel" aria-labelledby="admin-sample-types">
        <h2 id="admin-sample-types">Sample types</h2>
        <table className="data">
          <thead>
            <tr>
              <th>Name</th>
              <th>Container</th>
              <th>Temperature</th>
              <th>Qualification</th>
              <th>Cooled route</th>
              <th>Batching</th>
              <th>Incompatible with</th>
            </tr>
          </thead>
          <tbody>
            {sampleTypes.map((t) => (
              <tr key={t.sampleTypeId}>
                <td>{t.name}</td>
                <td>{t.containerType}</td>
                <td>
                  {t.temperatureMinC}…{t.temperatureMaxC} °C
                </td>
                <td>{t.qualifiedCollectorRequired ? t.requiredQualification : "none"}</td>
                <td>{t.requiresCooledRoute ? "yes" : "no"}</td>
                <td>{t.batchingAllowed ? "allowed" : "no batching"}</td>
                <td>{t.incompatibleSampleTypes.map((id) => ref.sampleTypes[id]?.name ?? id.slice(0, 8)).join(", ") || "—"}</td>
              </tr>
            ))}
          </tbody>
        </table>
        <div className="two-col">
          <SampleTypeForm stOptions={stOptions} />
          <SampleTypeForm stOptions={stOptions} existing />
        </div>
      </section>

      <section className="panel" aria-labelledby="admin-serviceability">
        <h2 id="admin-serviceability">Serviceability snapshot</h2>
        <SnapshotPanel />
      </section>
    </div>
  );
}

function UsersTable({ workers }: { workers: OperationsState["workers"] }) {
  const { ref } = useStore();
  const users = Object.values(ref.users);
  if (!users.length) return <p className="muted">No users loaded yet (users appear here as they are created or updated).</p>;
  return (
    <table className="data">
      <thead>
        <tr>
          <th>User</th>
          <th>Roles</th>
          <th>Assigned location</th>
          <th>Active</th>
          <th>Available</th>
        </tr>
      </thead>
      <tbody>
        {users.map((u) => {
          const w = workers.find((x) => x.workerId === u.userId);
          return (
            <tr key={u.userId}>
              <td>
                {u.fullName || u.username} <code>{u.userId.slice(0, 8)}</code>
              </td>
              <td>{(u.roles ?? []).map(humanize).join(", ")}</td>
              <td>{u.assignedLocationId ? ref.locations[u.assignedLocationId]?.name ?? u.assignedLocationId.slice(0, 8) : "—"}</td>
              <td>{u.active ? "yes" : "no"}</td>
              <td>{w ? w.status : "—"}</td>
            </tr>
          );
        })}
      </tbody>
    </table>
  );
}

function RolePicker({ roles, onChange }: { roles: string[]; onChange: (r: string[]) => void }) {
  return (
    <fieldset>
      <legend>Roles</legend>
      {ROLES.map((r) => (
        <CheckField key={r} label={humanize(r)} checked={roles.includes(r)} onChange={(v) => onChange(v ? [...roles, r] : roles.filter((x) => x !== r))} />
      ))}
    </fieldset>
  );
}

function certsFromText(text: string) {
  return text
    .split(",")
    .map((s) => s.trim())
    .filter(Boolean)
    .map((code) => ({ code, active: true }));
}

function CreateUserForm({ locOptions }: { locOptions: { value: string; label: string }[] }) {
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [fullName, setFullName] = useState("");
  const [email, setEmail] = useState("");
  const [roles, setRoles] = useState<string[]>(["requester"]);
  const [quals, setQuals] = useState("");
  const [loc, setLoc] = useState("");
  return (
    <ActionForm
      title="Create user"
      submitLabel="Create user"
      onSubmit={async () => {
        const body: any = { username, initialPassword: password, fullName, roles, active: true };
        if (email) body.email = email;
        if (quals.trim()) {
          body.qualifications = quals.split(",").map((s) => s.trim()).filter(Boolean);
          body.certifications = certsFromText(quals);
        }
        if (loc) body.assignedLocationId = loc;
        const r = await api("create-user", body);
        return `User ${r.username} created (${String(r.userId).slice(0, 8)})`;
      }}
    >
      <Field label="Username" value={username} onChange={setUsername} required />
      <Field label="Initial password" value={password} onChange={setPassword} type="password" required />
      <Field label="Full name" value={fullName} onChange={setFullName} />
      <Field label="Email" value={email} onChange={setEmail} type="email" />
      <RolePicker roles={roles} onChange={setRoles} />
      <Field label="Qualifications / certifications (comma separated)" value={quals} onChange={setQuals} placeholder="Amber, Frost" />
      <SelectField label="Assigned node or laboratory" value={loc} onChange={setLoc} allowEmpty options={locOptions} />
    </ActionForm>
  );
}

function UpdateUserForm({ locOptions, workers }: { locOptions: { value: string; label: string }[]; workers: OperationsState["workers"] }) {
  const { ref } = useStore();
  const [userId, setUserId] = useState("");
  const [roles, setRoles] = useState<string[]>([]);
  const [quals, setQuals] = useState("");
  const [loc, setLoc] = useState("");
  const [active, setActive] = useState(true);
  const [available, setAvailable] = useState(true);
  const [cap, setCap] = useState("1");
  const known = Object.values(ref.users);
  const loadUser = async (id: string) => {
    setUserId(id);
    if (!id) return;
    try {
      const u = await api<any>(`read-user/${id}`, undefined, "GET");
      setRoles(u.roles ?? []);
      setQuals((u.qualifications ?? []).join(", "));
      setActive(!!u.active);
      setLoc(ref.users[id]?.assignedLocationId ?? "");
      const w = workers.find((x) => x.workerId === id);
      if (w) {
        setAvailable(w.available);
        setCap(String(w.capacityUnits));
      }
    } catch {
      /* fall back to manual entry */
    }
  };
  return (
    <div>
      <ActionForm
        title="Update user access"
        submitLabel="Save access"
        onSubmit={async () => {
          const body: any = { userId, roles, active };
          body.qualifications = quals.split(",").map((s) => s.trim()).filter(Boolean);
          body.certifications = certsFromText(quals);
          if (loc) body.assignedLocationId = loc;
          const r = await api("update-user-access", body);
          return `Access updated: roles ${r.roles.join(", ")}`;
        }}
      >
        <SelectField label="User" value={userId} onChange={loadUser} allowEmpty options={known.map((u) => ({ value: u.userId, label: u.fullName || u.username }))} />
        <Field label="User id" value={userId} onChange={loadUser} required />
        <RolePicker roles={roles} onChange={setRoles} />
        <Field label="Qualifications / certifications (comma separated)" value={quals} onChange={setQuals} />
        <SelectField label="Assigned node or laboratory" value={loc} onChange={setLoc} allowEmpty options={locOptions} />
        <CheckField label="Account active" checked={active} onChange={setActive} />
      </ActionForm>
      <ActionForm
        title="Set worker availability"
        submitLabel="Save availability"
        onSubmit={async () => {
          const r = await api("set-worker-availability", { workerId: userId, available, capacityUnits: Number(cap) });
          return `Worker ${r.available ? "available" : "unavailable"} with ${r.capacityUnits} capacity units`;
        }}
      >
        <CheckField label="Available for work" checked={available} onChange={setAvailable} />
        <Field label="Worker capacity units" value={cap} onChange={setCap} type="number" required />
      </ActionForm>
    </div>
  );
}

function LocationForm({ existing }: { existing?: { value: string; label: string }[] }) {
  const { ref } = useStore();
  const [id, setId] = useState("");
  const [name, setName] = useState("");
  const [lat, setLat] = useState("12.9716");
  const [lon, setLon] = useState("77.5946");
  const [coverage, setCoverage] = useState("5");
  const [handling, setHandling] = useState("0");
  const [active, setActive] = useState(true);
  const [fns, setFns] = useState<string[]>(["collection_point"]);
  const pick = (lid: string) => {
    setId(lid);
    const l = ref.locations[lid];
    if (!l) return;
    setName(l.name);
    setLat(String(l.coordinate.latitude));
    setLon(String(l.coordinate.longitude));
    setCoverage(String(l.coverageKm));
    setHandling(String(l.handlingMinutes));
    setFns(FUNCTIONS.filter((f) => l.functions[f as keyof typeof l.functions]));
  };
  return (
    <ActionForm
      title={existing ? "Update location" : "Create location"}
      submitLabel={existing ? "Save location" : "Create location"}
      onSubmit={async () => {
        const body: any = { name, coordinate: { latitude: Number(lat), longitude: Number(lon) }, coverageKm: Number(coverage), handlingMinutes: Number(handling), functions: fns };
        if (existing) {
          body.locationId = id;
          const r = await api("update-location", body);
          return `Location ${r.name} updated`;
        }
        body.active = active;
        const r = await api("create-location", body);
        return `Location ${r.name} created (${String(r.locationId).slice(0, 8)})`;
      }}
    >
      {existing ? <SelectField label="Location" value={id} onChange={pick} allowEmpty options={existing} /> : null}
      <Field label="Name" value={name} onChange={setName} required />
      <Field label="Latitude" value={lat} onChange={setLat} type="number" step="any" required />
      <Field label="Longitude" value={lon} onChange={setLon} type="number" step="any" required />
      <Field label="Coverage km (max 5)" value={coverage} onChange={setCoverage} type="number" step="any" />
      <Field label="Handling minutes" value={handling} onChange={setHandling} type="number" />
      <fieldset>
        <legend>Functions</legend>
        {FUNCTIONS.map((f) => (
          <CheckField key={f} label={humanize(f)} checked={fns.includes(f)} onChange={(v) => setFns(v ? [...fns, f] : fns.filter((x) => x !== f))} />
        ))}
      </fieldset>
      {!existing ? <CheckField label="Active" checked={active} onChange={setActive} /> : null}
    </ActionForm>
  );
}

function StatusForm({ locOptions }: { locOptions: { value: string; label: string }[] }) {
  const [id, setId] = useState("");
  const [active, setActive] = useState(true);
  return (
    <ActionForm
      title="Activate or deactivate location"
      submitLabel="Apply location status"
      onSubmit={async () => {
        const r = await api("set-location-status", { locationId: id, active });
        return `Location is now ${r.active ? "active" : "inactive"}`;
      }}
    >
      <SelectField label="Location" value={id} onChange={setId} allowEmpty options={locOptions} />
      <CheckField label="Active" checked={active} onChange={setActive} />
    </ActionForm>
  );
}

function FunctionStatusForm({ locOptions }: { locOptions: { value: string; label: string }[] }) {
  const [id, setId] = useState("");
  const [fn, setFn] = useState("collection_point");
  const [active, setActive] = useState(true);
  return (
    <ActionForm
      title="Activate or deactivate location function"
      submitLabel="Apply function status"
      onSubmit={async () => {
        const r = await api("set-location-function-status", { locationId: id, function: fn, active });
        return `${humanize(r.function)} is now ${r.active ? "active" : "inactive"}`;
      }}
    >
      <SelectField label="Location" value={id} onChange={setId} allowEmpty options={locOptions} />
      <SelectField label="Function" value={fn} onChange={setFn} options={FUNCTIONS.map((f) => ({ value: f, label: humanize(f) }))} />
      <CheckField label="Active" checked={active} onChange={setActive} />
    </ActionForm>
  );
}

function ConnectionForm({ locOptions }: { locOptions: { value: string; label: string }[] }) {
  const [from, setFrom] = useState("");
  const [to, setTo] = useState("");
  const [travel, setTravel] = useState("30");
  const [cost, setCost] = useState("1");
  const [cooled, setCooled] = useState(false);
  const [active, setActive] = useState(true);
  return (
    <ActionForm
      title="Create connection"
      submitLabel="Create connection"
      onSubmit={async () => {
        const r = await api("create-connection", { fromLocationId: from, toLocationId: to, travelMinutes: Number(travel), costUnits: Number(cost), cooled, active });
        return `Connection ${String(r.connectionId).slice(0, 8)} created`;
      }}
    >
      <SelectField label="From location" value={from} onChange={setFrom} allowEmpty options={locOptions} />
      <SelectField label="To location" value={to} onChange={setTo} allowEmpty options={locOptions} />
      <Field label="Travel minutes" value={travel} onChange={setTravel} type="number" required />
      <Field label="Cost units" value={cost} onChange={setCost} type="number" step="any" required />
      <CheckField label="Cooled transport" checked={cooled} onChange={setCooled} />
      <CheckField label="Active" checked={active} onChange={setActive} />
    </ActionForm>
  );
}

function ConnectionStatusForm({ connections }: { connections: { value: string; label: string }[] }) {
  const [id, setId] = useState("");
  const [active, setActive] = useState(true);
  return (
    <ActionForm
      title="Activate or deactivate connection"
      submitLabel="Apply connection status"
      onSubmit={async () => {
        const r = await api("set-connection-status", { connectionId: id, active });
        return `Connection is now ${r.active ? "active" : "inactive"}`;
      }}
    >
      <SelectField label="Connection" value={id} onChange={setId} allowEmpty options={connections} />
      <CheckField label="Active" checked={active} onChange={setActive} />
    </ActionForm>
  );
}

function CapacityForm({ options }: { options: { value: string; label: string }[] }) {
  const [id, setId] = useState("");
  const [regular, setRegular] = useState("10");
  const [cooled, setCooled] = useState("0");
  return (
    <ActionForm
      title="Configure capacity"
      submitLabel="Save capacity"
      onSubmit={async () => {
        const r = await api("configure-capacity", { resourceId: id, capacityUnits: Number(regular), cooledCapacityUnits: Number(cooled) });
        return `Capacity set: ${r.capacityUnits} regular / ${r.cooledCapacityUnits} cooled`;
      }}
    >
      <SelectField label="Node, laboratory or connection" value={id} onChange={setId} allowEmpty options={options} />
      <Field label="Regular capacity units" value={regular} onChange={setRegular} type="number" required />
      <Field label="Cooled capacity units" value={cooled} onChange={setCooled} type="number" />
    </ActionForm>
  );
}

function AcceptanceForm({ labOptions, stOptions }: { labOptions: { value: string; label: string }[]; stOptions: { value: string; label: string }[] }) {
  const [lab, setLab] = useState("");
  const [st, setSt] = useState("");
  const [accepts, setAccepts] = useState(true);
  return (
    <ActionForm
      title="Configure laboratory acceptance"
      submitLabel="Save acceptance"
      onSubmit={async () => {
        const r = await api("configure-laboratory-acceptance", { laboratoryId: lab, sampleTypeId: st, accepts });
        return `Laboratory ${r.accepts ? "now accepts" : "no longer accepts"} this sample type`;
      }}
    >
      <SelectField label="Laboratory" value={lab} onChange={setLab} allowEmpty options={labOptions} />
      <SelectField label="Sample type" value={st} onChange={setSt} allowEmpty options={stOptions} />
      <CheckField label="Accepts" checked={accepts} onChange={setAccepts} />
    </ActionForm>
  );
}

function SampleTypeForm({ stOptions, existing }: { stOptions: { value: string; label: string }[]; existing?: boolean }) {
  const { ref } = useStore();
  const [id, setId] = useState("");
  const [name, setName] = useState("");
  const [container, setContainer] = useState("standard_vial");
  const [tmin, setTmin] = useState("2");
  const [tmax, setTmax] = useState("25");
  const [qualified, setQualified] = useState(true);
  const [qualification, setQualification] = useState("");
  const [cooled, setCooled] = useState(false);
  const [batching, setBatching] = useState(true);
  const [incompatible, setIncompatible] = useState<string[]>([]);
  const pick = (sid: string) => {
    setId(sid);
    const t = ref.sampleTypes[sid];
    if (!t) return;
    setName(t.name);
    setContainer(t.containerType);
    setTmin(String(t.temperatureMinC));
    setTmax(String(t.temperatureMaxC));
    setQualified(t.qualifiedCollectorRequired);
    setQualification(t.requiredQualification);
    setCooled(t.requiresCooledRoute);
    setBatching(t.batchingAllowed);
    setIncompatible(t.incompatibleSampleTypes);
  };
  return (
    <ActionForm
      title={existing ? "Update sample type" : "Create sample type"}
      submitLabel={existing ? "Save sample type" : "Create sample type"}
      onSubmit={async () => {
        const body: any = {
          containerType: container,
          temperatureMinC: Number(tmin),
          temperatureMaxC: Number(tmax),
          qualifiedCollectorRequired: qualified,
          requiredQualification: qualification || name,
          incompatibleSampleTypes: incompatible,
          requiresCooledRoute: cooled,
          batchingAllowed: batching,
        };
        if (existing) {
          body.sampleTypeId = id;
          const r = await api("update-sample-type", body);
          return `Sample type ${r.name} updated`;
        }
        body.name = name;
        const r = await api("create-sample-type", body);
        return `Sample type ${r.name} created`;
      }}
    >
      {existing ? <SelectField label="Sample type" value={id} onChange={pick} allowEmpty options={stOptions} /> : <Field label="Name" value={name} onChange={setName} required />}
      <Field label="Container type" value={container} onChange={setContainer} required />
      <Field label="Temperature min (°C)" value={tmin} onChange={setTmin} type="number" step="any" required />
      <Field label="Temperature max (°C)" value={tmax} onChange={setTmax} type="number" step="any" required />
      <CheckField label="Qualified collector required" checked={qualified} onChange={setQualified} />
      <Field label="Required qualification" value={qualification} onChange={setQualification} />
      <CheckField label="Requires cooled route" checked={cooled} onChange={setCooled} />
      <CheckField label="Batching allowed" checked={batching} onChange={setBatching} />
      <fieldset>
        <legend>Incompatible sample types</legend>
        {stOptions
          .filter((o) => o.value !== id)
          .map((o) => (
            <CheckField
              key={o.value}
              label={o.label}
              checked={incompatible.includes(o.value)}
              onChange={(v) => setIncompatible(v ? [...incompatible, o.value] : incompatible.filter((x) => x !== o.value))}
            />
          ))}
      </fieldset>
    </ActionForm>
  );
}

function SnapshotPanel() {
  const { tick } = useStore();
  const [snap, setSnap] = useState<any>(null);
  useEffect(() => {
    api("read-serviceability-snapshot", {}).then(setSnap).catch(() => undefined);
  }, [tick]);
  if (!snap) return <p className="muted">Loading…</p>;
  return (
    <div>
      <p>
        Version {snap.version} ({snap.status}) · computed {fmt(snap.computedAt)} · network revision {snap.networkRevision} · {snap.activeCollectionPointCount} active collection
        points
      </p>
      <ul>
        {snap.regions.map((r: any) => (
          <li key={r.locationId}>
            {r.name}: {r.coverageKm} km around {r.latitude.toFixed(4)}, {r.longitude.toFixed(4)}
          </li>
        ))}
      </ul>
    </div>
  );
}

