import { useEffect, useState } from "react";
import { ErrorBanner, errorText, humanize } from "./components/common";
import { useStore } from "./store";
import { AdminView } from "./views/AdminView";
import { AuditView } from "./views/AuditView";
import { CapacityView } from "./views/CapacityView";
import { Login } from "./views/Login";
import { MonitorView } from "./views/MonitorView";
import { ReplanView } from "./views/ReplanView";
import { RequesterView } from "./views/RequesterView";
import { WorkView } from "./views/WorkView";

interface Tab {
  id: string;
  label: string;
  render: () => JSX.Element;
}

function tabsFor(role: string): Tab[] {
  switch (role) {
    case "requester":
      return [{ id: "requests", label: "Requests", render: () => <RequesterView /> }];
    case "collection_professional":
    case "delivery_partner":
      return [
        { id: "work", label: "My work", render: () => <WorkView /> },
        { id: "presealed", label: "Register pre-sealed sample", render: () => <RequesterView presealed /> },
      ];
    case "node_handler":
    case "laboratory_team":
      return [
        { id: "work", label: "My work", render: () => <WorkView /> },
        { id: "capacity", label: "Capacity", render: () => <CapacityView /> },
        { id: "presealed", label: "Register pre-sealed sample", render: () => <RequesterView presealed /> },
      ];
    case "dispatcher":
      return [
        { id: "monitor", label: "Monitor", render: () => <MonitorView /> },
        { id: "journeys", label: "Journeys & replanning", render: () => <ReplanView /> },
        { id: "work", label: "My work", render: () => <WorkView /> },
        { id: "audit", label: "Audit", render: () => <AuditView /> },
      ];
    case "administrator":
      return [
        { id: "monitor", label: "Monitor", render: () => <MonitorView /> },
        { id: "journeys", label: "Journeys & replanning", render: () => <ReplanView /> },
        { id: "admin", label: "Administration", render: () => <AdminView /> },
        { id: "work", label: "My work", render: () => <WorkView /> },
        { id: "audit", label: "Audit", render: () => <AuditView /> },
      ];
    default:
      return [];
  }
}

export function App() {
  const { session, loading, signOut, selectRole } = useStore();
  const [tab, setTab] = useState("");
  const [error, setError] = useState<string | null>(null);

  const role = session?.activeRole ?? "";
  const tabs = tabsFor(role);
  useEffect(() => {
    if (tabs.length && !tabs.some((t) => t.id === tab)) setTab(tabs[0].id);
  }, [role]);

  if (loading) return <p className="muted">Loading…</p>;
  if (!session) return <Login />;

  const switchRole = async (r: string) => {
    setError(null);
    try {
      await selectRole(r);
    } catch (e) {
      setError(errorText(e));
    }
  };

  const needsRole = session.roleSelectionRequired || !session.activeRole;
  const active = tabs.find((t) => t.id === tab) ?? tabs[0];

  return (
    <div className="app">
      <header className="topbar">
        <h1>Lab Sample Pickup &amp; Delivery</h1>
        <div className="session">
          <span>
            Signed in as <strong>{session.fullName || session.username}</strong>
          </span>
          <label className="field inline">
            <span>Active role</span>
            <select aria-label="Active role" value={session.activeRole ?? ""} onChange={(e) => switchRole(e.target.value)}>
              {!session.activeRole ? <option value="">Select a role…</option> : null}
              {session.roles.map((r) => (
                <option key={r} value={r}>
                  {humanize(r)}
                </option>
              ))}
            </select>
          </label>
          <button type="button" onClick={signOut}>
            Sign out
          </button>
        </div>
      </header>
      <ErrorBanner error={error} />
      {needsRole ? (
        <main className="role-select">
          <h2>Select the role you are working under</h2>
          <p className="muted">You hold {session.roles.length} roles. Permissions and work views follow the selected role; switching never changes your roles.</p>
          <ul className="role-list">
            {session.roles.map((r) => (
              <li key={r}>
                <button type="button" onClick={() => switchRole(r)}>
                  Work as {humanize(r)}
                </button>
              </li>
            ))}
          </ul>
        </main>
      ) : (
        <>
          <nav aria-label="Sections">
            {tabs.map((t) => (
              <button key={t.id} type="button" className={active?.id === t.id ? "tab active" : "tab"} aria-current={active?.id === t.id ? "page" : undefined} onClick={() => setTab(t.id)}>
                {t.label}
              </button>
            ))}
          </nav>
          <main>
            <h2 className="role-heading">{humanize(role)}</h2>
            {active ? active.render() : <p className="muted">No views for this role.</p>}
          </main>
        </>
      )}
    </div>
  );
}

