:root {
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  color: #1f2937;
  background: #f5f6f8;
  font-size: 14px;
}
* { box-sizing: border-box; }
body { margin: 0; }
h1 { font-size: 1.25rem; margin: 0; }
h2 { font-size: 1.1rem; margin: 0 0 0.5rem; }
h3 { font-size: 1rem; margin: 0 0 0.4rem; }
h4 { font-size: 0.9rem; margin: 0.6rem 0 0.3rem; }
.app { min-height: 100vh; display: flex; flex-direction: column; }
.topbar { display: flex; justify-content: space-between; align-items: center; gap: 1rem; padding: 0.6rem 1rem; background: #111827; color: #fff; flex-wrap: wrap; }
.session { display: flex; align-items: center; gap: 0.8rem; }
.topbar select { padding: 0.25rem; }
nav[aria-label="Sections"] { display: flex; gap: 0.25rem; padding: 0.5rem 1rem 0; background: #e5e7eb; }
.tab { border: 1px solid #d1d5db; border-bottom: none; background: #f3f4f6; padding: 0.4rem 0.8rem; border-radius: 6px 6px 0 0; cursor: pointer; }
.tab.active { background: #fff; font-weight: 600; }
main { padding: 1rem; flex: 1; }
.role-heading { color: #6b7280; font-weight: 500; }
.panel { background: #fff; border: 1px solid #e5e7eb; border-radius: 8px; padding: 1rem; margin-bottom: 1rem; }
.login { max-width: 360px; margin: 4rem auto; }
.login form { background: #fff; padding: 1.2rem; border-radius: 8px; border: 1px solid #e5e7eb; }
.role-select { max-width: 480px; margin: 2rem auto; text-align: center; }
.role-list { list-style: none; padding: 0; display: grid; gap: 0.5rem; }
.role-list button { width: 100%; padding: 0.7rem; font-size: 1rem; }
button { font: inherit; padding: 0.35rem 0.7rem; border-radius: 5px; border: 1px solid #2563eb; background: #2563eb; color: #fff; cursor: pointer; }
button.secondary, .topbar button, .row button, td button, .card header button { background: #fff; color: #1f2937; border-color: #9ca3af; }
button.link { background: none; border: none; color: #2563eb; padding: 0; text-decoration: underline; }
button:disabled { opacity: 0.5; cursor: default; }
.field { display: flex; flex-direction: column; gap: 0.2rem; margin: 0.3rem 0; }
.field > span { font-size: 0.8rem; color: #4b5563; }
.field.inline { flex-direction: row; align-items: center; gap: 0.4rem; margin: 0; }
.field.inline > span { color: #d1d5db; }
.field.check { flex-direction: row; align-items: center; }
.field input, .field select, .field textarea { font: inherit; padding: 0.3rem 0.4rem; border: 1px solid #d1d5db; border-radius: 4px; }
fieldset { border: 1px solid #e5e7eb; border-radius: 4px; margin: 0.3rem 0; padding: 0.3rem 0.6rem; }
legend { font-size: 0.8rem; color: #4b5563; }
.grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(220px, 1fr)); gap: 0.4rem 0.8rem; }
.two-col { display: grid; grid-template-columns: repeat(auto-fit, minmax(320px, 1fr)); gap: 1rem; margin-top: 0.5rem; }
.row { display: flex; gap: 0.5rem; align-items: center; flex-wrap: wrap; margin: 0.4rem 0; }
.action-form { border: 1px dashed #d1d5db; border-radius: 6px; padding: 0.5rem 0.8rem; margin: 0.5rem 0; background: #fafafa; }
.actions { margin-top: 0.5rem; }
.error { background: #fee2e2; color: #991b1b; border: 1px solid #fca5a5; padding: 0.5rem 0.7rem; border-radius: 5px; margin: 0.5rem 0; }
.notice { background: #dcfce7; color: #166534; border: 1px solid #86efac; padding: 0.5rem 0.7rem; border-radius: 5px; margin: 0.5rem 0; }
.warning { background: #fef3c7; color: #92400e; border: 1px solid #fcd34d; padding: 0.5rem 0.7rem; border-radius: 5px; margin: 0.5rem 0; }
.muted { color: #6b7280; }
.tag { display: inline-block; font-size: 0.75rem; padding: 0.1rem 0.45rem; border-radius: 999px; background: #e5e7eb; color: #374151; margin-left: 0.3rem; }
.tag.ok { background: #dcfce7; color: #166534; }
.tag.warn { background: #fef3c7; color: #92400e; }
.tag.danger { background: #fee2e2; color: #991b1b; }
table.data { width: 100%; border-collapse: collapse; margin: 0.4rem 0; font-size: 0.85rem; }
table.data th, table.data td { border-bottom: 1px solid #e5e7eb; padding: 0.3rem 0.4rem; text-align: left; vertical-align: top; }
table.data caption { text-align: left; font-weight: 600; padding: 0.2rem 0; }
