export class ApiError extends Error {
  status: number;
  code: string;
  constructor(status: number, code: string, message: string) {
    super(message);
    this.status = status;
    this.code = code;
  }
}

const TOKEN_KEY = "labsample.sessionToken";

export function getToken(): string | null {
  return localStorage.getItem(TOKEN_KEY);
}

export function setToken(token: string | null) {
  if (token) localStorage.setItem(TOKEN_KEY, token);
  else localStorage.removeItem(TOKEN_KEY);
}

type Listener = () => void;
const unauthorizedListeners = new Set<Listener>();
export function onUnauthorized(fn: Listener) {
  unauthorizedListeners.add(fn);
  return () => unauthorizedListeners.delete(fn);
}

export async function api<T = any>(op: string, body?: unknown, method: "POST" | "GET" = "POST"): Promise<T> {
  const headers: Record<string, string> = { "Content-Type": "application/json" };
  const token = getToken();
  if (token) headers.Authorization = `Bearer ${token}`;
  const res = await fetch(`/api/${op}`, {
    method,
    headers,
    body: method === "GET" ? undefined : JSON.stringify(body ?? {}),
  });
  let payload: any = {};
  try {
    payload = await res.json();
  } catch {
    payload = {};
  }
  if (!res.ok) {
    if (res.status === 401 && op !== "authenticate-user") {
      setToken(null);
      unauthorizedListeners.forEach((fn) => fn());
    }
    throw new ApiError(res.status, payload.code ?? "error", payload.error ?? res.statusText);
  }
  return (payload.data ?? payload) as T;
}

export function newKey(): string {
  if (typeof crypto !== "undefined" && "randomUUID" in crypto) return crypto.randomUUID();
  return `${Date.now()}-${Math.random().toString(16).slice(2)}`;
}

export function nowIso(): string {
  return new Date().toISOString().replace(/\.\d{3}Z$/, "Z");
}

export function toIso(local: string): string {
  if (!local) return "";
  const d = new Date(local);
  if (Number.isNaN(d.getTime())) return local;
  return d.toISOString().replace(/\.\d{3}Z$/, "Z");
}

export function fmt(ts?: string | null): string {
  if (!ts) return "—";
  const d = new Date(ts);
  if (Number.isNaN(d.getTime())) return ts;
  return d.toLocaleString();
}

export function localInput(offsetMinutes: number): string {
  const d = new Date(Date.now() + offsetMinutes * 60_000);
  const pad = (n: number) => String(n).padStart(2, "0");
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`;
}
export type Role =
  | "administrator"
  | "dispatcher"
  | "requester"
  | "collection_professional"
  | "delivery_partner"
  | "node_handler"
  | "laboratory_team";

export const ROLE_LABELS: Record<string, string> = {
  administrator: "Administrator",
  dispatcher: "Dispatcher",
  requester: "Requester",
  collection_professional: "Certified collection professional",
  delivery_partner: "Relay courier",
  node_handler: "Node handler",
  laboratory_team: "Laboratory intake operator",
};

export const ALL_ROLES: Role[] = [
  "administrator",
  "dispatcher",
  "requester",
  "collection_professional",
  "delivery_partner",
  "node_handler",
  "laboratory_team",
];

export interface Coordinate {
  latitude: number;
  longitude: number;
}

export interface Session {
  userId: string;
  username: string;
  fullName?: string;
  roles: string[];
  activeRole: string;
  roleSelectionRequired: boolean;
}

export interface TimelineEntry {
  eventId: number;
  action: string;
  actorId: string;
  role: string;
  entityType: string;
  entityId: string;
  success: boolean;
  occurredAt: string;
  details: Record<string, unknown>;
}

export interface Capacity {
  capacityUnits: number;
  reservedUnits: number;
  availableUnits: number;
  cooledCapacityUnits: number;
  cooledReservedUnits: number;
  cooledAvailableUnits: number;
}

export interface WorkItem {
  kind: "sample" | "journey" | "collection" | "transport" | "node" | "laboratory";
  status: string;
  history: TimelineEntry[];
  sampleId?: string;
  requestId?: string;
  journeyId?: string;
  assignmentId?: string;
  fromLocationId?: string;
  toLocationId?: string;
  sequence?: number;
  offerExpiresAt?: string;
  nodeId?: string;
  laboratoryId?: string;
  incomingFromLocationId?: string;
  outgoingToLocationId?: string;
