package main

import (
        "context"
        "errors"
        "flag"
        "log"
        "net/http"
        "os"
        "os/signal"
        "strconv"
        "syscall"
        "time"

        "labsample/internal/app"
)

func envOr(key, def string) string {
        if v := os.Getenv(key); v != "" {
                return v
        }
        return def
}

func envSeconds(key string, def int) time.Duration {
        if v := os.Getenv(key); v != "" {
                if n, err := strconv.Atoi(v); err == nil && n > 0 {
                        return time.Duration(n) * time.Second
                }
        }
        return time.Duration(def) * time.Second
}

func main() {
        reset := flag.Bool("reset", false, "clear all application-owned state, apply the schema, and exit")
        flag.Parse()

        cfg := app.Config{
                DatabaseURL:   envOr("DATABASE_URL", "postgresql://arena:arena@127.0.0.1:5432/arena?sslmode=disable"),
                Addr:          envOr("LISTEN_ADDR", "127.0.0.1:"+envOr("PORT", "8080")),
                AdminUsername: os.Getenv("ADMIN_USERNAME"),
                AdminPassword: os.Getenv("ADMIN_PASSWORD"),
                StaticDir:     envOr("STATIC_DIR", "frontend/dist"),
                MapAssetsDir:  envOr("MAP_ASSETS_DIR", "/opt/arena/map-assets"),
                OfferTimeout:  envSeconds("OFFER_TIMEOUT_SECONDS", 60),
                NoWorkerGrace: envSeconds("NO_WORKER_GRACE_SECONDS", 120),
                StaleAfter:    envSeconds("LOCATION_STALE_SECONDS", 600),
                SessionTTL:    envSeconds("SESSION_TTL_SECONDS", 86400),
        }
        ctx, cancel := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
        defer cancel()

        if *reset {
                if err := app.Reset(ctx, cfg.DatabaseURL); err != nil {
                        log.Fatalf("reset failed: %v", err)
                }
                log.Printf("reset complete: schema materialised in %s", cfg.DatabaseURL)
                return
        }

        a, err := app.New(ctx, cfg)
        if err != nil {
                log.Fatalf("startup failed: %v", err)
        }
        defer a.Close()
        go a.RunScheduler(ctx)

        srv := &http.Server{Addr: cfg.Addr, Handler: a.Handler(), ReadHeaderTimeout: 10 * time.Second}
        go func() {
                <-ctx.Done()
                shutdownCtx, c := context.WithTimeout(context.Background(), 5*time.Second)
                defer c()
                _ = srv.Shutdown(shutdownCtx)
        }()
        log.Printf("lab sample pickup & delivery listening on http://%s", cfg.Addr)
        if err := srv.ListenAndServe(); err != nil && !errors.Is(err, http.ErrServerClosed) {
                log.Fatalf("server: %v", err)
        }
}
