func (a *App) expireOffers(tx *Tx) {
        for _, id := range sortedKeys(tx.st.Assignments) {
                asg := tx.st.Assignments[id]
                if asg.Status != AsgOffered || asg.OfferExpiresAt == nil || asg.OfferExpiresAt.After(tx.now) {
                        continue
                }
                s := tx.st.Samples[asg.SampleID]
                w := tx.st.Users[asg.WorkerID]
                if s != nil {
                        tx.SampleEvent(s, "offer_expired", "assignment", asg.ID, map[string]any{"assignmentId": asg.ID, "workerId": asg.WorkerID, "treatedAs": "declined"})
                }
                asg.DeclinedBy = append(asg.DeclinedBy, asg.WorkerID)
                asg.Status = AsgPending
                asg.WorkerID = ""
                asg.OfferExpiresAt = nil
                tx.MarkAssignment(asg)
                if w != nil {
                        a.recordDecline(tx, w)
                }
                a.offer(tx, asg)
        }
}

